import socket
import time
import signal
import sys
import logging
from threading import Thread, Lock

try:
    from gpiozero import DigitalOutputDevice, PWMOutputDevice, MCP3008
except ImportError:
    DigitalOutputDevice = None
    PWMOutputDevice = None
    MCP3008 = None

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)

MOTOR_A_FORWARD_PIN = 27
MOTOR_A_BACKWARD_PIN = 22
MOTOR_B_CLOCKWISE_PIN = 24
MOTOR_B_COUNTERCLOCKWISE_PIN = 25
MOTOR_A_ENABLE_PIN = 17
MOTOR_B_ENABLE_PIN = 23
SPI_CLK_PIN = 11
SPI_MOSI_PIN = 10
SPI_MISO_PIN = 9
SPI_CS_1_PIN = 8
SPI_CS_2_PIN = 7
DEFAULT_THRESHOLD = 30
DEFAULT_WATERING_DURATION = 30
SERVER_PORT = 12345
SENSOR_READINGS = 5
SENSOR_DELAY = 0.02
HEALTH_CHECK_INTERVAL = 60

shutdown_event = False
motor_a_forward = None
motor_a_backward = None
motor_b_clockwise = None
motor_b_counterclockwise = None
motor_a_enable = None
motor_b_enable = None
spi1 = None
spi2 = None
server_socket = None
sensor1 = None
sensor2 = None
last_health_check = 0.0
health_lock = Lock()


def signal_handler(signum, frame):
    global shutdown_event
    logger.info(f"Signal {signum} received, shutting down...")
    shutdown_event = True


def initialize_gpio():
    global motor_a_forward, motor_a_backward, motor_b_clockwise, motor_b_counterclockwise, motor_a_enable, motor_b_enable, spi1, spi2
    global sensor1, sensor2
    motor_a_forward = motor_a_backward = motor_b_clockwise = motor_b_counterclockwise = motor_a_enable = motor_b_enable = None
    spi1 = spi2 = None
    try:
        if DigitalOutputDevice is not None:
            motor_a_forward = DigitalOutputDevice(MOTOR_A_FORWARD_PIN, initial_value=False)
            motor_a_backward = DigitalOutputDevice(MOTOR_A_BACKWARD_PIN, initial_value=False)
            motor_b_clockwise = DigitalOutputDevice(MOTOR_B_CLOCKWISE_PIN, initial_value=False)
            motor_b_counterclockwise = DigitalOutputDevice(MOTOR_B_COUNTERCLOCKWISE_PIN, initial_value=False)
            motor_a_enable = PWMOutputDevice(MOTOR_A_ENABLE_PIN, frequency=1000)
            motor_b_enable = PWMOutputDevice(MOTOR_B_ENABLE_PIN, frequency=1000)
            motor_a_enable.value = 0
            motor_b_enable.value = 0
            motor_a_forward.value = 0
            motor_a_backward.value = 0
            motor_b_clockwise.value = 0
            motor_b_counterclockwise.value = 0
            logger.info("GPIO initialized successfully.")
        else:
            logger.warning("gpiozero not available; running in degraded mode.")
    except Exception as e:
        logger.error(f"GPIO initialization failed: {e}")


def initialize_adc():
    global sensor1, sensor2
    try:
        if MCP3008 is not None:
            sensor1 = MCP3008(channel=0)
            sensor2 = MCP3008(channel=1)
            logger.info("ADC initialized successfully.")
        else:
            logger.warning("MCP3008 not available; running in degraded mode.")
    except Exception as e:
        logger.error(f"ADC initialization failed: {e}")


def read_moisture_level(sensor, channel):
    if sensor is None:
        return -1
    try:
        readings = []
        for _ in range(SENSOR_READINGS):
            readings.append(sensor.value)
            time.sleep(SENSOR_DELAY)
        return sum(readings) / len(readings)
    except Exception as e:
        logger.error(f"Error reading moisture level from sensor: {e}")
        return -1


def read_sensor_data(sensor1, sensor2):
    moisture1 = read_moisture_level(sensor1, 0)
    moisture2 = read_moisture_level(sensor2, 1)
    return moisture1, moisture2


def control_motor(motor, direction, duration):
    if motor is None:
        return
    try:
        if direction == "forward":
            motor_a_forward.value = 1
            motor_a_backward.value = 0
            motor_b_clockwise.value = 0
            motor_b_counterclockwise.value = 1
        elif direction == "backward":
            motor_a_forward.value = 0
            motor_a_backward.value = 1
            motor_b_clockwise.value = 1
            motor_b_counterclockwise.value = 0
        else:
            logger.warning("Invalid motor direction.")
            return
        motor.enable.value = 1
        time.sleep(duration)
        motor.enable.value = 0
    except Exception as e:
        logger.error(f"Error controlling motor: {e}")


def watering_system_control(moisture1, moisture2, threshold, watering_duration):
    if moisture1 == -1 or moisture2 == -1:
        logger.warning("Skipping watering due to sensor error.")
        return
    if moisture1 < threshold and moisture2 < threshold:
        logger.info("Moisture levels low. Watering plant 1.")
        control_motor(motor_a_enable, "forward", watering_duration)
        time.sleep(watering_duration)
        control_motor(motor_a_enable, "off", watering_duration)
        logger.info("Watering plant 1 complete.")
    elif moisture1 < threshold:
        logger.info("Moisture level low for plant 1. Watering in progress...")
        control_motor(motor_a_enable, "forward", watering_duration)
        time.sleep(watering_duration)
        control_motor(motor_a_enable, "off", watering_duration)
        logger.info("Watering plant 1 complete.")
    elif moisture2 < threshold:
        logger.info("Moisture level low for plant 2. Watering in progress...")
        control_motor(motor_b_enable, "forward", watering_duration)
        time.sleep(watering_duration)
        control_motor(motor_b_enable, "off", watering_duration)
        logger.info("Watering plant 2 complete.")
    else:
        logger.info("Moisture levels adequate. No watering needed.")


def handle_client(client_socket):
    try:
        data = client_socket.recv(1024).decode('utf-8')
        logger.info(f"Received data: {data}")
        if "WATER_PLANT_1" in data:
            moisture1, moisture2 = read_sensor_data(sensor1, sensor2)
            watering_system_control(moisture1, moisture2, DEFAULT_THRESHOLD, DEFAULT_WATERING_DURATION)
        elif "WATER_PLANT_2" in data:
            moisture1, moisture2 = read_sensor_data(sensor1, sensor2)
            watering_system_control(moisture1, moisture2, DEFAULT_THRESHOLD, DEFAULT_WATERING_DURATION)
        elif "GET_SENSOR_DATA" in data:
            moisture1, moisture2 = read_sensor_data(sensor1, sensor2)
            client_socket.sendall(f"{moisture1},{moisture2}".encode('utf-8'))
        elif "SET_THRESHOLD" in data:
            try:
                threshold = int(data.split()[-1])
                if 0 <= threshold <= 100:
                    logger.info(f"Threshold set to: {threshold}")
                else:
                    logger.error("Invalid threshold value.")
            except ValueError:
                logger.error("Invalid threshold value.")
        elif "SET_WATERING_DURATION" in data:
            try:
                duration = int(data.split()[-1])
                if duration > 0:
                    logger.info(f"Watering duration set to: {duration}")
                else:
                    logger.error("Invalid watering duration.")
            except ValueError:
                logger.error("Invalid watering duration.")
        else:
            logger.warning("Unknown command received.")
    except Exception as e:
        logger.error(f"Error handling client: {e}")
    finally:
        client_socket.close()


def start_server():
    global server_socket
    try:
        server_socket = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        server_socket.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
        server_socket.bind(('0.0.0.0', SERVER_PORT))
        server_socket.listen(5)
        server_socket.settimeout(1.0)
        logger.info(f"Server listening on port {SERVER_PORT}")
        while not shutdown_event:
            try:
                client_socket, address = server_socket.accept()
                client_thread = Thread(target=handle_client, args=(client_socket,), daemon=True)
                client_thread.start()
            except socket.timeout:
                continue
            except Exception as e:
                logger.error(f"Server error: {e}")
    except Exception as e:
        logger.error(f"Failed to start server: {e}")
    finally:
        if server_socket:
            server_socket.close()
            logger.info("Server stopped.")


def periodic_health_check():
    global last_health_check
    while not shutdown_event:
        try:
            with health_lock:
                current_time = time.time()
                if current_time - last_health_check > HEALTH_CHECK_INTERVAL:
                    logger.info("System health check: Sensors, GPIO, and network connectivity.")
                    if sensor1 is None or sensor2 is None:
                        logger.warning("One or more ADC sensors unavailable.")
                    if motor_a_forward is None or motor_a_backward is None or motor_a_enable is None:
                        logger.warning("Motor A GPIO unavailable.")
                    if motor_b_clockwise is None or motor_b_counterclockwise is None or motor_b_enable is None:
                        logger.warning("Motor B GPIO unavailable.")
                    if server_socket and not server_socket.is_connected():
                        logger.warning("Server disconnected.")
                    time.sleep(HEALTH_CHECK_INTERVAL)
                    last_health_check = current_time
        except Exception as e:
            logger.error(f"Error during periodic health check: {e}")
            time.sleep(5)


def cleanup():
    logger.info("Cleaning up resources...")
    if motor_a_forward is not None:
        motor_a_forward.close()
    if motor_a_backward is not None:
        motor_a_backward.close()
    if motor_b_clockwise is not None:
        motor_b_clockwise.close()
    if motor_b_counterclockwise is not None:
        motor_b_counterclockwise.close()
    if motor_a_enable is not None:
        motor_a_enable.close()
    if motor_b_enable is not None:
        motor_b_enable.close()
    if spi1 is not None:
        spi1.close()
    if spi2 is not None:
        spi2.close()
    if server_socket and server_socket.is_connected():
        server_socket.close()
    logger.info("Cleanup complete.")


def main():
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)
    initialize_gpio()
    initialize_adc()
    start_server()
    periodic_thread = Thread(target=periodic_health_check, daemon=True)
    periodic_thread.start()
    try:
        while not shutdown_event:
            time.sleep(1)
    except KeyboardInterrupt:
        shutdown_event = True
    finally:
        cleanup()


if __name__ == "__main__":
    main()

