import spidev
import time
import datetime
import socket
import json
import signal
import sys
from gpiozero import Buzzer

# Constants
SPI_BUS = 0
SPI_DEVICE = 0
SPI_MAX_SPEED_HZ = 1000000
ADC_CHANNELS = {0: "MQ-4 (CH4)", 1: "MQ-7 (CO)", 2: "MQ-135 (VOC)"}
ALERT_THRESHOLD_PPM = {"CH4": 50.0, "CO": 25.0, "VOC": 100.0}
BUZZER_PIN = 17
SERVER_IP = "127.0.0.1"
SERVER_PORT = 12345
LOG_FILE = "gas_sensor_data.csv"
CALIBRATION_READINGS = 10
CALIBRATION_DELAY = 3
LOG_INTERVAL = 60

# Global state
spi = None
buzzer = None
running = True

def signal_handler(sig, frame):
    global running
    print("\nSignal received, shutting down...")
    running = False

def initialize_spi():
    global spi
    try:
        spi = spidev.SpiDev()
        spi.open(SPI_BUS, SPI_DEVICE)
        spi.max_speed_hz = SPI_MAX_SPEED_HZ
        spi.mode = 0
        return True
    except Exception as e:
        print(f"Error initializing SPI: {e}")
        return False

def initialize_buzzer():
    global buzzer
    try:
        buzzer = Buzzer(BUZZER_PIN)
        return True
    except Exception as e:
        print(f"Error initializing buzzer: {e}")
        return False

def read_adc(channel):
    try:
        adc = spi.xfer2([1, (8 + channel) << 4, 0])
        data = ((adc[1] & 3) << 8) + adc[2]
        return data
    except Exception as e:
        print(f"Error reading ADC channel {channel}: {e}")
        return None

def calculate_gas_concentration(adc_value, r0, baseline_adc):
    if baseline_adc is None:
        return None
    if baseline_adc == 0:
        return None
    return (adc_value / baseline_adc) * (r0 / 1000.0)

def calibrate_sensors():
    print("Calibrating sensors...")
    data = {}
    for channel, name in ADC_CHANNELS.items():
        readings = []
        for _ in range(CALIBRATION_READINGS):
            adc = read_adc(channel)
            if adc is not None:
                readings.append(adc)
            time.sleep(CALIBRATION_DELAY)
        if readings:
            data[name] = sum(readings) / len(readings)
        else:
            data[name] = None
    print("Calibration complete.")
    return data

def log_data(timestamp, data):
    try:
        with open(LOG_FILE, "a") as f:
            f.write(f"{timestamp},{data}\n")
    except Exception as e:
        print(f"Error writing to log file: {e}")

def transmit_data(data):
    try:
        with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as s:
            s.settimeout(5)
            s.connect((SERVER_IP, SERVER_PORT))
            json_data = json.dumps(data)
            s.sendall(json_data.encode())
    except socket.timeout:
        print("Error: Connection timed out.")
    except socket.error as e:
        print(f"Error transmitting data: {e}")
    except Exception as e:
        print(f"Error transmitting data: {e}")

def main():
    global running
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    if not initialize_spi():
        print("Failed to initialize SPI. Exiting.")
        sys.exit(1)

    if not initialize_buzzer():
        print("Failed to initialize buzzer. Exiting.")
        spi.close()
        sys.exit(1)

    baseline_data = calibrate_sensors()
    if any(v is None for v in baseline_data.values()):
        print("Failed to calibrate sensors. Exiting.")
        spi.close()
        sys.exit(1)

    print("Starting gas sensor monitoring...")
    while running:
        timestamp = datetime.datetime.now().isoformat()
        data = {}
        for channel, name in ADC_CHANNELS.items():
            adc = read_adc(channel)
            if adc is not None:
                r0 = baseline_data[name]
                baseline_adc = read_adc(channel)
                gas_concentration = calculate_gas_concentration(adc, r0, baseline_adc)
                data[name] = {"ADC": adc, "Concentration": gas_concentration, "R0": r0, "Baseline_ADC": baseline_adc}
