import spidev
import RPi.GPIO as GPIO
import time
import logging
import sys

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

class SmartGardenController:
    """Controls a smart garden using an MCP3008 ADC and a relay pump."""

    def __init__(self, spi_bus=0, spi_device=0, pump_pin=18, dry_threshold=450):
        self.spi_bus = spi_bus
        self.spi_device = spi_device
        self.pump_pin = pump_pin
        self.dry_threshold = dry_threshold
        self.spi = None
        self.pump_active = False

        try:
            self.spi = spidev.SpiDev()
            self.spi.open(self.spi_bus, self.spi_device)
            self.spi.max_speed_hz = 1350000
            self.spi.mode = 0
            logging.info("SPI initialized on bus %d, device %d", self.spi_bus, self.spi_device)
        except Exception as e:
            logging.error("Failed to initialize SPI: %s", e)
            raise

        try:
            GPIO.setmode(GPIO.BCM)
            GPIO.setup(self.pump_pin, GPIO.OUT, initial=GPIO.LOW)
            logging.info("GPIO pin %d configured as output", self.pump_pin)
        except Exception as e:
            logging.error("Failed to initialize GPIO: %s", e)
            self.close()
            raise

    def read_moisture(self):
        """Read soil moisture from MCP3008 channel 0 (single-ended)."""
        if self.spi is None:
            raise RuntimeError("SPI not initialized")
        try:
            # MCP3008 command: start bit (1), single-ended mode (1), channel select (3 bits), then 0 padding
            # Channel 0: command byte = 0b00011000 = 0x18
            command = [0x18, 0x00, 0x00]
            response = self.spi.xfer2(command)
            # Response: first byte is garbage, second byte has 2 LSBs of data, third byte has 8 bits
            raw_value = ((response[1] & 0x03) << 8) | response[2]
            logging.debug("Raw moisture value: %d", raw_value)
            return raw_value
        except Exception as e:
            logging.error("SPI read error: %s", e)
            raise

    def run_pump(self, seconds):
        """Activate the pump relay for a given duration."""
        if self.pump_active:
            logging.warning("Pump already active")
            return
        try:
            GPIO.output(self.pump_pin, GPIO.HIGH)
            self.pump_active = True
            logging.info("Pump activated for %d seconds", seconds)
            time.sleep(seconds)
        except Exception as e:
            logging.error("Pump activation error: %s", e)
        finally:
            self.pump_active = False
            GPIO.output(self.pump_pin, GPIO.LOW)
            logging.info("Pump deactivated")

    def irrigation_cycle(self):
        """Perform one irrigation cycle: read moisture, log, water if dry."""
        try:
            moisture = self.read_moisture()
            logging.info("Soil moisture: %d", moisture)
            if moisture > self.dry_threshold:
                self.run_pump(2)
                logging.info("Irrigation cycle completed")
                return True
            else:
                logging.info("Soil moisture sufficient, no watering")
                return False
        except Exception as e:
            logging.error("Irrigation cycle error: %s", e)
            return False

    def close(self):
        """Release SPI and GPIO resources."""
        if self.spi is not None:
            try:
                self.spi.close()
                logging.info("SPI closed")
            except Exception as e:
                logging.error("Error closing SPI: %s", e)
            self.spi = None
        try:
            GPIO.cleanup()
            logging.info("GPIO cleaned up")
        except Exception as e:
            logging.error("Error cleaning GPIO: %s", e)


def schedule_cycles(controller, cycle_count, interval_seconds):
    """Run a fixed number of irrigation cycles."""
    for cycle_index in range(cycle_count):
        if controller.irrigation_cycle():
            logging.info("Cycle %d completed successfully", cycle_index + 1)
        else:
            logging.warning("Cycle %d failed", cycle_index + 1)
        if cycle_index < cycle_count - 1:
            time.sleep(interval_seconds)


if __name__ == "__main__":
    controller = None
    try:
        controller = SmartGardenController()
        schedule_cycles(controller, 10, 3)
    except KeyboardInterrupt:
        logging.info("Interrupted by user")
    except Exception as e:
        logging.error("Fatal error: %s", e)
        sys.exit(1)
    finally:
        if controller is not None:
            controller.close()

