                    logging.info(f"Motion detected at {timestamp} with frame shape {frame.shape}")
                    self.motion_queue.task_done()
                except queue.Empty:
                    pass
        except KeyboardInterrupt:
            logging.info("Keyboard interrupt received.")
        finally:
            self.stop()

