import numpy as np
import signal
import sys
import time
from picamera2 import Picamera2

running = True

def signal_handler(signum, frame):
    global running
    running = False

signal.signal(signal.SIGINT, signal_handler)
signal.signal(signal.SIGTERM, signal_handler)

def main():
    global running

    cam1 = None
    cam2 = None

    try:
        cam1 = Picamera2(0)
        cam2 = Picamera2(1)

        config1 = cam1.create_preview_configuration(
            main={"size": (640, 480), "format": "RGB888"}
        )
        config2 = cam2.create_preview_configuration(
            main={"size": (640, 480), "format": "RGB888"}
        )

        cam1.configure(config1)
        cam2.configure(config2)

        cam1.start()
        cam2.start()

        cam1.set_controls({"FrameDurationLimits": (33333, 33333)})
        cam2.set_controls({"FrameDurationLimits": (33333, 33333)})

        time.sleep(2.0)

        while running:
            frame1 = cam1.capture_array()
            frame2 = cam2.capture_array()

            if frame1 is None or frame2 is None:
                print("Error: Failed to capture frame from one or both cameras.", file=sys.stderr)
                break

            if frame1.shape != (480, 640, 3):
                print("Error: Frame1 shape mismatch.", file=sys.stderr)
                break
            if frame2.shape != (480, 640, 3):
                print("Error: Frame2 shape mismatch.", file=sys.stderr)
                break

            combined = np.hstack((frame1, frame2))
            cv2.imshow("Dual CSI Cameras", combined)

            key = cv2.waitKey(30) & 0xFF
            if key == 27 or cv2.getWindowProperty("Dual CSI Cameras", cv2.WND_PROP_VISIBLE) < 1:
                break

    except Exception as e:
        print(f"Error: {e}", file=sys.stderr)

    finally:
        if cam1 is not None:
            try:
                cam1.stop()
            except Exception:
                pass
        if cam2 is not None:
            try:
                cam2.stop()
            except Exception:
                pass
        cv2.destroyAllWindows()

if __name__ == "__main__":
    main()

