#!/usr/bin/env python3
"""
Wildlife Camera System for Raspberry Pi
Uses PIR motion sensor (HC-SR501) on GPIO 4, picamera2 for video capture,
and gpiozero for edge detection. Logs to config.ini and a local log file.
"""

import os
import sys
import time
import signal
import logging
import configparser
from datetime import datetime
from pathlib import Path

from gpiozero import MotionSensor
from picamera2 import Picamera2
from picamera2.encoders import H264Encoder
from picamera2.outputs import FileOutput

# ---------------------------------------------------------------------------
# Constants
# ---------------------------------------------------------------------------
DEFAULT_CONFIG = {
    "resolution": "640x480",
    "frame_rate": "20",
    "image_quality": "85",
    "video_bitrate": "1700000",
    "gpio_pin": "4",
    "motion_delay": "2",
    "storage_directory": "/home/pi/wildlife_media",
    "disk_space_threshold_mb": "500",
    "log_file": "/var/log/wildlifecam/wildlifecam.log",
    "log_level": "INFO",
}

# ---------------------------------------------------------------------------
# Global state for cleanup
# ---------------------------------------------------------------------------
camera = None
pir = None
running = True


def signal_handler(signum, frame):
    """Handle SIGINT/SIGTERM for graceful shutdown."""
    global running
    logging.info(f"Received signal {signum}, shutting down...")
    running = False


def setup_logging(log_file, log_level):
    """Configure logging to file and console."""
    log_dir = Path(log_file).parent if Path(log_file).parent else Path("./logs")
    log_dir.mkdir(parents=True, exist_ok=True)
    log_file = str(log_dir / log_file)
    try:
        logging.basicConfig(
            filename=log_file,
            level=getattr(logging, log_level.upper(), logging.INFO),
            format="%(asctime)s - %(levelname)s - %(message)s",
        )
        logging.info("Logging initialized.")
    except (PermissionError, OSError) as e:
        logging.warning(f"Cannot write to {log_file}: {e}. Falling back to ./logs.")
        log_file = str(Path("./logs") / log_file)
        try:
            logging.basicConfig(
                filename=log_file,
                level=getattr(logging, log_level.upper(), logging.INFO),
                format="%(asctime)s - %(levelname)s - %(message)s",
            )
            logging.info("Logging initialized in fallback directory.")
        except (PermissionError, OSError) as e2:
            logging.error(f"Cannot write to fallback log: {e2}. Logging disabled.")
            logging.shutdown()


def load_config(config_file="config.ini"):
    """Load configuration from INI file, creating defaults if missing."""
    config = configparser.ConfigParser()
    if not config.read(config_file):
        logging.warning(f"Config file {config_file} not found. Creating with defaults.")
        config["DEFAULT"] = DEFAULT_CONFIG
        try:
            with open(config_file, "w") as f:
                config.write(f)
            logging.info("Created default config file.")
        except OSError as e:
            logging.error(f"Failed to write default config: {e}")
    return config


def parse_resolution(res_str):
    """Parse 'widthxheight' string into (width, height) tuple."""
    try:
        w, h = map(int, res_str.split("x"))
        return w, h
    except ValueError:
        logging.error(f"Invalid resolution format: {res_str}. Using default {DEFAULT_CONFIG['resolution']}")
        return DEFAULT_CONFIG["resolution"].split("x")


def parse_frame_rate(frate_str):
    """Parse 'fps' string into float."""
    try:
        return float(frate_str)
    except ValueError:
        logging.error(f"Invalid frame rate: {frate_str}. Using default {DEFAULT_CONFIG['frame_rate']}")
        return DEFAULT_CONFIG["frame_rate"]


def parse_image_quality(qual_str):
    """Parse 'quality' string into int 0-100."""
    try:
        return int(qual_str)
    except ValueError:
        logging.error(f"Invalid image quality: {qual_str}. Using default {DEFAULT_CONFIG['image_quality']}")
        return DEFAULT_CONFIG["image_quality"]


def parse_video_bitrate(bitrate_str):
    """Parse bitrate string into int."""
    try:
        return int(bitrate_str)
    except ValueError:
        logging.error(f"Invalid bitrate: {bitrate_str}. Using default {DEFAULT_CONFIG['video_bitrate']}")
        return DEFAULT_CONFIG["video_bitrate"]


def parse_disk_space_threshold_mb(threshold_str):
    """Parse 'MB' string into int."""
    try:
        return int(threshold_str)
    except ValueError:
        logging.error(f"Invalid disk space threshold: {threshold_str}. Using default {DEFAULT_CONFIG['disk_space_threshold_mb']}")
        return DEFAULT_CONFIG["disk_space_threshold_mb"]


def parse_gpio_pin(pin_str):
    """Parse GPIO pin string into int."""
    try:
        return int(pin_str)
    except ValueError:
        logging.error(f"Invalid GPIO pin: {pin_str}. Using default {DEFAULT_CONFIG['gpio_pin']}")
        return DEFAULT_CONFIG["gpio_pin"]


def parse_motion_delay(delay_str):
    """Parse delay string into float seconds."""
    try:
        return float(delay_str)
    except ValueError:
        logging.error(f"Invalid motion delay: {delay_str}. Using default {DEFAULT_CONFIG['motion_delay']}")
        return DEFAULT_CONFIG["motion_delay"]


def get_storage_directory(config):
    return config.get("DEFAULT", "storage_directory", fallback="/home/pi/wildlife_media")


def get_disk_space_threshold_mb(config):
    return config.getint("DEFAULT", "disk_space_threshold_mb", fallback=DEFAULT_CONFIG["disk_space_threshold_mb"])


def get_log_file(config):
    return config.get("DEFAULT", "log_file", fallback=DEFAULT_CONFIG["log_file"])


def get_log_level(config):
    return config.get("DEFAULT", "log_level", fallback=DEFAULT_CONFIG["log_level"])


def cleanup():
    """Release all hardware resources."""
    global camera, pir
    if camera is not None:
        try:
            camera.stop()
            camera.close()
            logging.info("Camera closed.")
        except Exception as e:
            logging.error(f"Error closing camera: {e}")
        camera = None
    if pir is not None:
        try:
            pir.close()
            logging.info("PIR sensor closed.")
        except Exception as e:
            logging.error(f"Error closing PIR sensor: {e}")
        pir = None
    logging.info("Cleanup complete.")


def main():
    global camera, pir, running

    config = load_config()

    setup_logging(get_log_file(config), get_log_level(config))

    resolution = parse_resolution(config.get("resolution", DEFAULT_CONFIG["resolution"]))
    frame_rate = parse_frame_rate(config.get("frame_rate", DEFAULT_CONFIG["frame_rate"]))
    image_quality = parse_image_quality(config.get("image_quality", DEFAULT_CONFIG["image_quality"]))
    video_bitrate = parse_video_bitrate(config.get("video_bitrate", DEFAULT_CONFIG["video_bitrate"]))
    gpio_pin = parse_gpio_pin(config.get("gpio_pin", DEFAULT_CONFIG["gpio_pin"]))
    motion_delay = parse_motion_delay(config.get("motion_delay", DEFAULT_CONFIG["motion_delay"]))
    storage_directory = get_storage_directory(config)
    disk_space_threshold_mb = get_disk_space_threshold_mb(config)

    # -----------------------------------------------------------------------
    # GPIO setup
    # -----------------------------------------------------------------------
    try:
        pir = MotionSensor(gpio_pin)
        logging.info(f"PIR sensor initialized on GPIO {gpio_pin}.")
    except Exception as e:
        logging.error(f"Failed to initialize PIR sensor on GPIO {gpio_pin}: {e}")
        sys.exit(1)

    # -----------------------------------------------------------------------
    # Camera setup
    # -----------------------------------------------------------------------
    try:
        camera = Picamera2()
        camera_config = camera.create_video_configuration(
            main={"size": resolution, "format": "RGB888"},
            controls={"FrameRate": frame_rate},
        )
        camera.configure(camera_config)
        camera.start()
        logging.info("Camera initialized.")
    except Exception as e:
        logging.error(f"Failed to initialize camera: {e}")
        cleanup()
        sys.exit(1)

    # -----------------------------------------------------------------------
    # Signal handlers
    # -----------------------------------------------------------------------
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    # -----------------------------------------------------------------------
    # Main loop
    # -----------------------------------------------------------------------
    try:
        while running:
            try:
                pir.wait_for_motion()
                logging.info("Motion detected!")

                timestamp = datetime.now().strftime("%Y%m%d_%H%M%S")
                storage_path = Path(storage_directory)
                storage_path.mkdir(parents=True, exist_ok=True)

                # Delete oldest files if disk space is low
                if disk_space_threshold_mb > 0:
                    try:
                        files = [
                            f for f in storage_path.iterdir()
                            if f.is_file() and f.suffix in (".jpg", ".jpeg", ".png", ".mp4")
                        ]
                        if files:
                            files.sort(key=lambda f: f.stat().st_mtime)
                            for f in files:
                                if disk_space_threshold_mb > 0 and f.stat().st_size > 0:
                                    f.unlink()
                                    logging.info(f"Deleted old file: {f}")
                                    disk_space = get_disk_space()
                                    if disk_space < disk_space_threshold_mb:
                                        logging.warning(
                                            f"Disk space low. Deleted {f}. "
                                            f"Available space: {disk_space:.1f} MB"
                                        )
                    except Exception as e:
                        logging.error(f"Error managing storage: {e}")

                # Capture images
                for i in range(3):
                    if not running:
                        break
                    filename = storage_path / f"{timestamp}_{i+1:03d}.jpg"
                    try:
                        camera.capture_file(str(filename), format="jpeg", quality=image_quality)
                        logging.info(f"Captured image: {filename}")
                    except Exception as e:
                        logging.error(f"Error capturing image {filename}: {e}")
                    time.sleep(0.5)

                # Capture video
                if not running:
                    break
                filename = storage_path / f"{timestamp}_video.mp4"
                try:
                    encoder = H264Encoder(bitrate=video_bitrate)
                    camera.start_encoder(encoder, FileOutput(str(filename)))
                    time.sleep(5)
                    camera.stop_encoder()
                    logging.info(f"Captured video: {filename}")
                except Exception as e:
                    logging.error(f"Error capturing video: {e}")

                # Wait for motion to clear before next trigger
                if not running:
                    break
                time.sleep(motion_delay)

            except Exception as e:
                logging.error(f"Error in main loop: {e}")
                time.sleep(1)

    finally:
        cleanup()


def get_disk_space():
    """Return available disk space in MB."""
    try:
        statvfs = os.statvfs("/")
        available_mb = (statvfs.f_bavail * statvfs.f_frsize) / (1024 * 1024)
        return available_mb
    except Exception as e:
        logging.error(f"Error getting disk space: {e}")
        return 0


if __name__ == "__main__":
    main()

