import cv2
import numpy as np
import serial
import serial.tools.list_ports
import signal
import sys

SERIAL_PORT = "/dev/ttyACM0"
BAUD_RATE = 9600
ROI_SIZE = 100
ROI_HALF_EXTENT = 50
MIN_CONTOUR_AREA = 500
SERIAL_WRITE_TIMEOUT = 1.0

running = True
cap = None
ser = None


def signal_handler(signum, frame):
    global running
    running = False


def initialize_camera():
    global cap
    cap = cv2.VideoCapture(0)
    if not cap.isOpened():
        print("Error: Could not open camera.")
        return False
    return True


def initialize_serial():
    global ser
    available_ports = [p.device for p in serial.tools.list_ports.comports()]
    if not available_ports:
        print("Warning: No serial ports found.")
        return False
    for port in available_ports:
        if port == SERIAL_PORT:
            try:
                ser = serial.Serial(port, BAUD_RATE, timeout=SERIAL_WRITE_TIMEOUT)
                print(f"Serial port {SERIAL_PORT} opened at {BAUD_RATE} baud.")
                return True
            except serial.SerialException as e:
                print(f"Warning: Could not open {SERIAL_PORT}: {e}")
    for port in available_ports:
        if port.startswith("ttyUSB"):
            try:
                ser = serial.Serial(port, BAUD_RATE, timeout=SERIAL_WRITE_TIMEOUT)
                print(f"Serial port {port} opened at {BAUD_RATE} baud.")
                return True
            except serial.SerialException as e:
                print(f"Warning: Could not open {port}: {e}")
    print("Warning: No serial port available. Running in non-serial mode.")
    return False


def get_roi(frame):
    h, w = frame.shape[:2]
    cx = w // 2
    cy = h // 2
    x1 = max(cx - ROI_HALF_EXTENT, 0)
    y1 = max(cy - ROI_HALF_EXTENT, 0)
    x2 = min(cx + ROI_HALF_EXTENT, w)
    y2 = min(cy + ROI_HALF_EXTENT, h)
    return frame[y1:y2, x1:x2]


def set_color_range(hsv_roi):
    h_min = np.min(hsv_roi[:, :, 0])
    h_max = np.max(hsv_roi[:, :, 0])
    s_min = np.min(hsv_roi[:, :, 1])
    s_max = np.max(hsv_roi[:, :, 1])
    v_min = np.min(hsv_roi[:, :, 2])
    v_max = np.max(hsv_roi[:, :, 2])
    return np.array([h_min, s_min, v_min]), np.array([h_max, s_max, v_max])


def send_serial_data(data):
    if ser is None:
        return
    try:
        ser.write(data)
        ser.flush()
    except serial.SerialException as e:
        print(f"Serial write error: {e}")


def main():
    global running, cap, ser
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    if not initialize_camera():
        sys.exit(1)
    if not initialize_serial():
        print("Non-serial mode: pressing 's' to sample color, 'o' to disable tracking.")
    try:
        while running:
            ret, frame = cap.read()
            if not ret:
                print("Error: Could not read frame from camera.")
                break
            hsv_roi = cv2.cvtColor(frame, cv2.COLOR_BGR2HSV)
            h_min, s_min, v_min = set_color_range(hsv_roi)
            h_max, s_max, v_max = set_color_range(hsv_roi)
            mask = cv2.inRange(hsv_roi, np.array([h_min, s_min, v_min]), np.array([h_max, s_max, v_max]))
            contours, _ = cv2.findContours(mask, cv2.RETR_EXTERNAL, cv2.CHAIN_APPROX_SIMPLE)
            for contour in contours:
                if cv2.contourArea(contour) > MIN_CONTOUR_AREA:
                    x, y, w, h = cv2.boundingRect(contour)
                    cv2.rectangle(frame, (x, y), (x + w, y + h), (255, 0, 0), 2)
                    ball_x = x + w // 2
                    ball_y = y + h // 2
                    dx = abs(ball_x - ROI_SIZE // 2)
                    dy = abs(ball_y - ROI_SIZE // 2)
                    if dx > ROI_HALF_EXTENT and dy > ROI_HALF_EXTENT:
                        position = 5
                    elif dx > ROI_HALF_EXTENT and dy < ROI_HALF_EXTENT:
                        position = 1
                    elif dx < ROI_HALF_EXTENT and dy > ROI_HALF_EXTENT:
                        position = 3
                    elif dx < ROI_HALF_EXTENT and dy < ROI_HALF_EXTENT:
                        position = 4
                    else:
                        position = 5
                    try:
                        send_serial_data(str(position).encode('utf-8'))
                    except Exception as e:
                        print(f"Serial send error: {e}")
            cv2.imshow("Frame", frame)
            key = cv2.waitKey(1) & 0xFF
            if key == ord('s'):
                roi = get_roi(frame)
                hsv_roi = cv2.cvtColor(roi, cv2.COLOR_BGR2HSV)
                h_min, s_min, v_min = set_color_range(hsv_roi)
                h_max, s_max, v_max = set_color_range(hsv_roi)
            elif key == ord('o'):
                print("Color tracking disabled.")
                running = False
            elif key == 27:
                running = False
    finally:
        if cap is not None:
            cap.release()
        if ser is not None:
            try:
                ser.close()
            except Exception:
                pass
        cv2.destroyAllWindows()


if __name__ == "__main__":
    main()

