import json
import logging
import signal
import sys
import time
from collections import deque
from statistics import median

try:
    from gpiozero import OutputDevice, InputDevice
except ImportError:
    OutputDevice = None
    InputDevice = None

DEFAULT_CONFIG = {
    "trigger_pins": [17, 22, 24],
    "echo_pins": [18, 23, 25],
    "offsets": [0.0, 0.0, 0.0],
    "max_distances": [200.0, 200.0, 200.0],
    "alert_threshold_low": 10.0,
    "alert_threshold_high": 180.0,
    "alert_repeat_delay": 60,
    "log_file": "water_level.log",
}

_running = True


def _signal_handler(signum, frame):
    global _running
    _running = False


def load_config(config_file="config.json"):
    try:
        with open(config_file, "r") as f:
            return json.load(f)
    except FileNotFoundError:
        logging.warning("config.json not found; creating default configuration.")
        try:
            with open(config_file, "w") as f:
                json.dump(DEFAULT_CONFIG, f, indent=2)
        except OSError as e:
            logging.error(f"Failed to write default config: {e}")
        return dict(DEFAULT_CONFIG)
    except json.JSONDecodeError as e:
        logging.error(f"Invalid JSON in config.json: {e}")
        return dict(DEFAULT_CONFIG)


def setup_logging(log_file):
    logging.basicConfig(
        filename=log_file,
        level=logging.INFO,
        format="%(asctime)s - %(levelname)s - %(message)s",
    )
    logging.info("Logging initialized.")


def measure_distance(trigger_pin, echo_pin, offset, max_distance):
    if OutputDevice is None or InputDevice is None:
        logging.error("gpiozero not available; cannot measure distance.")
        return None

    trigger = None
    echo = None
    try:
        trigger = OutputDevice(trigger_pin)
        echo = InputDevice(echo_pin)
    except Exception as e:
        logging.error(f"Failed to initialize GPIO pins {trigger_pin}/{echo_pin}: {e}")
        return None

    try:
        trigger.off()
        time.sleep(0.1)

        trigger.on()
        time.sleep(0.00001)
        trigger.off()

        timeout = time.time() + 0.05
        while echo.is_active:
            if time.time() > timeout:
                logging.error("Echo stuck HIGH before trigger; sensor absent or wiring fault.")
                return None
            time.sleep(0.0001)

        pulse_start = time.time()
        timeout = time.time() + 0.05
        while not echo.is_active:
            if time.time() > timeout:
                logging.error("Echo pulse start timeout; sensor absent or wiring fault.")
                return None
            time.sleep(0.0001)

        pulse_end = time.time()
        pulse_duration = pulse_end - pulse_start

        distance = (pulse_duration * 34300) / 2.0
        distance += offset
        distance = min(distance, max_distance)

        logging.debug(f"Distance: {distance:.2f} cm")
        return distance

    except Exception as e:
        logging.error(f"Error measuring distance: {e}")
        return None
    finally:
        if trigger is not None:
            trigger.close()
        if echo is not None:
            echo.close()


def check_alerts(water_levels, alert_threshold_low, alert_threshold_high, alert_repeat_delay):
    if len(water_levels) < 3:
        return
    valid_levels = [l for l in water_levels if l is not None]
    if not valid_levels:
        return

    avg_level = sum(valid_levels) / len(valid_levels)
    if avg_level < alert_threshold_low:
        logging.warning(f"ALERT: Water level too low! Level: {avg_level:.2f} cm")
    elif avg_level > alert_threshold_high:
        logging.warning(f"ALERT: Water level too high! Level: {avg_level:.2f} cm")
    else:
        logging.info(f"Water level normal: {avg_level:.2f} cm")

    last_low = None
    last_high = None
    last_low_time = 0.0
    last_high_time = 0.0

    for i, level in enumerate(valid_levels):
        if level < alert_threshold_low:
            if last_low is None or (time.time() - last_low_time) > alert_repeat_delay:
                last_low = level
                last_low_time = time.time()
                logging.info(f"Water level too low! Level: {level:.2f} cm")
        elif level > alert_threshold_high:
            if last_high is None or (time.time() - last_high_time) > alert_repeat_delay:
                last_high = level
                last_high_time = time.time()
                logging.info(f"Water level too high! Level: {level:.2f} cm")


def main():
    global _running
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    config = load_config()
    setup_logging(config["log_file"])

    trigger_pins = config["trigger_pins"]
    echo_pins = config["echo_pins"]
    offsets = config["offsets"]
    max_distances = config["max_distances"]
    alert_threshold_low = config["alert_threshold_low"]
    alert_threshold_high = config["alert_threshold_high"]
    alert_repeat_delay = config["alert_repeat_delay"]

    sensors = []
    for i in range(len(trigger_pins)):
        try:
            sensors.append({
                "trigger_pin": trigger_pins[i],
                "echo_pin": echo_pins[i],
                "offset": offsets[i],
                "max_distance": max_distances[i],
            })
        except Exception as e:
            logging.error(f"Error initializing sensor {i}: {e}")
            sensors.append({"trigger_pin": None, "echo_pin": None, "offset": 0.0, "max_distance": 0.0})

    sensor_errors = {i: 0 for i in range(len(sensors))}
    sensor_excluded = {i: False for i in range(len(sensors))}

    logging.info("Starting water level monitoring...")

    try:
        while _running:
            water_levels = []
            for i, sensor in enumerate(sensors):
                if sensor["trigger_pin"] is None or sensor["echo_pin"] is None:
                    continue

                distance = measure_distance(
                    sensor["trigger_pin"], sensor["echo_pin"], sensor["offset"], sensor["max_distance"]
                )
                if distance is not None:
                    water_levels.append(distance)
                    sensor_errors[i] = 0
                else:
                    sensor_errors[i] += 1
                    if sensor_errors[i] >= 5:
                        logging.error(f"Excluding sensor {i} after 5 consecutive errors.")
                        sensor_excluded[i] = True

            if water_levels:
                median_level = median(water_levels)
                logging.info(f"Water level: {median_level:.2f} cm")
                check_alerts(water_levels, alert_threshold_low, alert_threshold_high, alert_repeat_delay)
            else:
                logging.warning("No valid sensor readings this cycle.")

            for i in range(len(sensors)):
                if sensor_excluded[i]:
                    sensors[i]["trigger_pin"] = None
                    sensors[i]["echo_pin"] = None
                    sensors[i]["offset"] = 0.0
                    sensors[i]["max_distance"] = 0.0

            time.sleep(5)
    except Exception as e:
        logging.error(f"Unexpected error: {e}")
    finally:
        logging.info("Exiting water level monitoring.")


if __name__ == "__main__":
    main()

