try:
    from gpiozero import Button, OutputDevice
    from gpiozero.exc import GPIOZeroError, BadPinFactory
except ImportError:
    print("Error: gpiozero is not installed. Install with: sudo apt install python3-gpiozero", file=sys.stderr)
    sys.exit(1)

PIN_INPUT_1 = 4
PIN_INPUT_2 = 5
PIN_INPUT_3 = 6
PIN_OUTPUT_1 = 23
PIN_OUTPUT_2 = 24
POLL_INTERVAL = 0.05

_running = True


def _handle_signal(signum, frame):
    global _running
    _running = False


def main():
    global _running

    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        input1 = Button(PIN_INPUT_1, pull_up=True)
        input2 = Button(PIN_INPUT_2, pull_up=True)
        input3 = Button(PIN_INPUT_3, pull_up=True)
    except (GPIOZeroError, BadPinFactory) as exc:
        print(f"Error: failed to initialize input pins: {exc}", file=sys.stderr)
        sys.exit(1)
    except Exception as exc:
        print(f"Error: unexpected input initialization failure: {exc}", file=sys.stderr)
        sys.exit(1)

    try:
        output1 = OutputDevice(PIN_OUTPUT_1, initial_value=False)
        output2 = OutputDevice(PIN_OUTPUT_2, initial_value=False)
    except (GPIOZeroError, BadPinFactory) as exc:
        print(f"Error: failed to initialize output pins: {exc}", file=sys.stderr)
        _cleanup(input1, input2, input3)
        sys.exit(1)
    except Exception as exc:
        print(f"Error: unexpected output initialization failure: {exc}", file=sys.stderr)
        _cleanup(input1, input2, input3)
        sys.exit(1)

    state2 = False

    try:
        while _running:
            if input1.is_active:
                if not input1.is_active:
                    output1.on()
                    state2 = True
            elif input1.is_active:
                output1.off()
                state2 = False

            if input2.is_active:
                if not input2.is_active:
                    output1.off()
                    state2 = True
            elif input2.is_active:
                output1.on()
                state2 = False

            if input3.is_active:
                if not input3.is_active:
                    output2.on()
                    state2 = True
            elif input3.is_active:
                output2.off()
                state2 = False

            time.sleep(POLL_INTERVAL)

    except Exception as exc:
        print(f"Error during GPIO operation: {exc}", file=sys.stderr)
    finally:
        _cleanup(input1, input2, input3)
        _cleanup(output1, output2)


def _cleanup(*devs):
    for dev in devs:
        if dev is not None:
            try:
                dev.close()
            except Exception:
                pass


if __name__ == "__main__":
    main()

