import cv2
import pyzbar.pyzbar as pyzbar
import time
import datetime
import logging
import configparser
import threading
import queue
import os
import sys

# Configuration file path
CONFIG_FILE = 'config.ini'

# Default configuration values
DEFAULT_CONFIG = {
    'DEFAULT': {
        'camera0_path': '/dev/video0',
        'camera1_path': '/dev/video2',
        'motion_threshold': 25,
        'redundancy_time_window': 5,
        'cloud_upload_interval': 60,
        'frame_buffer_size': 3,
        'reinit_delay': 5,
        'watchdog_timeout': 30
    }
}

# Global variables
inventory_queue = queue.Queue()
inventory_file = 'inventory.log'
backup_inventory_file = 'backup_inventory.log'
shutdown_event = threading.Event()
last_qr_time = {}
camera_lock = threading.Lock()
config = configparser.ConfigParser()
config.read_dict(DEFAULT_CONFIG)

def load_config():
    global config
    config = configparser.ConfigParser()
    config.read_dict(DEFAULT_CONFIG)

def log_message(message):
    """Logs a message to the inventory.log file with a timestamp."""
    try:
        with open(inventory_file, 'a') as f:
            f.write(f"{datetime.datetime.now()} - {message}\n")
    except IOError as e:
        logging.error(f"Error writing to inventory.log: {e}")
        try:
            with open(backup_inventory_file, 'a') as f:
                f.write(f"{datetime.datetime.now()} - {message}\n")
        except IOError as e2:
            logging.error(f"Error writing to backup_inventory.log: {e2}")

def decode_qr_code(frame):
    """Decodes QR codes in a frame and returns the decoded data."""
    try:
        decoded_objects = pyzbar.decode(frame)
        for obj in decoded_objects:
            return obj.data.decode('utf-8')
        return None
    except Exception as e:
        logging.error(f"Error decoding QR code: {e}")
        return None

def process_frame(frame, camera_id):
    """Processes a single frame from a camera, looking for motion and QR codes."""
    try:
        gray = cv2.cvtColor(frame, cv2.COLOR_BGR2GRAY)
        gray = cv2.GaussianBlur(gray, (21, 21), 0)

        if camera_id == 0:
            motion_detected = False
            previous_frame = None
        else:
            motion_detected = False
            previous_frame = None

        if previous_frame is not None:
            frame_delta = cv2.absdiff(gray, previous_frame)
            thresh = cv2.threshold(frame_delta, config['DEFAULT']['motion_threshold'], 255, cv2.THRESH_BINARY)[1]
            thresh = cv2.dilate(thresh, None, iterations=2)
            contours, _ = cv2.findContours(thresh.copy(), cv2.RETR_EXTERNAL, cv2.CHAIN_APPROX_SIMPLE)

            for contour in contours:
                if cv2.contourArea(contour) < 250:
                    continue
                motion_detected = True

        previous_frame = gray

        qr_code_data = decode_qr_code(frame)
        if qr_code_data:
            if not inventory_queue.full():
                inventory_queue.put((qr_code_data, camera_id))
            else:
                log_message(f"Inventory full for camera {camera_id}, dropping scan.")

        return frame, motion_detected

    except Exception as e:
        logging.error(f"Error processing frame: {e}")
        return frame, False

def camera_thread(camera_id, camera_path, frame_buffer_size):
    """Thread function for capturing and processing video from a camera."""
    global last_qr_time, shutdown_event
    previous_frame = None
    frame_buffer = [None] * frame_buffer_size
    frame_index = 0

    while not shutdown_event.is_set():
        try:
            cap = cv2.VideoCapture(camera_path)
            if not cap.isOpened():
                logging.error(f"Failed to open camera {camera_id}: {camera_path}")
                time.sleep(config['DEFAULT']['reinit_delay'])
                continue

            time.sleep(2.0)
            ret, frame = cap.read()
            if not ret:
                logging.error(f"Failed to read frame from camera {camera_id}: {camera_path}")
                cap.release()
                time.sleep(config['DEFAULT']['reinit_delay'])
                continue

            frame_buffer[frame_index] = frame
            frame_index = (frame_index + 1) % frame_buffer_size

            if frame_buffer[0] is not None:
                previous_frame = frame_buffer[0]

