                        if qr_code_data not in last_qr_time or (time.time() - last_qr_time[qr_code_data]) > config['DEFAULT']['redundancy_time_window']:
                            log_message(f"QR Code: {qr_code_data} from Camera {camera_id}")
                            last_qr_time[qr_code_data] = time.time()

            cap.release()
            time.sleep(config['DEFAULT']['reinit_delay'])

        except Exception as e:
            logging.error(f"Error in camera thread for {camera_id}: {e}")
            time.sleep(config['DEFAULT']['reinit_delay'])

def cloud_upload():
    """Simulates uploading data to a cloud service."""
    try:
        with open(inventory_file, 'r') as f:
