#!/usr/bin/env python3
"""
Raspberry Pi Motion Detection and Temperature Alert System

Uses Picamera2 for motion detection and gpiozero for CPU temperature monitoring.
"""

import io
import time
import datetime
import signal
import sys
import os
import configparser
from PIL import Image
from picamera2 import Picamera2
from gpiozero import CPUTemperature

CONFIG_FILE = "config.txt"
DEFAULT_CONFIG = {
    "resolution_width": "640",
    "resolution_height": "480",
    "roi_x1": "0",
    "roi_y1": "0",
    "roi_x2": "640",
    "roi_y2": "480",
    "motion_threshold": "1.0",
    "confirmation_delay": "5",
    "temperature_threshold": "45.0",
    "simulated_temperature": "False",
    "snapshot_dir": "snapshots"
}

running = True

def signal_handler(sig, frame):
    global running
    running = False

def load_config(config_file):
    config = configparser.ConfigParser()
    if not os.path.exists(config_file):
        print(f"Warning: {config_file} not found. Using defaults.")
        return DEFAULT_CONFIG
    try:
        config.read(config_file)
        return config
    except Exception as e:
        print(f"Error reading config: {e}. Using defaults.")
        return DEFAULT_CONFIG

def parse_resolution(config, key):
    try:
        value = config.getint(key, "resolution_width")
        return (value, config.getint(key, "resolution_height"))
    except (configparser.NoOptionError, configparser.Error, ValueError) as e:
        print(f"Error parsing {key}: {e}. Using default {DEFAULT_CONFIG[key]['resolution_width']}.")
        return DEFAULT_CONFIG[key]["resolution_width"], DEFAULT_CONFIG[key]["resolution_height"]

def parse_roi(config, key):
    try:
        x1 = config.getint(key, "roi_x1")
        y1 = config.getint(key, "roi_y1")
        x2 = config.getint(key, "roi_x2")
        y2 = config.getint(key, "roi_y2")
        return (x1, y1, x2, y2)
    except (configparser.NoOptionError, configparser.Error, ValueError) as e:
        print(f"Error parsing {key}: {e}. Using default 0-640.")
        return 0, 0, 640, 480

def parse_threshold(config, key):
    try:
        return float(config.getfloat(key, "motion_threshold"))
    except (configparser.NoOptionError, configparser.Error, ValueError) as e:
        print(f"Error parsing {key}: {e}. Using default 1.0.")
        return DEFAULT_CONFIG[key]["motion_threshold"]

def parse_delay(config, key):
    try:
        return float(config.getfloat(key, "confirmation_delay"))
    except (configparser.NoOptionError, configparser.Error, ValueError) as e:
        print(f"Error parsing {key}: {e}. Using default 5.")
        return DEFAULT_CONFIG[key]["confirmation_delay"]

def parse_temp_threshold(config, key):
    try:
        return float(config.getfloat(key, "temperature_threshold"))
    except (configparser.NoOptionError, configparser.Error, ValueError) as e:
        print(f"Error parsing {key}: {e}. Using default 45.0.")
        return DEFAULT_CONFIG[key]["temperature_threshold"]

def parse_temp_simulated(config, key):
    try:
        return config.getboolean(key, "simulated_temperature")
    except (configparser.NoOptionError, configparser.Error) as e:
        print(f"Error parsing {key}: {e}. Using default False.")
        return DEFAULT_CONFIG[key]["simulated_temperature"]

def parse_snapshot_dir(config, key):
    try:
        return config.get(key, "snapshot_dir")
    except (configparser.NoOptionError, configparser.Error) as e:
        print(f"Error parsing {key}: {e}. Using default 'snapshots'.")
        return DEFAULT_CONFIG[key]["snapshot_dir"]

def detect_motion(picam2, config, prev_frame, roi):
    try:
        current_frame = picam2.capture_array()
        if current_frame is None:
            return False, prev_frame
        current_frame = Image.fromarray(current_frame)
        current_frame = current_frame.crop(roi)
        current_frame = current_frame.convert("L")
        current_frame = current_frame.resize((roi[2] - roi[0], roi[3] - roi[1]))
        current_frame = current_frame.convert("RGB")
        current_frame = current_frame.getdata()
        total_pixels = roi[2] * roi[3]
        motion_pixels = sum(1 for pixel in current_frame if pixel > 127)
        motion_percentage = (motion_pixels / total_pixels) * 100
        return motion_percentage > config["motion_threshold"], current_frame
    except Exception as e:
        print(f"Error detecting motion: {e}")
        return False, prev_frame

def save_snapshot(picam2, config, current_frame, timestamp):
    try:
        snapshot_dir = parse_snapshot_dir(config, "snapshot_dir")
        os.makedirs(snapshot_dir, exist_ok=True)
        filename = os.path.join(snapshot_dir, f"motion_{timestamp}.jpg")
        picam2.capture_file(filename)
        print(f"Snapshot saved: {filename}")
    except Exception as e:
        print(f"Error saving snapshot: {e}")

def temperature_alert(temp_sensor, config):
    try:
        temp = temp_sensor.temperature
        timestamp = datetime.datetime.now().strftime("%Y-%m-%d_%H-%M-%S")
        if temp > config["temperature_threshold"]:
            print(f"Temperature alert: {temp:.2f}C at {timestamp}")
            save_snapshot(None, config, None, timestamp)
    except Exception as e:
        print(f"Error reading temperature: {e}")

def main():
    global running
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)
    config = load_config(CONFIG_FILE)
    width, height = parse_resolution(config, "resolution")
    roi = parse_roi(config, "roi")
    motion_threshold = parse_threshold(config, "motion_threshold")
    confirmation_delay = parse_delay(config, "confirmation_delay")
    temperature_threshold = parse_temp_threshold(config, "temperature_threshold")
    simulated_temperature = parse_temp_simulated(config, "simulated_temperature")
    temp_sensor = None
    if simulated_temperature:
        print("Using simulated temperature sensor.")
    else:
        try:
            temp_sensor = CPUTemperature()
            print("Using gpiozero CPU temperature sensor.")
        except Exception as e:
            print(f"Error initializing temperature sensor: {e}. Using simulated.")
            temp_sensor = None
    picam2 = None
    try:
        picam2 = Picamera2()
        picam2.configure(picam2.create_preview_configuration(main={"format": "RGB888", "size": (width, height)}))
        picam2.start()
        print("Camera initialized.")
    except Exception as e:
        print(f"Error initializing camera: {e}")
        sys.exit(1)
    prev_frame = None
    try:
        while running:
            motion, prev_frame = detect_motion(picam2, config, prev_frame, roi)
            if motion:
                print("Motion detected!")
                time.sleep(confirmation_delay)
                if running:
                    temperature_alert(temp_sensor, config)
            time.sleep(0.1)
    except Exception as e:
        print(f"Unexpected error: {e}")
    finally:
        if picam2:
            picam2.stop()
            picam2.close()
        if temp_sensor:
            temp_sensor.close()
        print("Exiting.")

if __name__ == "__main__":
    main()

