import cv2
import pyzbar.pyzbar as pyzbar
from datetime import datetime
import csv
import time
import os
import signal
import sys

ERROR_LOG_FILE = "error_log.txt"
CSV_FILE = "inventory_log.csv"
CAMERA_ID = "Camera 1"
CAPTURE_INTERVAL = 0.2

running = True

def signal_handler(signum, frame):
    global running
    running = False

def log_error(message):
    timestamp = datetime.now().isoformat(timespec="seconds")
    try:
        with open(ERROR_LOG_FILE, "a") as f:
            f.write(f"{timestamp} - {message}\n")
    except Exception as e:
        print(f"Failed to write to error log: {e}", file=sys.stderr)

def write_csv_header():
    try:
        with open(CSV_FILE, "x", newline="") as f:
            writer = csv.writer(f)
            writer.writerow(["camera_id", "item_id", "capture_time"])
    except FileExistsError:
        pass
    except Exception as e:
        log_error(f"Failed to create CSV file: {e}")

def log_inventory_item(item_id):
    timestamp = datetime.now().isoformat(timespec="seconds")
    try:
        with open(CSV_FILE, "a", newline="") as f:
            writer = csv.writer(f)
            writer.writerow([CAMERA_ID, item_id, timestamp])
    except Exception as e:
        log_error(f"Failed to write to CSV file: {e}")

def decode_qr_code(frame):
    try:
        decoded_objects = pyzbar.decode(frame)
        if decoded_objects:
            return decoded_objects[0].data.decode("utf-8")
        return None
    except Exception as e:
        log_error(f"QR code decode error: {e}")
        return None

def validate_item_id(item_id):
    if not item_id or not item_id.isalnum():
        return False
    for char in item_id:
        if not (char.isalpha() or char.isdigit()):
            return False
    return True

def main():
    global running
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    write_csv_header()

    cap = cv2.VideoCapture(0)
    if not cap.isOpened():
        log_error("Failed to open USB camera at index 0")
        return

    try:
        while running:
            ret, frame = cap.read()
            if not ret:
                log_error("Failed to capture frame from camera")
                time.sleep(CAPTURE_INTERVAL)
                continue

            item_id = decode_qr_code(frame)
            if item_id is None:
                time.sleep(CAPTURE_INTERVAL)
                continue

            if validate_item_id(item_id):
                log_inventory_item(item_id)
            else:
                log_error(f"Invalid item_id: {item_id}")

            time.sleep(CAPTURE_INTERVAL)
    finally:
        cap.release()
        cv2.destroyAllWindows()

if __name__ == "__main__":
    main()

