import signal
import sys
import time
import boto3
from picamera2 import Picamera2
from botocore.exceptions import ClientError, ResourceNotFoundException

running = True

def signal_handler(sig, frame):
    global running
    running = False
    print("\nInterrupt received, shutting down...")

def initialize_camera():
    try:
        picam2 = Picamera2()
        picam2.start()
        time.sleep(2)
        return picam2
    except Exception as e:
        print(f"Error initializing camera: {e}")
        return None

def capture_image(picam2):
    try:
        picam2.capture_file("image.jpg")
        print("Image captured successfully.")
        return True
    except Exception as e:
        print(f"Error capturing image: {e}")
        return False

def check_face_recognition(client, collection_id, image_path, similarity_threshold):
    try:
        with open(image_path, 'rb') as image_file:
            response = client.search_faces_by_image(
                CollectionId=collection_id,
                Image={'Bytes': image_file.read()},
                MaxFaces=1,
                FaceMatchThreshold=similarity_threshold
            )
        return response, True
    except (ClientError, ResourceNotFoundException) as e:
        print(f"Error checking face recognition: {e}")
        return None, False
    except Exception as e:
        print(f"Unexpected error checking face recognition: {e}")
        return None, False

def main():
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        client = boto3.client('rekognition')
    except Exception as e:
        print(f"Error initializing Rekognition client: {e}")
        sys.exit(1)

    picam2 = initialize_camera()
    if picam2 is None:
        sys.exit(1)

    if not capture_image(picam2):
        picam2.close()
        sys.exit(1)

    matched, found = check_face_recognition(client, 'home', 'image.jpg', 85)

    if matched is not None and found:
        print(f"Matched face found. External Image ID: {matched['FaceMatches'][0]['ExternalImageId']}")
        print(f"Similarity: {matched['FaceMatches'][0]['Similarity']}")
    elif matched is not None and not found:
        print("No face matches found.")
    else:
        print("No face matches found.")

    try:
        picam2.close()
    except Exception:
        pass

if __name__ == "__main__":
    main()

