import asyncio
import logging
import signal
import threading
import numpy as np
import cv2
from picamera2 import Picamera2
from picamera2.encoders import MJPEGEncoder
from picamera2.outputs import Output

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)


class WebSocketHandler:
    """Manages WebSocket connections and broadcasts JPEG frames."""

    def __init__(self):
        self._connections = 0
        self._lock = threading.Lock()
        self._event_loop = None

    def has_connections(self) -> bool:
        with self._lock:
            return self._connections > 0

    def add_connection(self):
        with self._lock:
            self._connections += 1

    def remove_connection(self):
        with self._lock:
            self._connections -= 1


def _signal_handler(signum, frame, handler):
    logger.info(f"Signal {signum} received, shutting down...")
    handler.stop()
    raise SystemExit(0)


def _convert_jpeg_bytes_to_opencv_frame(jpeg_bytes):
    """Convert JPEG bytes to an OpenCV BGR frame."""
    if not jpeg_bytes:
        return None
    try:
        data = np.frombuffer(jpeg_bytes, dtype=np.uint8)
        frame = cv2.imdecode(data, cv2.IMREAD_COLOR)
        if frame is None:
            logger.warning("cv2.imdecode returned None; invalid JPEG data.")
            return None
        return frame
    except Exception as e:
        logger.error(f"Error converting JPEG bytes to frame: {e}")
        return None


def _detect_motion(prev_frame, curr_frame, detect_motion_function):
    """Detect motion between two OpenCV frames."""
    if prev_frame is None or curr_frame is None:
        return False
    try:
        diff = cv2.absdiff(prev_frame, curr_frame)
        gray = cv2.cvtColor(diff, cv2.COLOR_BGR2GRAY)
        _, thresh = cv2.threshold(gray, 25, 255, cv2.THRESH_BINARY)
        motion_detected = bool(np.sum(thresh) > 0)
        if motion_detected:
            logger.debug("Motion detected.")
        return motion_detected
    except Exception as e:
        logger.error(f"Error detecting motion: {e}")
        return False


class CameraStreamHandler:
    """Captures video from the V2 camera and broadcasts JPEG frames via WebSockets."""

    def __init__(self, detect_motion_function=None):
        self._detect_motion_function = detect_motion_function
        self._picam2 = None
        self._output = None
        self._buffer = bytearray()
        self._lock = threading.Lock()
        self._stop_event = threading.Event()
        self._event_loop = None
        self._prev_frame = None
        self._install_signal_handlers()

    def _install_signal_handlers(self):
        for sig in (signal.SIGINT, signal.SIGTERM):
            loop = asyncio.get_event_loop()
