import argparse
import logging
import logging.handlers
import os
import signal
import sys
import threading
import time
from collections import deque

import numpy as np
import smbus2
from PIL import Image
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
from picamera2 import Picamera2
import adafruit_amg88xx

DEFAULT_CONFIG = {
    'sampling_rate': 5,
    'motion_detection_threshold': 1.0,
    'enable_camera': False,
    'log_max_size': 1048576,
    'logging_file_path': 'beehive.log',
}


class ThermalMonitor:
    def __init__(self, config):
        self.config = config
        self.running = True
        self.last_frame = None
        self.frame_buffer = deque(maxlen=300)
        self.i2c = None
        self.camera = None
        self.thermal_sensor = None
        self.lock = threading.Lock()
        self._stop_event = threading.Event()

        self._init_i2c()
        self._init_camera()
        self._init_thermal_sensor()

    def _init_i2c(self):
        try:
            self.i2c = smbus2.SMBus(1)
            logging.info("I2C bus 1 initialized successfully.")
        except Exception as e:
            logging.error(f"Failed to initialize I2C bus 1: {e}")
            sys.exit(1)

    def _init_camera(self):
        if not self.config['enable_camera']:
            logging.info("Camera disabled in config.")
            return
        try:
            self.camera = Picamera2()
            self.camera.configure(self.camera.create_still_configuration())
            self.camera.start()
            logging.info("Camera initialized successfully.")
        except Exception as e:
            logging.warning(f"Failed to initialize camera: {e}. Continuing without camera.")

    def _init_thermal_sensor(self):
        for attempt in range(3):
            try:
                self.thermal_sensor = adafruit_amg88xx.AMG88XX(self.i2c, addr=0x69)
                logging.info("AMG88XX thermal sensor initialized successfully.")
                return
            except Exception as e:
                logging.error(f"Failed to initialize AMG88XX sensor (attempt {attempt + 1}/3): {e}")
                time.sleep(2)
        logging.error("Failed to initialize AMG88XX sensor after 3 attempts. Exiting.")
        sys.exit(1)

    def _read_thermal_frame(self):
        try:
            return np.array(self.thermal_sensor.pixels, dtype=np.float32)
        except Exception as e:
            logging.error(f"Error reading thermal frame: {e}")
            return None

    def _capture_image(self):
        if self.camera is None:
            logging.warning("Camera not available; skipping image capture.")
            return
        try:
            image = self.camera.capture_image()
            image.save('thermal_image.png')
            logging.info("Image captured and saved as thermal_image.png")
        except Exception as e:
            logging.error(f"Error capturing image: {e}")

    def _process_frame(self, frame):
        if frame is None:
            return
        if self.last_frame is not None:
            diff = np.abs(frame.astype(np.int16) - self.last_frame.astype(np.int16))
            mean_diff = float(np.mean(diff))
            if mean_diff > self.config['motion_detection_threshold'] and self.config['enable_camera']:
                logging.info(f"Motion detected! Mean difference: {mean_diff:.2f}")
                self._capture_image()
        self.frame_buffer.append(frame)
        self.last_frame = frame

    def _render_heatmap(self):
        if self.frame_buffer:
            frame = self.frame_buffer[-1]
            if frame is None:
                return
            plt.imshow(frame, cmap='jet', interpolation='nearest')
            plt.colorbar(label='Temperature (°C)')
            plt.title(f"Thermal Image - {time.strftime('%Y-%m-%d %H:%M:%S')}")
            plt.tight_layout()
            plt.savefig('thermal_image.png', dpi=150)
            plt.close()
            logging.info("Heatmap rendered and saved as thermal_image.png")
        else:
            logging.warning("No frame available for rendering.")

    def _log_event(self, message):
        logging.info(message)

    def _log_error(self, message):
        logging.error(message)

    def _log_motion(self, message):
        logging.info(message)

    def _log_camera_error(self, message):
        logging.warning(message)

    def _log_config(self, message):
        logging.info(message)

    def _signal_handler(self, signum, frame):
        logging.info(f"Signal {signum} received. Shutting down...")
        self.running = False
        self._stop_event.set()

    def run(self):
        signal.signal(signal.SIGINT, self._signal_handler)
        signal.signal(signal.SIGTERM, self._signal_handler)

        logging.basicConfig(
            filename=self.config['logging_file_path'],
            level=logging.INFO,
            format='%(asctime)s - %(levelname)s - %(message)s',
            force=True,
        )

        logging.info("Starting thermal monitoring system...")
        logging.info(f"Config: {self.config}")

        try:
            while self.running:
                frame = self._read_thermal_frame()
                if frame is not None:
                    self._process_frame(frame)
                self._render_heatmap()
                self._stop_event.wait(1.0 / self.config['sampling_rate'])
        except Exception as e:
            logging.error(f"Unexpected error in main loop: {e}")
        finally:
            self.cleanup()

    def cleanup(self):
        logging.info("Cleaning up resources...")
        if self.camera is not None:
            try:
                self.camera.stop()
                self.camera.close()
            except Exception as e:
                logging.error(f"Error closing camera: {e}")
        if self.i2c is not None:
            try:
                self.i2c.close()
            except Exception as e:
                logging.error(f"Error closing I2C bus: {e}")
        logging.info("Cleanup complete.")


def load_config(config_file):
    try:
        with open(config_file, 'r') as f:
            config = {**DEFAULT_CONFIG, **json.load(f)}
        logging.info(f"Configuration loaded from {config_file}")
        return config
    except FileNotFoundError:
        logging.warning(f"Config file {config_file} not found. Using defaults.")
        return DEFAULT_CONFIG.copy()
    except json.JSONDecodeError as e:
        logging.error(f"Error decoding JSON from {config_file}: {e}. Using defaults.")
        return DEFAULT_CONFIG.copy()
    except Exception as e:
        logging.error(f"Unexpected error loading config: {e}. Using defaults.")
        return DEFAULT_CONFIG.copy()


def main():
    parser = argparse.ArgumentParser(description="Thermal Monitoring System for Beehive")
    parser.add_argument("--config", default="config.json", help="Path to the configuration file")
    args = parser.parse_args()

    config = load_config(args.config)
    logging.info("Starting thermal monitoring system...")
    logging.info(f"Config: {config}")

    monitor = ThermalMonitor(config)
    monitor.run()


if __name__ == "__main__":
    main()

