import io
import logging
import signal
import sys
import numpy as np
import cv2

try:
    from picamera2 import Picamera2
except ImportError:
    logging.error("picamera2 is not installed. Install with: pip install picamera2")
    sys.exit(1)

logging.basicConfig(level=logging.INFO, format="%(asctime)s [%(levelname)s] %(message)s")
logger = logging.getLogger(__name__)


class CameraStreamBuffer:
    """Accumulates MJPEG frames from a picamera2 stream and flushes them to an output sink."""

    def __init__(self, c: Picamera2):
        self.b = io.BytesIO()
        self.c = c
        self._flushed = False

    def write(self, d: bytes) -> int:
        """Accumulate bytes; flush completed frames (non-I-frames) to the output sink."""
        try:
            self.b.write(d)
        except OSError as exc:
            logger.error("I/O error while writing to buffer: %s", exc)
            return len(d)

        # Detect end of a complete frame (H.264 metadata) and flush if not an I-frame.
        if self.b.tell() >= self.c.current_configuration()['encode'].size:
            try:
                cfg = self.c.current_configuration()
            except Exception as exc:
                logger.error("Failed to read current configuration: %s", exc)
                return len(d)
            if cfg.get('encode', None) is None:
                return len(d)
            metadata = self.b.getvalue()[-cfg['encode'].size:]
            if metadata:
                try:
                    metadata = metadata.decode('utf-8', errors='ignore')
                except UnicodeDecodeError:
                    metadata = ''
                if 'frame_type' in metadata and metadata.find('frame_type=0') != -1:
                    # Non-I-frame: flush accumulated data.
                    self.flush()
                    self._flushed = True
                    return len(d)
                elif 'frame_type' in metadata and metadata.find('frame_type=1') != -1:
                    # I-frame: keep accumulating.
                    self._flushed = False
            else:
                # No metadata; assume end of frame.
                self.flush()
                self._flushed = True
                return len(d)

        return len(d)

    def flush(self) -> None:
        """Flush the accumulated buffer to the output sink."""
        if self._flushed:
            return
        try:
            data = self.b.getvalue()
        except OSError as exc:
            logger.error("Failed to read buffer for flush: %s", exc)
            return
        if data:
            try:
                self.c.encode(data)
            except Exception as exc:
                logger.error("Failed to encode data: %s", exc)
        self.b.seek(0)
        self.b.truncate(0)
        self._flushed = True


class MotionDetectionBuffer:
    """Accumulates JPEG frames from an MJPEG stream and decodes them for motion detection."""

    def __init__(self, f: callable):
        if not callable(f):
            raise TypeError("callback must be callable")
        self.f = f
        self.b = io.BytesIO()
        self._prev = None
        self._curr = None

    def write(self, d: bytes) -> int:
        """Parse JPEG frames and invoke the motion-detection callback."""
        try:
            self.b.write(d)
        except OSError as exc:
            logger.error("I/O error while writing to buffer: %s", exc)
            return len(d)

        # Find the SOI marker that separates one JPEG frame from the next.
        pos = self.b.tell()
        while pos > 0:
            try:
                start = self.b.tell()
            except OSError as exc:
                logger.error("Failed to seek in buffer: %s", exc)
                return len(d)
            try:
                self.b.seek(start)
                marker = self.b.read(1)
            except OSError as exc:
                logger.error("Failed to read marker: %s", exc)
                return len(d)
            if marker != b'\xff\xd8':
                break
            # Read the rest of the JPEG frame.
            try:
                self.b.seek(start + 1)
                end = self.b.tell()
            except OSError as exc:
                logger.error("Failed to seek end of frame: %s", exc)
                return len(d)
            try:
                self.b.seek(start + 2)
                frame_data = self.b.read(end - start - 2)
            except OSError as exc:
                logger.error("Failed to read frame data: %s", exc)
                return len(d)
            if not frame_data:
                continue
            # Decode the frame.
            try:
                ok, prev_img, _ = cv2.imdecode(np.frombuffer(frame_data, dtype=np.uint8), cv2.IMREAD_COLOR)
                if ok:
                    self._prev = prev_img
                    self._curr = ok
                    if self._prev is not None and self._curr is not None:
                        self.f(self._prev, self._curr)
            except Exception as exc:
                logger.error("Error decoding frame: %s", exc)
            finally:
                # Skip the SOI marker and trailing bytes of the previous frame.
                self.b.seek(start + 2)
                self.b.truncate(pos - start - 2)
            break
        return len(d)


# ---------------------------------------------------------------------------
# Signal handling for clean shutdown
# ---------------------------------------------------------------------------
_running = True

def _signal_handler(signum, frame):
    global _running
    logger.info("Signal %s received, shutting down...", signum)
    _running = False


