    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    picam2 = Picamera2()
    try:
        config = picam2.create_video_configuration(
            main={"size": (640, 480), "format": "RGB888"},
            encode="mjpeg",
        )
        picam2.configure(config)
        picam2.start()
        logger.info("picamera2 started successfully.")
    except Exception as exc:
        logger.error("Failed to initialize picamera2: %s", exc)
        sys.exit(1)

    stream_buf = CameraStreamBuffer(picam2)
    motion_buf = MotionDetectionBuffer(lambda p, c: logger.info("Motion detected: p=%s, c=%s", p, c))

    try:
        while _running:
            try:
                data = stream_buf.b.getvalue()
            except OSError as exc:
                logger.error("Failed to read buffer: %s", exc)
                break
            if data:
