    """Release every hardware resource we own."""
    global _door_lock, _button, _camera, _mixer
    if _door_lock is not None:
        try:
            _door_lock.off()
        except Exception:
            pass
        _door_lock.close()
        _door_lock = None
    if _button is not None:
        try:
            _button.close()
        except Exception:
