        model.read(config.TRAINING_FILE)
        return model
    except cv2.error as exc:
        print(f"[ERROR] OpenCV model load failed: {exc}", file=sys.stderr)
        return None
    except Exception as exc:
        print(f"[ERROR] Unexpected model load error: {exc}", file=sys.stderr)
        return None


