                except Exception as exc:
                    print(f"[WARN] face recognition failed: {exc}", file=sys.stderr)
                    time.sleep(0.1)
                    continue

                if label == config.POSITIVE_LABEL and confidence < config.POSITIVE_THRESHOLD:
                    print("Recognized face! Unlocking...")
                    _door_lock.on()
                    time.sleep(0.5)
                    _door_lock.off()
                    try:
                        _mixer.play(welcome)
                    except pygame.error as exc:
                        print(f"[WARN] welcome.play failed: {exc}", file=sys.stderr)
                else:
                    print("Face not recognized.")
                    try:
                        _mixer.play(wait)
                    except pygame.error as exc:
                        print(f"[WARN] wait.play failed: {exc}", file=sys.stderr)

            time.sleep(0.1)
    finally:
        _cleanup()
        print("Cleanup complete. Exiting.")


if __name__ == "__main__":
    main()

