import signal
import sys
import time
import board
import busio
import adafruit_ssd1306
import adafruit_bme280
import adafruit_tsl2561

# Global resources for cleanup
display = None
i2c = None
bme280 = None
tsl2561 = None
running = True

def cleanup():
    global display, i2c, bme280, tsl2561
    if display is not None:
        try:
            display.fill(0)
            display.show()
        except Exception:
            pass
    if i2c is not None:
        try:
            i2c.deinit()
        except Exception:
            pass
    if bme280 is not None:
        try:
            bme280 = None
        except Exception:
            pass
    if tsl2561 is not None:
        try:
            tsl2561 = None
        except Exception:
            pass

def signal_handler(sig, frame):
    global running
    running = False

def init_display():
    global display
    try:
        i2c = busio.I2C(board.SCL, board.SDA)
        display = adafruit_ssd1306.SSD1306_I2C(128, 64, i2c, addr=0x3C)
        display.fill(0)
        display.show()
        return True
    except Exception as e:
        print(f"Error initializing display at 0x3C: {e}", file=sys.stderr)
        return False

def init_bme280():
    global bme280
    try:
        i2c = busio.I2C(board.SCL, board.SDA)
        bme280 = adafruit_bme280.Adafruit_BME280_I2C(i2c, address=0x76)
        return True
    except Exception as e:
        print(f"Error initializing BME280 at 0x76: {e}", file=sys.stderr)
        return False

def init_tsl2561():
    global tsl2561
    try:
        i2c = busio.I2C(board.SCL, board.SDA)
        tsl2561 = adafruit_tsl2561.TSL2561(i2c, address=0x39)
        return True
    except Exception as e:
        print(f"Error initializing TSL2561 at 0x39: {e}", file=sys.stderr)
        return False

def read_sensors():
    temp = None
    hum = None
    pres = None
    light = None
    try:
        temp = bme280.temperature
        hum = bme280.humidity
        pres = bme280.pressure
    except Exception as e:
        print(f"BME280 read error: {e}", file=sys.stderr)
    try:
        light = tsl2561.lux
    except Exception as e:
        print(f"TSL2561 read error: {e}", file=sys.stderr)
    return temp, hum, pres, light

def update_display(temp, hum, pres, light):
    try:
        display.fill(0)
        display.text(f"Temp: {temp:.1f} C", 0, 0, 1)
        display.text(f"Humidity: {hum:.1f} %", 0, 16, 1)
        display.text(f"Pressure: {pres:.1f} hPa", 0, 32, 1)
        display.text(f"Light: {light:.1f} lux", 0, 48, 1)
        display.show()
    except Exception as e:
        print(f"Display update error: {e}", file=sys.stderr)

def main():
    global running
    signal.signal(signal.SIGINT, signal_handler)
    if not init_display():
        sys.exit(1)
    if not init_bme280():
        sys.exit(1)
    if not init_tsl2561():
        sys.exit(1)
    try:
        while running:
            temp, hum, pres, light = read_sensors()
            update_display(temp, hum, pres, light)
            time.sleep(1)
    except Exception as e:
        print(f"Unexpected error: {e}", file=sys.stderr)
    finally:
        cleanup()

if __name__ == "__main__":
    main()

