import spidev
import time
import signal
import sys
import logging
from luma.core.interface.serial import i2c
from luma.oled.device import ssd1306
from luma.core.render import canvas

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)

SPI_BUS = 0
SPI_DEVICE = 0
SPI_SPEED_HZ = 50000
OLED_I2C_PORT = 1
OLED_I2C_ADDRESS = 0x3C
REFERENCE_VOLTAGE = 3.3
ADC_MAX_VALUE = 1023
READ_INTERVAL_SECONDS = 1.0

spi = None
oled_display = None
running = True

def signal_handler(signum, frame):
    global running
    logger.info(f"Signal {signum} received, shutting down...")
    running = False

def initialize_spi():
    try:
        s = spidev.SpiDev()
        s.open(SPI_BUS, SPI_DEVICE)
        s.max_speed_hz = SPI_SPEED_HZ
        s.mode = 0
        logger.info(f"SPI initialized on bus {SPI_BUS}, device {SPI_DEVICE} at {SPI_SPEED_HZ} Hz")
        return s
    except Exception as e:
        logger.error(f"Failed to initialize SPI: {e}")
        return None

def initialize_oled():
    try:
        serial = i2c(port=OLED_I2C_PORT, address=OLED_I2C_ADDRESS)
        device = ssd1306(serial, width=128, height=64)
        logger.info(f"OLED initialized on I2C bus {OLED_I2C_PORT} at address 0x{OLED_I2C_ADDRESS:02X}")
        return device
    except Exception as e:
        logger.error(f"Failed to initialize OLED: {e}")
        return None

def read_adc_channel(spi_dev, channel):
    if not 0 <= channel <= 3:
        raise ValueError(f"Invalid ADC channel: {channel}. Must be 0-3.")
    try:
        adc = spi_dev.xfer2([1, (8 + channel) << 4, 0])
        data = ((adc[1] & 3) << 8) + adc[2]
        return data
    except Exception as e:
        logger.error(f"Error reading ADC channel {channel}: {e}")
        return None

def convert_to_voltage(adc_value):
    if adc_value is None:
        return None
    return adc_value * (REFERENCE_VOLTAGE / ADC_MAX_VALUE)

def display_data(device, voltages):
    try:
        with canvas(device) as draw:
            for i, voltage in enumerate(voltages):
                if voltage is not None:
                    draw.text((0, i * 10), f"CH{i}: {voltage:.2f}V", fill="white")
                else:
                    draw.text((0, i * 10), f"CH{i}: ERR", fill="white")
    except Exception as e:
        logger.error(f"Error displaying data: {e}")

def cleanup():
    global spi, oled_display
    logger.info("Cleaning up resources...")
    if spi is not None:
        try:
            spi.close()
            logger.info("SPI closed.")
        except Exception as e:
            logger.error(f"Error closing SPI: {e}")
        finally:
            spi = None
    if oled_display is not None:
        try:
            oled_display.cleanup()
            logger.info("OLED display cleaned up.")
        except Exception as e:
            logger.error(f"Error cleaning up OLED: {e}")
        finally:
            oled_display = None

def main():
    global spi, oled_display, running
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    spi = initialize_spi()
    if spi is None:
        logger.error("SPI initialization failed. Exiting.")
        sys.exit(1)

    oled_display = initialize_oled()
    if oled_display is None:
        logger.error("OLED initialization failed. Exiting.")
        cleanup()
        sys.exit(1)

    try:
        while running:
            voltages = [convert_to_voltage(read_adc_channel(spi, i)) for i in range(4)]
            display_data(oled_display, voltages)
            time.sleep(READ_INTERVAL_SECONDS)
    except Exception as e:
        logger.error(f"Unexpected error in main loop: {e}")
    finally:
        cleanup()

if __name__ == "__main__":
    main()

