import signal
import sys
import board
import busio
import adafruit_character_lcd.character_lcd_i2c as character_lcd
import adafruit_dht

# --- Configuration -----------------------------------------------------------
LCD_COLUMNS = 16
LCD_ROWS = 2
DHT_PIN = board.D4
I2C_ADDR = 0x27
UPDATE_INTERVAL_S = 2.0

# --- Globals for cleanup -----------------------------------------------------
_lcd = None
_sensor = None
_running = True


def _cleanup():
    """Clear the LCD display so stale data is never left on exit."""
    global _lcd
    if _lcd is not None:
        try:
            _lcd.clear()
        except Exception:
            pass


def _signal_handler(signum, frame):
    global _running
    _running = False


def init_i2c():
    """Initialize the I2C bus; return the bus object or None on failure."""
    try:
        return busio.I2C(board.SCL, board.SDA)
    except Exception as exc:
        print(f"[init_i2c] I2C bus init failed: {exc}", file=sys.stderr)
        return None


def init_lcd(i2c_bus, address):
    """Initialize the 16x2 I2C character LCD; return the LCD object or None."""
    try:
        return character_lcd.Character_LCD_I2C(i2c_bus, LCD_COLUMNS, LCD_ROWS, address=address)
    except Exception as exc:
        print(f"[init_lcd] LCD init failed: {exc}", file=sys.stderr)
        return None


def init_dht22(pin):
    """Initialize the DHT22 sensor; return the sensor object or None."""
    try:
        return adafruit_dht.DHT22(pin, use_pulseio=False)
    except Exception as exc:
        print(f"[init_dht22] DHT22 init failed: {exc}", file=sys.stderr)
        return None


def read_dht22(sensor):
    """Read temperature and humidity from the DHT22; return (temp, hum) or (None, None)."""
    try:
        temperature = sensor.temperature
        humidity = sensor.humidity
        if temperature is None or humidity is None:
            print("[read_dht22] Sensor returned None (checksum or timing error).", file=sys.stderr)
            return None, None
        return temperature, humidity
    except RuntimeError as exc:
        # DHT22 checksum / timing errors are common; log and continue.
        print(f"[read_dht22] Read error: {exc}", file=sys.stderr)
        return None, None
    except Exception as exc:
        print(f"[read_dht22] Unexpected error: {exc}", file=sys.stderr)
        return None, None


def display_data(lcd, temperature, humidity):
    """Write temperature and humidity to the LCD; return True on success."""
    try:
        lcd.message = f"Temp: {temperature:.1f} C\nHumidity: {humidity:.1f}%"
        return True
    except Exception as exc:
        print(f"[display_data] LCD write failed: {exc}", file=sys.stderr)
        return False


def main():
    global _lcd, _sensor

    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    i2c_bus = init_i2c()
    if i2c_bus is None:
        sys.exit(1)

    _lcd = init_lcd(i2c_bus, I2C_ADDR)
    if _lcd is None:
        sys.exit(1)

    _sensor = init_dht22(DHT_PIN)
    if _sensor is None:
        sys.exit(1)

    try:
        while _running:
            temperature, humidity = read_dht22(_sensor)
            if temperature is not None and humidity is not None:
                display_data(_lcd, temperature, humidity)
            else:
                print("[main] Skipping display update due to read failure.", file=sys.stderr)
            time.sleep(UPDATE_INTERVAL_S)
    except Exception as exc:
        print(f"[main] Fatal error: {exc}", file=sys.stderr)
    finally:
        _cleanup()


if __name__ == "__main__":
    main()

