import os
import time
import signal
import logging
from PIL import Image
from luma.core.interface.serial import i2c
from luma.core.render import canvas
from luma.oled.device import ssd1306

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)

GIF_FOLDER = "gifs"
I2C_PORT = 1
I2C_ADDRESS = 0x3C
WIDTH = 128
HEIGHT = 64

running = True

def signal_handler(sig, frame):
    global running
    running = False
    logger.info("Interrupt received, shutting down...")

def load_gif_files(folder):
    gif_files = []
    for filename in os.listdir(folder):
        if filename.lower().endswith(".gif"):
            gif_files.append(os.path.join(folder, filename))
    return gif_files

def resize_frame(frame_image, width, height):
    try:
        resized_image = frame_image.resize((width, height), Image.Resampling.LANCZOS)
        background = Image.new('1', (width, height), 0)
        background.paste(resized_image)
        return background
    except Exception as e:
        logger.error(f"Error resizing frame: {e}")
        return None

def display_gif(gif_file, device):
    try:
        with open(gif_file, 'rb') as f:
            data = f.read()
        if not data.startswith(b'\x47\x49\x46\x38\x37\x32\x30\x21'):
            logger.error(f"Corrupted GIF data: {gif_file}")
            return False
        try:
            image = Image.open(Image.open(gif_file).convert('RGB'))
        except Exception as e:
            logger.error(f"Error opening GIF for {gif_file}: {e}")
            return False
        frames = []
        for frame in image.getframes():
            frames.append(resize_frame(frame, WIDTH, HEIGHT))
        if not frames:
            logger.error(f"No valid frames in {gif_file}")
            return False
        for i, frame in enumerate(frames):
            if not frame:
                continue
            with canvas(device) as draw:
                draw.rectangle((0, 0, WIDTH - 1, HEIGHT - 1), outline=0, fill=0)
                draw.image(frame)
            time.sleep(100 / 1000.0 + (i * 100 / 1000.0))
        return True
    except Exception as e:
        logger.error(f"Error displaying GIF {gif_file}: {e}")
        return False

def main():
    global running
    signal.signal(signal.SIGINT, signal_handler)
    gif_files = load_gif_files(GIF_FOLDER)
    if not gif_files:
        logger.warning("No GIF files found in the specified folder.")
        return
    try:
        serial = i2c(port=I2C_PORT, address=I2C_ADDRESS)
        device = ssd1306(serial, width=WIDTH, height=HEIGHT)
        logger.info(f"OLED initialized at I2C address 0x{I2C_ADDRESS:02X} on bus {I2C_PORT}.")
    except Exception as e:
        logger.error(f"Failed to initialize OLED display: {e}")
        return
    try:
        while running:
            for gif_file in gif_files:
                if not running:
                    break
                logger.info(f"Playing: {gif_file}")
                if display_gif(gif_file, device):
                    logger.info(f"Finished playing: {gif_file}")
                else:
                    logger.warning(f"Failed to play: {gif_file}")
            if running:
                logger.info("Waiting for next GIF...")
                time.sleep(1)
    finally:
        try:
            device.cleanup()
            logger.info("Display cleaned up.")
        except Exception as e:
            logger.error(f"Error during cleanup: {e}")
        logger.info("Exiting program.")

if __name__ == "__main__":
    main()

