import time
import board
import busio
import adafruit_ssd1306
import adafruit_dht

# Initialize I2C bus
i2c = busio.I2C(board.SCL, board.SDA)

# Initialize OLED display (128x64)
oled = adafruit_ssd1306.SSD1306_I2C(128, 64, i2c)

# Initialize DHT22 sensor on GPIO4
dht_device = adafruit_dht.DHT22(board.D4)

def clear_display():
    """Clear the OLED display."""
    oled.fill(0)
    oled.show()

def read_sensor():
    """Read temperature and humidity from DHT22 with retry."""
    for attempt in range(3):
        try:
            temperature = dht_device.temperature
            humidity = dht_device.humidity
            if temperature is not None and humidity is not None:
                return temperature, humidity
        except RuntimeError as e:
            # DHT22 often throws transient errors; retry
            if attempt < 2:
                time.sleep(0.5)
            else:
                raise
        except Exception as e:
            raise RuntimeError(f"Sensor read failed: {e}")
    return None, None

def display_data(temperature, humidity):
    """Display temperature and humidity on OLED."""
    clear_display()
    oled.text(f"Temp: {temperature:.1f} C", 0, 0, 1)
    oled.text(f"Hum: {humidity:.1f} %", 0, 16, 1)
    oled.show()

def main():
    try:
        while True:
            temperature, humidity = read_sensor()
            if temperature is not None and humidity is not None:
                display_data(temperature, humidity)
            else:
                print("Failed to read sensor after retries.")
            time.sleep(2)
    except KeyboardInterrupt:
        print("\nExiting...")
    finally:
        clear_display()
        dht_device.exit()
        i2c.deinit()

if __name__ == "__main__":
    main()

