import signal
import sys
import time

try:
    from smbus2 import SMBus
except ImportError:
    print("Error: smbus2 library not found. Install with: pip install smbus2")
    sys.exit(1)

# PCF8574 I2C address (A0-A2 tied to GND)
PCF8574_ADDR = 0x20
I2C_BUS = 1

# PCF8574 register map
PCF8574_OUT_H = 0x00
PCF8574_OUT_L = 0x01
PCF8574_PUD = 0x0C  # PUD[1:0] = 11 -> pull-up on all pins

NUM_SENSORS = 8
POLL_INTERVAL_S = 0.1
RETRY_DELAY_S = 1.0

_running = True


def _signal_handler(signum, frame):
    global _running
    _running = False


def _write_output(bus, addr, reg, value):
    bus.write_byte_data(addr, reg, value)


def _read_input(bus, addr, reg):
    return bus.read_byte_data(addr, reg)


def main():
    global _running

    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    bus = None
    try:
        bus = SMBus(I2C_BUS)
    except OSError as e:
        print(f"Error: cannot open I2C bus {I2C_BUS}: {e}")
        sys.exit(1)

    try:
        # Configure all expander pins as inputs with internal pull-up enabled
        _write_output(bus, PCF8574_ADDR, PCF8574_PUD, 0xFF)
        print("PCF8574 initialized. Polling proximity sensors (Ctrl-C to quit)...")

        while _running:
            obstacle_count = 0
            for i in range(NUM_SENSORS):
                pin = i
                try:
                    state = _read_input(bus, PCF8574_ADDR, PCF8574_OUT_H)
                    if state & 0x01:
                        obstacle_count += 1
                        print(f"Obstacle detected by sensor {pin}")
                except OSError as e:
                    print(f"Error reading sensor {pin}: {e}")
                    # Continue polling other sensors; this one is skipped this cycle
                    continue

            if obstacle_count > 0:
                print(f"Total obstacles: {obstacle_count}")

            time.sleep(POLL_INTERVAL_S)

    except Exception as e:
        print(f"Unexpected error: {e}")
    finally:
        if bus is not None:
            try:
                bus.close()
            except OSError:
                pass
        print("\nProgram terminated.")


if __name__ == "__main__":
    main()

