import time
import sys
import board
import adafruit_dht

# DHT11 data pin connected to GPIO4 (BCM numbering, physical pin 7)
DHT_PIN = board.D4

# Attempt up to 5 reads; DHT11 requires >=1 s between reads
MAX_RETRIES = 5
RETRY_DELAY = 2.0  # seconds between retries


def read_dht11():
    """
    Read temperature and humidity from a DHT11 sensor.
    Returns (temperature_c, humidity) or (None, None) on failure.
    """
    sensor = None
    try:
        sensor = adafruit_dht.DHT11(DHT_PIN, use_pulseio=False)
    except Exception as exc:
        print(f"Error: failed to initialize DHT11 on GPIO4: {exc}")
        return None, None

    for attempt in range(1, MAX_RETRIES + 1):
        try:
            temperature_c = sensor.temperature
            humidity = sensor.humidity
            if temperature_c is not None and humidity is not None:
                return temperature_c, humidity
        except RuntimeError as exc:
            # Common DHT11 transient errors: checksum mismatch, timeout
            print(f"Attempt {attempt}/{MAX_RETRIES}: read error: {exc}")
        except Exception as exc:
            print(f"Attempt {attempt}/{MAX_RETRIES}: unexpected error: {exc}")
        if attempt < MAX_RETRIES:
            time.sleep(RETRY_DELAY)

    return None, None


def main():
    temperature_c, humidity = read_dht11()

    if temperature_c is not None and humidity is not None:
        print(f"Temperature: {temperature_c:.1f} C")
        sys.exit(0)
    else:
        print("Error: failed to read DHT11 sensor after 5 attempts.")
        sys.exit(1)


if __name__ == "__main__":
    try:
        main()
    except KeyboardInterrupt:
        print("\nInterrupted by user. Exiting gracefully.")
        sys.exit(1)

