import signal
import sys
import time
import logging
from smbus2 import SMBus

logging.basicConfig(level=logging.INFO, format="%(asctime)s [%(levelname)s] %(message)s")
log = logging.getLogger("dht20")

I2C_BUS = 1
I2C_ADDR = 0x38
CMD_MEASURE = [0x33, 0x00]
REG_STATUS = 0x71
REG_DATA = 0xAC
STATUS_TIMEOUT = 0.1
POLL_INTERVAL = 0.01

_running = True


class DHT20:
    def __init__(self, bus_num=I2C_BUS, addr=I2C_ADDR):
        self.addr = addr
        self.bus = None
        try:
            self.bus = SMBus(bus_num)
        except OSError as exc:
            log.error("Cannot open /dev/i2c-%d: %s", bus_num, exc)
            self.bus = None
        if self.bus is None:
            log.error("DHT20 not detected at 0x%02X on bus %d — check wiring and address", addr, bus_num)
            return
        try:
            self.bus.read_byte_data(addr, REG_STATUS)
        except OSError as exc:
            log.error("I2C read of status reg 0x%02X failed: %s", REG_STATUS, exc)
            self.bus.close()
            self.bus = None
        if self.bus is None:
            log.error("DHT20 not responding — sensor absent or bus closed")
            return
        log.info("DHT20 initialised on bus %d at 0x%02X", bus_num, addr)

    def measure(self):
        if self.bus is None:
            log.error("I2C bus not initialised")
            return None, None, True
        try:
            self.bus.write_i2c_block_data(self.addr, REG_DATA, CMD_MEASURE)
        except OSError as exc:
            log.error("I22 write to 0x%02X failed: %s", self.addr, exc)
            return None, None, True
        deadline = time.monotonic() + STATUS_TIMEOUT
        while True:
            try:
                status = self.bus.read_byte_data(self.addr, REG_STATUS)
            except OSError as exc:
                log.error("I2C read of status reg 0x%02X failed: %s", REG_STATUS, exc)
                return None, None, True
            if status & 0x80:
                break
            if time.monotonic() > deadline:
                log.error("DHT20 measurement timed out (polling %d ms)")
                return None, None, True
            time.sleep(POLL_INTERVAL)
        try:
            data = self.bus.read_i2c_block_data(self.addr, REG_DATA, 7)
        except OSError as exc:
            log.error("I2C read of data reg 0x%02X failed: %s", REG_DATA, exc)
            return None, None, True
        if len(data) < 7:
            log.error("Short read: got %d bytes, expected 7", len(data))
            return None, None, True
        crc = self._crc8(data[:6])
        if data[6] != crc:
            log.error("CRC mismatch: sensor sent 0x%02X, calculated 0x%02X", data[6], crc)
            return None, None, True
        humidity_raw = ((data[1] << 12) | (data[2] << 4) | (data[3] >> 4)) & 0xFFFFF
        temp_raw = (((data[3] & 0x0F) << 16) | (data[4] << 8) | data[5]) & 0xFFFFF
        temperature = float(temp_raw) / 5242.88 - 50.0
        humidity = float(humidity_raw) / 0x100000 * 100.0
        return temperature, humidity, False

    @staticmethod
    def _crc8(data):
        crc = 0xFF
        for b in data:
            crc ^= b
            for _ in range(8):
                if crc & 0x80:
                    crc = ((crc << 1) ^ 0x31) & 0xFF
                else:
                    crc = (crc << 1) & 0xFF
        return crc

    def close(self):
        if self.bus is not None:
            try:
                self.bus.close()
            except OSError:
                pass
            self.bus = None


def _signal_handler(signum, frame):
    global _running
    _running = False
    log.info("Signal %d received, shutting down", signum)


def main():
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)
    sensor = DHT20()
    if sensor.bus is None:
        sys.exit(1)
    try:
        temp, hum, err = sensor.measure()
        if err:
            log.error("Measurement failed: %s", err)
        else:
            print(f"Temperature: {temp:.2f} C  Humidity: {hum:.2f} %")
    finally:
        sensor.close()


if __name__ == "__main__":
    main()

