import signal
import sys
import time

from gpiozero import LED, DistanceSensor
from gpiozero.exc import GPIOZeroError

try:
    from hcsr04sensor import Hcsr04Sensor
except ImportError:
    Hcsr04Sensor = None

TRIGGER_PIN = 17
ECHO_PIN = 18
LED_PIN = 2
SAFE_DISTANCE = 20.0
LOOP_DELAY = 0.1
SAFE_DISTANCE_ERROR = SAFE_DISTANCE + 10.0

running = True
led = None
sensor = None


def handle_signal(signum, frame):
    global running
    running = False


def cleanup():
    global led, sensor
    if led is not None:
        try:
            led.off()
            led.close()
        except Exception:
            pass
        led = None
    if sensor is not None:
        try:
            sensor.close()
        except Exception:
            pass
        sensor = None


def main():
    global led, sensor

    signal.signal(signal.SIGINT, handle_signal)
    signal.signal(signal.SIGTERM, handle_signal)

    try:
        led = LED(LED_PIN)
    except GPIOZeroError as exc:
        print(f"Failed to initialize LED on GPIO{LED_PIN}: {exc}", file=sys.stderr)
        sys.exit(1)

    if Hcsr04Sensor is None:
        print("hcsr04sensor library not installed; running in safe-mode only.", file=sys.stderr)

    try:
        sensor = Hcsr04Sensor(TRIGGER_PIN, ECHO_PIN, temperature=20)
    except Exception as exc:
        print(f"Failed to initialize HC-SR04 sensor: {exc}", file=sys.stderr)
        sensor = None

    try:
        while running:
            distance = SAFE_DISTANCE_ERROR

            if sensor is not None:
                try:
                    distance = sensor.get_distance()
                except Exception as exc:
                    print(f"Error reading HC-SR04: {exc}", file=sys.stderr)
                    distance = SAFE_DISTANCE_ERROR

            if distance <= SAFE_DISTANCE:
                led.on()
            else:
                led.off()

            print(f"Distance: {distance:.2f} cm, LED: {'ON' if led.is_lit else 'OFF'}")

            time.sleep(LOOP_DELAY)
    finally:
        cleanup()


if __name__ == "__main__":
    main()

