import time
import random
import logging
import sqlite3
from gpiozero import LED
from collections import deque

# Configuration
STATUS_LED_PIN = 23
DATABASE_PATH = '/tmp/wearable_health.db'
WINDOW_SIZE = 20
ALERT_THRESHOLD_HOURS = 100
MAX_REMAINING_LIFE_HOURS = 500
DEGRADATION_FACTOR = 0.6
TEMPERATURE_SCALE = 100.0
VIBRATION_SCALE = 0.9
ITERATIONS = 30
SAMPLE_INTERVAL = 0.05  # 50 ms

# Logging setup
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

# Global state
vibration_window = deque(maxlen=WINDOW_SIZE)
temperature_window = deque(maxlen=WINDOW_SIZE)
alert_active = False
status_led = None
db_conn = None


def setup_gpio():
    """Initialize the status LED on GPIO23."""
    global status_led
    try:
        status_led = LED(STATUS_LED_PIN)
        status_led.off()
        logging.info(f"Status LED initialized on GPIO{STATUS_LED_PIN}")
    except Exception as e:
        logging.error(f"Failed to initialize status LED: {e}")
        raise


def setup_database():
    """Create the alerts table if it doesn't exist."""
    global db_conn
    try:
        db_conn = sqlite3.connect(DATABASE_PATH)
        cursor = db_conn.cursor()
        cursor.execute('''
            CREATE TABLE IF NOT EXISTS alerts (
                remaining_life REAL,
                ts REAL
            )
        ''')
        db_conn.commit()
        logging.info("Database initialized successfully.")
    except sqlite3.Error as e:
        logging.error(f"Database setup failed: {e}")
        raise


def read_vibration():
    """Simulate vibration sensor reading (0.1 to 0.9 units)."""
    try:
        return random.uniform(0.1, 0.9)
    except Exception as e:
        logging.error(f"Vibration read error: {e}")
        return None


def read_temperature():
    """Simulate temperature sensor reading (30.0 to 70.0°C)."""
    try:
        return random.uniform(30.0, 70.0)
    except Exception as e:
        logging.error(f"Temperature read error: {e}")
        return None


def calculate_degradation(vibration, temperature):
    """Calculate degradation score from vibration and temperature."""
    if vibration is None or temperature is None:
        return 0.0
    return DEGRADATION_FACTOR * vibration + (DEGRADATION_FACTOR * temperature) / TEMPERATURE_SCALE


def estimate_remaining_life(degradation_score):
    """Estimate remaining useful life in hours."""
    if degradation_score <= 0:
        return 0.0
    return max(0.0, MAX_REMAINING_LIFE_HOURS * (1.0 - (degradation_score / 3.0)))


def store_alert(remaining_life):
    """Store an alert in the database."""
    global db_conn
    if db_conn is None:
        logging.warning("Database not connected; cannot store alert.")
        return
    try:
        cursor = db_conn.cursor()
        cursor.execute(
            "INSERT INTO alerts (remaining_life, ts) VALUES (?, ?)",
            (remaining_life, time.time())
        )
        db_conn.commit()
        logging.warning(f"Alert stored: remaining life={remaining_life:.2f} hours")
    except sqlite3.Error as e:
        logging.error(f"Failed to store alert: {e}")


def blink_led():
    """Blink the status LED 1 second on, 1 second off."""
    if status_led is None:
        return
    try:
        status_led.on()
        time.sleep(1)
        status_led.off()
        time.sleep(1)
    except Exception as e:
        logging.error(f"LED blink error: {e}")


def cleanup():
    """Release resources on exit."""
    global status_led, db_conn
    if status_led is not None:
        try:
            status_led.close()
            logging.info("Status LED released.")
        except Exception as e:
            logging.error(f"Error releasing LED: {e}")
    if db_conn is not None:
        try:
            db_conn.close()
            logging.info("Database connection closed.")
        except Exception as e:
            logging.error(f"Error closing database: {e}")


def main():
    """Main predictive maintenance loop."""
    global alert_active
    try:
        setup_gpio()
        setup_database()
    except Exception as e:
        logging.error(f"Initialization failed: {e}")
        cleanup()
        return

    logging.info("Starting predictive maintenance loop.")

    try:
        for i in range(ITERATIONS):
            vibration = read_vibration()
            temperature = read_temperature()

            if vibration is None or temperature is None:
                logging.warning(f"Skipping iteration {i+1}: sensor read failed.")
                time.sleep(SAMPLE_INTERVAL)
                continue

            vibration_window.append(vibration)
            temperature_window.append(temperature)

            degradation = calculate_degradation(vibration, temperature)
            remaining = estimate_remaining_life(degradation)

            if remaining < ALERT_THRESHOLD_HOURS:
                if not alert_active:
                    logging.warning(
                        f"ALERT: Remaining life {remaining:.2f} hours, "
                        f"degradation {degradation:.2f}"
                    )
                    store_alert(remaining)
                    alert_active = True
                blink_led()
            else:
                if alert_active:
                    logging.info(
                        f"Remaining life {remaining:.2f} hours, "
                        f"degradation {degradation:.2f}"
                    )
                    alert_active = False

            time.sleep(SAMPLE_INTERVAL)

    except KeyboardInterrupt:
        logging.info("Predictive maintenance stopped by user.")
    except Exception as e:
        logging.error(f"Unexpected error: {e}")
    finally:
        cleanup()
        logging.info("Program finished.")


if __name__ == "__main__":
    main()

