import time
import signal
import sys
from gpiozero import PWMOutputDevice

FAN_PIN = 18
PWM_FREQ = 50
TEMP_FILE = '/sys/class/thermal/thermal_zone0/temp'
INTERVAL = 1.0
MIN_TEMP = 40.0
MAX_TEMP = 50.0
MIN_DUTY = 0.0
MAX_DUTY = 100.0

fan = None
running = True

def cleanup(signum=None, frame=None):
    global running
    running = False
    if fan is not None:
        try:
            fan.close()
        except Exception:
            pass
    if signum is not None:
        sys.exit(0)

def get_cpu_temp():
    try:
        with open(TEMP_FILE, 'r') as f:
            return float(f.read().strip()) / 1000.0
    except (IOError, OSError, ValueError) as e:
        print(f"Error reading CPU temperature: {e}", file=sys.stderr)
        return None

def compute_duty(temp):
    if temp <= MIN_TEMP:
        return MIN_DUTY
    if temp >= MAX_TEMP:
        return MAX_DUTY
    return (temp - MIN_TEMP) * (MAX_DUTY - MIN_DUTY) / (MAX_TEMP - MIN_TEMP) + MIN_DUTY

def main():
    global fan
    signal.signal(signal.SIGTERM, cleanup)
    try:
        fan = PWMOutputDevice(FAN_PIN, frequency=PWM_FREQ, initial_value=0.0)
    except Exception as e:
        print(f"Failed to initialize PWM on GPIO{FAN_PIN}: {e}", file=sys.stderr)
        sys.exit(1)
    try:
        while running:
            temp = get_cpu_temp()
            if temp is not None:
                duty = compute_duty(temp)
                fan.value = duty / 100.0
                print(f"CPU Temp: {temp:.1f}C  ->  Fan Duty: {duty:.1f}%")
            else:
                print("Skipping iteration due to temperature read error.", file=sys.stderr)
            time.sleep(INTERVAL)
    except KeyboardInterrupt:
        pass
    finally:
        cleanup()

if __name__ == '__main__':
    main()

