import time
import signal
import sys
import board
import adafruit_dht

# Global sensor handle for cleanup
_sensor = None

def cleanup():
    """Release sensor resources if held."""
    global _sensor
    if _sensor is not None:
        try:
            _sensor.exit()
        except Exception:
            pass
        _sensor = None

def signal_handler(signum, frame):
    """Handle SIGINT/SIGTERM for clean shutdown."""
    print("\nInterrupt received, exiting...")
    cleanup()
    sys.exit(0)

def main():
    global _sensor

    # Register signal handlers for graceful shutdown
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    # Initialize DHT11 on GPIO4 (board.D4)
    try:
        _sensor = adafruit_dht.DHT11(board.D4, use_pulseio=False)
    except Exception as e:
        print(f"Failed to initialize DHT11 on GPIO4: {e}")
        sys.exit(1)

    print("DHT11 sensor initialized. Reading every 5 seconds. Press Ctrl+C to stop.")

    try:
        while True:
            try:
                temperature = _sensor.temperature
                humidity = _sensor.humidity

                if temperature is not None and humidity is not None:
                    print(f"Temperature: {temperature:.1f} C")
                    print(f"Humidity: {humidity:.1f} %")
                else:
                    print("Sensor returned None for temperature or humidity.")

            except RuntimeError as e:
                # DHT sensors frequently throw RuntimeError on timing glitches
                print(f"Sensor read error: {e}")
            except Exception as e:
                print(f"Unexpected error during read: {e}")

            time.sleep(5)

    except KeyboardInterrupt:
        print("\nInterrupted by user.")
    finally:
        cleanup()
        print("Resources released. Goodbye.")

if __name__ == "__main__":
    main()

