import time
import board
import busio
import adafruit_bmp280

LOG_FILE = 'altitude_log.txt'
I2C_ADDR = 0x76
SEA_LEVEL_PRESSURE = 1013.25  # hPa


def main():
    i2c = busio.I2C(board.SCL, board.SDA)
    try:
        bmp = adafruit_bmp280.Adafruit_BMP280_I2C(i2c, address=I2C_ADDR)
    except Exception as exc:
        print(f"Error: failed to initialize BMP280 at 0x{I2C_ADDR:02X}: {exc}")
        return 1

    try:
        bmp.sea_level_pressure = SEA_LEVEL_PRESSURE
    except Exception as exc:
        print(f"Warning: could not set sea_level_pressure: {exc}")

    print("BMP280 initialized. Reading every 1 s. Press Ctrl+C to stop.")
    try:
        while True:
            try:
                pressure = bmp.pressure
                altitude = bmp.altitude
            except Exception as exc:
                print(f"Warning: sensor read failed: {exc}")
                time.sleep(1)
                continue

            print(f"Pressure: {pressure:.2f} hPa, Altitude: {altitude:.2f} meters")
            timestamp = time.strftime('%Y-%m-%d %H:%M:%S')
            try:
                with open(LOG_FILE, 'a') as f:
                    f.write(f"{timestamp} - Pressure: {pressure:.2f} hPa, Altitude: {altitude:.2f} meters\n")
            except OSError as exc:
                print(f"Warning: could not write to log file: {exc}")

            time.sleep(1)
    except KeyboardInterrupt:
        print("\nProgram terminated by user.")
    finally:
        print("Exiting program.")


if __name__ == '__main__':
    raise SystemExit(main())

