import time
import signal
import sys
import board
import busio
import adafruit_ahtx0

# Global flag for graceful shutdown
_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def initialize_i2c():
    """Initialize the I2C bus on board.SCL / board.SDA."""
    try:
        i2c = busio.I2C(board.SCL, board.SDA)
        # Scan the bus to confirm the AHT20 is present at address 0x38
        while not i2c.try_lock():
            pass
        try:
            devices = i2c.scan()
        finally:
            i2c.unlock()
        if 0x38 not in devices:
            print(f"AHT20 not found at I2C address 0x38. "
                  f"Detected devices: {[hex(d) for d in devices]}")
            i2c.deinit()
            return None
        return i2c
    except Exception as e:
        print(f"Error initializing I2C bus: {e}")
        return None

def initialize_sensor(i2c_bus):
    """Initialize the AHT20 sensor on the I2C bus."""
    try:
        sensor = adafruit_ahtx0.AHTx0(i2c_bus)
        # Force a measurement to confirm the sensor is responding
        _ = sensor.temperature
        return sensor
    except Exception as e:
        print(f"Error initializing AHT20 sensor: {e}")
        return None

def read_sensor_data(sensor):
    """Read temperature and humidity from the AHT20 sensor."""
    try:
        temperature = sensor.temperature
        humidity = sensor.humidity
        if temperature is None or humidity is None:
            raise RuntimeError("Sensor returned None for temperature or humidity")
        return temperature, humidity
    except Exception as e:
        print(f"Error reading sensor data: {e}")
        return None, None

def validate_data(temperature, humidity):
    """Validate that the readings are within the expected ranges."""
    if not (-40.0 <= temperature <= 85.0):
        print(f"Invalid temperature reading: {temperature} C")
        return False
    if not (0.0 <= humidity <= 100.0):
        print(f"Invalid humidity reading: {humidity} %")
        return False
    return True

def display_data(timestamp, temperature, humidity):
    """Print the sensor data in a formatted way."""
    if not validate_data(temperature, humidity):
        return
    print(f"{timestamp} Temperature: {temperature:.1f} C Humidity: {humidity:.1f} %")

def main():
    """Main function to read and display sensor data."""
    global _running

    # Register signal handlers for graceful shutdown
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    i2c_bus = initialize_i2c()
    if i2c_bus is None:
        return

    sensor = initialize_sensor(i2c_bus)
    if sensor is None:
        i2c_bus.deinit()
        return

    try:
        while _running:
            temperature, humidity = read_sensor_data(sensor)
            timestamp = time.strftime("%Y-%m-%d %H:%M:%S")
            if temperature is not None and humidity is not None:
                display_data(timestamp, temperature, humidity)
            else:
                print(f"Failed to read sensor data at {timestamp}")
            # Wait 5 seconds between readings
            time.sleep(5)
    except Exception as e:
        print(f"Unexpected error in main loop: {e}")
    finally:
        print("Shutting down...")
        try:
            i2c_bus.deinit()
        except Exception:
            pass
        print("Program finished.")

if __name__ == "__main__":
    main()

