import serial
import time
import signal
import sys
import board
import adafruit_dht

# --- Configuration -----------------------------------------------------------
SERIAL_PORT = '/dev/ttyS0'
BAUD_RATE = 9600
READ_INTERVAL = 1.0          # seconds between readings
DHT_PIN = board.D4           # GPIO4 (physical pin 7)

# --- Globals for cleanup -----------------------------------------------------
serial_connection = None
dht_sensor = None
running = True


def cleanup():
    """Release serial and sensor resources."""
    global serial_connection, dht_sensor
    if serial_connection is not None and serial_connection.is_open:
        try:
            serial_connection.close()
            print("Serial port closed.")
        except Exception as exc:
            print(f"Error closing serial port: {exc}")
    if dht_sensor is not None:
        try:
            dht_sensor.exit()
        except Exception as exc:
            print(f"Error releasing DHT sensor: {exc}")


def signal_handler(signum, frame):
    """Handle SIGINT / SIGTERM for graceful shutdown."""
    global running
    running = False


def transmit_reading(temperature):
    """Send one temperature reading over UART."""
    if serial_connection is None or not serial_connection.is_open:
        print("Serial port not open; cannot transmit.")
        return
    payload = f"Temperature: {temperature:.2f}C\n".encode('utf-8')
    try:
        bytes_written = serial_connection.write(payload)
        serial_connection.flush()
        if bytes_written == len(payload):
            print(f"Transmitted: {payload.strip()}")
        else:
            print(f"Warning: incomplete write ({bytes_written}/{len(payload)} bytes).")
    except serial.SerialException as exc:
        print(f"Serial I/O error: {exc}")
    except Exception as exc:
        print(f"Unexpected transmit error: {exc}")


def main():
    global serial_connection, dht_sensor, running

    # --- Signal handlers -----------------------------------------------------
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    # --- Initialize serial port --------------------------------------------
    try:
        serial_connection = serial.Serial(
            port=SERIAL_PORT,
            baudrate=BAUD_RATE,
            timeout=1,
            write_timeout=2
        )
        print(f"Serial port {SERIAL_PORT} opened at {BAUD_RATE} baud.")
    except serial.SerialException as exc:
        print(f"Failed to open serial port {SERIAL_PORT}: {exc}")
        sys.exit(1)

    # --- Initialize DHT22 sensor --------------------------------------------
    try:
        dht_sensor = adafruit_dht.DHT22(DHT_PIN, use_pulseio=False)
        print("DHT22 sensor initialized on GPIO4.")
    except Exception as exc:
        print(f"Failed to initialize DHT22 sensor: {exc}")
        cleanup()
        sys.exit(1)

    # --- Main loop -----------------------------------------------------------
    try:
        while running:
            try:
                temperature = dht_sensor.temperature
                if temperature is not None:
                    print(f"Temperature: {temperature:.2f}C")
                    transmit_reading(temperature)
                else:
                    print("Warning: DHT22 returned None for temperature.")
            except RuntimeError as exc:
                # Common DHT22 transient errors (e.g., checksum, timeout)
                print(f"DHT22 read error: {exc}")
            except Exception as exc:
                print(f"Unexpected error during read: {exc}")

            # Sleep in small increments so signals are caught promptly
            elapsed = 0.0
            while running and elapsed < READ_INTERVAL:
                time.sleep(0.1)
                elapsed += 0.1

    except Exception as exc:
        print(f"Fatal error in main loop: {exc}")
    finally:
        cleanup()
        print("Program terminated.")


if __name__ == "__main__":
    main()

