            elapsed = 0.0
            while running and elapsed < READ_INTERVAL:
                time.sleep(0.1)
                elapsed += 0.1

    except Exception as exc:
        print(f"Fatal error in main loop: {exc}")
    finally:
        cleanup()
        print("Program terminated.")


