    try:
        client = connect_mqtt()
        dht_device = init_dht22(config.dhtgpiopin)
        while running:
            temperature, humidity = read_dht22(dht_device)
            if publish_data(client, temperature, humidity):
                time.sleep(config.publishtime)
            else:
                logger.warning("Skipping next cycle due to publish failure")
                time.sleep(config.publishtime)
    except Exception as e:
        logger.error(f"Fatal error: {e}")
    finally:
        cleanup()


if __name__ == "__main__":
    main()

