import random
import time
import signal
import sys

try:
    from gpiozero import OutputDevice
    from gpiozero.exc import GPIOZeroError
except ImportError:
    print("Error: gpiozero is not installed. Install with: sudo apt install python3-gpiozero")
    sys.exit(1)

FAN_PIN = 18
TEMP_MIN = 20
TEMP_MAX = 40
TEMP_THRESHOLD = 30
NUM_READINGS = 5
DELAY_SECONDS = 2

fan = None
running = True

def signal_handler(signum, frame):
    global running
    running = False

signal.signal(signal.SIGINT, signal_handler)
signal.signal(signal.SIGTERM, signal_handler)

def read_temp():
    return random.randint(TEMP_MIN, TEMP_MAX)

def main():
    global fan
    try:
        fan = OutputDevice(FAN_PIN, active_high=True, initial_value=False)
    except GPIOZeroError as e:
        print(f"Error: Failed to initialize GPIO{FAN_PIN}: {e}")
        sys.exit(1)
    except Exception as e:
        print(f"Unexpected error initializing GPIO{FAN_PIN}: {e}")
        sys.exit(1)

    try:
        for i in range(NUM_READINGS):
            if not running:
                break
            temperature = read_temp()
            print(f"Reading {i + 1}/{NUM_READINGS} - Temperature: {temperature}°C")

            if temperature > TEMP_THRESHOLD:
                fan.on()
                print("  -> Fan ON: Temperature exceeds threshold.")
            else:
                fan.off()
                print("  -> Fan OFF: Temperature within normal range.")

            if i < NUM_READINGS - 1 and running:
                time.sleep(DELAY_SECONDS)

    except KeyboardInterrupt:
        print("\nProgram interrupted by user.")
    except Exception as e:
        print(f"Error during temperature simulation: {e}")
    finally:
        if fan is not None:
            try:
                fan.close()
                print("GPIO cleanup completed.")
            except Exception as e:
                print(f"Error during GPIO cleanup: {e}")

if __name__ == "__main__":
    main()

