#!/usr/bin/env python3
"""
DHT11 Temperature Monitor for Raspberry Pi

Reads temperature from a DHT11 sensor on GPIO4 (physical pin 7) every 5 seconds.
Uses adafruit_circuitpython_dht (imported as adafruit_dht) with board.D4.
Includes robust error handling, clean exit on Ctrl-C, and no silent crashes.
"""

import time
import board
import adafruit_dht

# Configuration
DHT_PIN = board.D4          # GPIO4 (physical pin 7)
READ_INTERVAL = 5           # seconds between readings
MAX_RETRIES = 3             # retries for RuntimeError on missed pulses


def main() -> None:
    # Initialize the DHT11 sensor on GPIO4.
    # use_pulseio=False is recommended on Raspberry Pi to avoid pulseio dependency issues.
    try:
        sensor = adafruit_dht.DHT11(DHT_PIN, use_pulseio=False)
    except Exception as exc:
        print(f"Failed to initialize DHT11 on GPIO4: {exc}")
        raise SystemExit(1)

    print("DHT11 Temperature Monitor started. Press Ctrl-C to stop.")

    try:
        while True:
            temperature = None
            for attempt in range(1, MAX_RETRIES + 1):
                try:
                    temperature = sensor.temperature
                    break
                except RuntimeError as exc:
                    # DHT11 occasionally misses pulses or has checksum errors.
                    print(f"Read attempt {attempt}/{MAX_RETRIES} failed: {exc}")
                    if attempt < MAX_RETRIES:
                        time.sleep(0.5)
                    else:
                        print("Max retries reached; skipping this cycle.")
                        break

            if temperature is not None:
                timestamp = time.strftime("%Y-%m-%d %H:%M:%S")
                print(f"[{timestamp}] Temperature: {temperature:.1f} °C")
            else:
                print("Failed to read temperature after retries.")

            time.sleep(READ_INTERVAL)

    except KeyboardInterrupt:
        print("\nProgram stopped by user.")
    except Exception as exc:
        print(f"Unexpected error: {exc}")
    finally:
        # Release the GPIO resource cleanly on all exit paths.
        try:
            sensor.exit()
        except Exception:
            pass
        print("GPIO cleanup completed.")


if __name__ == "__main__":
    main()

