import serial
import time
import signal
import sys

SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
READ_TIMEOUT = 1.0
TEMP_THRESHOLD = 30.0
HUMIDITY_THRESHOLD = 70.0

running = True

def signal_handler(signum, frame):
    global running
    running = False

def parse_sensor_data(data):
    """Parse a 'temperature,humidity' line into (temp, humidity) floats."""
    parts = data.split(',')
    if len(parts) != 2:
        raise ValueError(f"Expected 2 fields, got {len(parts)}")
    try:
        temperature = float(parts[0])
        humidity = float(parts[1])
    except ValueError:
        raise ValueError(f"Non-numeric data: {data!r}")
    return temperature, humidity

def main():
    global running
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    ser = None
    try:
        ser = serial.Serial(SERIAL_PORT, BAUD_RATE, timeout=READ_TIMEOUT)
        print(f"Opened {SERIAL_PORT} @ {BAUD_RATE} baud. Reading sensor data...")

        while running:
            try:
                raw = ser.readline()
            except serial.SerialException as e:
                print(f"Serial read error: {e}", file=sys.stderr)
                break

            if not raw:
                continue

            data = raw.decode('ascii', errors='replace').strip()
            if not data:
                continue

            try:
                temperature, humidity = parse_sensor_data(data)
            except ValueError as e:
                print(f"Parse error: {e}", file=sys.stderr)
                continue

            print(f"Temperature: {temperature:.1f}°C, Humidity: {humidity:.1f}%")

            if temperature > TEMP_THRESHOLD:
                print("ALERT: Temperature exceeds threshold!")
            if humidity > HUMIDITY_THRESHOLD:
                print("ALERT: Humidity exceeds threshold!")

            time.sleep(1)

    except serial.SerialException as e:
        print(f"Failed to open serial port {SERIAL_PORT}: {e}", file=sys.stderr)
        sys.exit(1)
    finally:
        if ser is not None and ser.is_open:
            ser.close()
            print("Serial port closed.")

if __name__ == '__main__':
    main()

