import signal
import sys
import time
from gpiozero import DigitalInputDevice
from gpiozero.exc import GPIOZeroError, GPIODeviceError

# GPIO pins (BCM numbering) for the three sensors
SENSOR_PINS = [17, 27, 22]
POLL_INTERVAL = 1.0  # seconds

# Global list of DigitalInputDevice objects for cleanup
sensors = []

def cleanup(signum=None, frame=None):
    """Release all GPIO resources and exit."""
    for sensor in sensors:
        try:
            sensor.close()
        except Exception:
            pass
    if signum is not None:
        sys.exit(0)

def main():
    # Register signal handlers for graceful shutdown
    signal.signal(signal.SIGTERM, cleanup)
    signal.signal(signal.SIGINT, cleanup)

    # Initialize each sensor with an active-high pull-up resistor
    for pin in SENSOR_PINS:
        try:
            sensor = DigitalInputDevice(pin, pull_up=True, bounce_time=0.05)
            sensors.append(sensor)
        except (GPIOZeroError, GPIODeviceError) as e:
            print(f"Error: Failed to initialize GPIO pin {pin}: {e}", file=sys.stderr)
            cleanup()
