import RPi.GPIO as GPIO
import time
import threading
import signal
import sys
import os

# Constants for GPIO pins
GPIO_PIN = 17

# Global variables
server_started = False
log_file = "log.txt"
log_lock = threading.Lock()
receive_thread = None
server_thread = None

# DOG class for data transfer
class DOG:
    def send(self, data):
        print(f"Sending data: {data}")
        return True

    def receive(self):
        data = input("Enter data to receive: ")
        print(f"Received data: {data}")
        return data

# Function to handle data transfer
def transfer_data(data):
    try:
        if not server_started:
            print("Server not started. Please start the server first.")
            return
        with log_lock:
            with open(log_file, "a") as f:
                f.write(data + "\n")
    except Exception as e:
        print(f"Error writing to log file: {e}")

# Function to handle data logging
def log_data(data):
    try:
        with log_lock:
            with open(log_file, "a") as f:
                f.write(data + "\n")
    except Exception as e:
        print(f"Error writing to log file: {e}")

# Function to start the data logging server
def start_server(filename):
    global server_started, receive_thread, server_thread
    if server_started:
        print("Server already started.")
        return
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(GPIO_PIN, GPIO.IN, pull_up_down=GPIO.PUD_UP)
        server_started = True
        receive_thread = threading.Thread(target=receive_data, daemon=True)
        receive_thread.start()
        server_thread = threading.Thread(target=server_loop, daemon=True)
        server_thread.start()
        print(f"Server started. Logging to {filename}")
    except Exception as e:
        print(f"Error starting server: {e}")
        server_started = False

# Function to stop the data logging server
def stop_server():
    global server_started, receive_thread, server_thread
    if not server_started:
        print("Server not started. Nothing to stop.")
        return
    try:
        if receive_thread and receive_thread.is_alive():
            receive_thread.join()
        if server_thread and server_thread.is_alive():
            server_thread.join()
        server_started = False
        GPIO.cleanup()
        print("Server stopped and GPIO cleaned up.")
    except Exception as e:
        print(f"Error stopping server: {e}")

# Function to receive data
def receive_data():
    while server_started:
        try:
            data = DOG.receive()
            if data:
                transfer_data(data)
        except Exception as e:
            print(f"Error receiving data: {e}")
            break
        time.sleep(0.1)

