def server_loop():
    while server_started:
        try:
            command = input("Enter command: ").split()
            if not command:
                continue
            if command[0] == "start":
                if len(command) < 2:
                    print("Usage: start <filename>")
                    continue
                start_server(command[1])
            elif command[0] == "stop":
                stop_server()
            elif command[0] == "help":
                print("Available commands:")
                print("  start <filename>        Start the server and log to file")
                print("  stop                     Stop the server")
                print("  help <command>           Show help for command")
                print("  display                   Display log file contents")
                print("  send <data>              Send data using DOG.send()")
                print("  write <data>             Write data directly to log file")
                print("  exit                     Exit the server")
            elif command[0] == "display":
                try:
                    with log_lock:
                        with open(log_file, "r") as f:
                            print(f.read())
                except FileNotFoundError:
                    print("Log file not found.")
                except Exception as e:
                    print(f"Error displaying log file: {e}")
            elif command[0] == "send":
                if len(command) < 2:
                    print("Usage: send <data>")
                    continue
                transfer_data(command[1])
            elif command[0] == "write":
                if len(command) < 2:
                    print("Usage: write <data>")
                    continue
                log_data(command[1])
            elif command[0] == "exit":
                stop_server()
                sys.exit(0)
            else:
                print("Invalid command. Type 'help' for available commands.")
        except EOFError:
            break
        except Exception as e:
            print(f"Error in server loop: {e}")
            break

# Signal handler for graceful shutdown
def signal_handler(sig, frame):
    print("\nSignal received. Shutting down...")
    stop_server()
    sys.exit(0)

if __name__ == "__main__":
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)
    try:
        start_server("log.txt")
    except Exception as e:
        print(f"Failed to initialize GPIO: {e}")
        sys.exit(1)

