import time
import signal
import sys
import board
import busio
import adafruit_tsl2561
import RPi.GPIO as GPIO

PWM_PIN = 18
TSL2561_ADDR = 0x39
SAMPLE_INTERVAL = 1.0
PWM_FREQ = 1000
MAX_LUX = 1000.0

_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def init_i2c():
    try:
        return busio.I2C(board.SCL, board.SDA)
    except Exception as e:
        print(f"Fatal: I2C bus initialization failed: {e}", file=sys.stderr)
        sys.exit(1)

def init_sensor(i2c_bus):
    try:
        sensor = adafruit_tsl2561.TSL2561(i2c_bus, address=TSL2561_ADDR)
        sensor.gain = adafruit_tsl2561.GAIN_AUTO
        sensor.integration_time = adafruit_tsl2561.INTEGRATIONTIME_402MS
        return sensor
    except ValueError as e:
        print(f"Fatal: TSL2561 not detected at 0x{TSL2561_ADDR:02X}: {e}", file=sys.stderr)
        sys.exit(1)
    except Exception as e:
        print(f"Fatal: Sensor initialization failed: {e}", file=sys.stderr)
        sys.exit(1)

def lux_to_brightness(lux):
    return max(0.0, min(100.0, (lux / MAX_LUX) * 100.0))

def main():
    global _running

    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    i2c_bus = init_i2c()
    sensor = init_sensor(i2c_bus)

    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(PWM_PIN, GPIO.OUT)
        pwm = GPIO.PWM(PWM_PIN, PWM_FREQ)
        pwm.start(0)
    except Exception as e:
        print(f"Fatal: PWM setup failed: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        while _running:
            try:
                lux = sensor.lux
            except Exception as e:
                print(f"Warning: I2C read error: {e}", file=sys.stderr)
                lux = None

            if lux is not None:
                brightness = lux_to_brightness(lux)
                print(f"Lux: {lux:.2f}, Brightness: {brightness:.1f}%")
                pwm.ChangeDutyCycle(brightness)
            else:
                print("Sensor read failed; maintaining previous brightness.")

            time.sleep(SAMPLE_INTERVAL)
    except KeyboardInterrupt:
        pass
    finally:
        pwm.stop()
        GPIO.cleanup()
        try:
            i2c_bus.deinit()
        except Exception:
            pass
        print("Cleanup complete.")

if __name__ == "__main__":
    main()

