import RPi.GPIO as GPIO
import time
import sys

# IR sensor pins (BCM numbering)
LEFT_SENSOR_PIN = 5
RIGHT_SENSOR_PIN = 6

# Sampling interval in seconds
SAMPLE_INTERVAL = 0.5
# Number of samples to take
NUM_SAMPLES = 10

def setup_gpio():
    """Initialize GPIO mode and sensor pins."""
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(LEFT_SENSOR_PIN, GPIO.IN, pull_up_down=GPIO.PUD_DOWN)
        GPIO.setup(RIGHT_SENSOR_PIN, GPIO.IN, pull_up_down=GPIO.PUD_DOWN)
    except Exception as e:
        print(f"GPIO setup failed: {e}")
        sys.exit(1)

def read_sensor(pin):
    """Read a single IR sensor state (0=black line, 1=white surface)."""
    try:
        return GPIO.input(pin)
    except Exception as e:
        print(f"Error reading sensor on pin {pin}: {e}")
        return None

def decide_direction(left_state, right_state):
    """Return steering direction based on sensor states."""
    if left_state == 0 and right_state == 0:
        return "forward"
    elif left_state == 1 and right_state == 1:
        return "search"
    elif left_state == 0 and right_state == 1:
        return "turn-right"
    elif left_state == 1 and right_state == 0:
        return "turn-left"
    else:
        return "forward"

def main():
    setup_gpio()
    try:
        for i in range(NUM_SAMPLES):
            left_state = read_sensor(LEFT_SENSOR_PIN)
            right_state = read_sensor(RIGHT_SENSOR_PIN)
            if left_state is None or right_state is None:
                print(f"Sample {i+1}: Sensor read error, skipping")
                time.sleep(SAMPLE_INTERVAL)
                continue
            direction = decide_direction(left_state, right_state)
            print(f"Sample {i+1}: Left={left_state}, Right={right_state} -> {direction}")
            time.sleep(SAMPLE_INTERVAL)
    except KeyboardInterrupt:
        print("\nLine following stopped by user")
    except Exception as e:
        print(f"Unexpected error: {e}")
    finally:
        GPIO.cleanup()
        print("GPIO cleaned up")

if __name__ == "__main__":
    main()

