                print(f"Sample {i+1}: Sensor read error, skipping")
                time.sleep(SAMPLE_INTERVAL)
                continue
            direction = decide_direction(left_state, right_state)
            print(f"Sample {i+1}: Left={left_state}, Right={right_state} -> {direction}")
            time.sleep(SAMPLE_INTERVAL)
    except KeyboardInterrupt:
        print("\nLine following stopped by user")
    except Exception as e:
        print(f"Unexpected error: {e}")
    finally:
        GPIO.cleanup()
        print("GPIO cleaned up")

if __name__ == "__main__":
    main()

