#!/usr/bin/env python3
"""
Raspberry Pi driver for a 1.44-inch TFT display (ST7735S, 128x128) over 4-wire SPI.

Wiring (BCM numbering):
  RST  -> GPIO18
  DC   -> GPIO22
  LED  -> GPIO23
  SPI  -> CE0 (bus 0, device 0), SCLK=GPIO11, MOSI=GPIO10

The script initializes the display, renders a few test patterns, and cleans up
GPIO and SPI resources on exit.
"""

import signal
import sys
import time

import spidev
import RPi.GPIO as GPIO

# ---------------------------------------------------------------------------
# Pin definitions (BCM numbering)
# ---------------------------------------------------------------------------
RST_PIN = 18
DC_PIN = 22
LED_PIN = 23

# ST7735S commands
ST7735_SWRESET = 0x01
ST7735_SLPOUT = 0x11
ST7735_DISPON = 0x29
ST7735_CASET = 0x2A
ST7735_RASET = 0x2B
ST7735_RAMWR = 0x2C
ST7735_MADCTL = 0x36
ST7735_COLMOD = 0x3A

# Colors (RGB565)
BLACK = 0x0000
WHITE = 0xFFFF
RED = 0xF800
GREEN = 0x07E0

# Global resources for cleanup
_spi = None
_gpio_initialized = False


def _cleanup(signum=None, frame=None):
    """Release GPIO and SPI resources on exit or signal."""
    global _spi, _gpio_initialized
    if _spi is not None:
        try:
            _spi.close()
        except Exception:
            pass
        _spi = None
    if _gpio_initialized:
        try:
            GPIO.cleanup()
        except Exception:
            pass
        _gpio_initialized = False
    if signum is not None:
        sys.exit(0)


def _spi_write(data):
    """Write a list of bytes to the SPI bus."""
    _spi.xfer2(list(data))


def _spi_read(data):
    """Read a list of bytes from the SPI bus."""
    return _spi.xfer2(list(data))


def _spi_write_command(cmd):
    _spi_write([cmd])


def _spi_write_data(data):
    _spi_write(data)


def _spi_write_data_list(data_list):
    _spi_write(data_list)


def _spi_read_command():
    return _spi_read([0x00])


def _spi_read_data():
    return _spi_read([0x00])


def _spi_read_data_list():
    return _spi_read([0x00])


