#!/usr/bin/env python3
# -*- coding: utf-8 -*-

"""
Flask web server for controlling an LED on a Raspberry Pi.

Hardware:
  - LED + current-limiting resistor on GPIO 17 (BCM).

Dependencies:
  pip install flask gpiozero

Run:
  python3 app.py
  Open http://<host>:8080 in a browser.
"""

import signal
import sys
from flask import Flask, render_template_string
from gpiozero import LED
from gpiozero.exc import GPIOZeroError, BadPinFactory

app = Flask(__name__)

LED_PIN = 17
led = None


def init_led():
    """Initialize the LED on GPIO 17. Returns the LED object or None on failure."""
    global led
    try:
        led = LED(LED_PIN)
        print(f"LED initialized on GPIO {LED_PIN}.")
        return led
    except (BadPinFactory, GPIOZeroError) as e:
        print(f"GPIO initialization error: {e}", file=sys.stderr)
        return None
    except Exception as e:
        print(f"Unexpected error initializing LED: {e}", file=sys.stderr)
        return None


def cleanup(signum=None, frame=None):
    """Release the LED resource and exit cleanly."""
    global led
    if led is not None:
        try:
            led.close()
            print("LED resource released.")
        except Exception as e:
            print(f"Error releasing LED: {e}", file=sys.stderr)
        finally:
            led = None
    if signum is not None:
        sys.exit(0)


@app.route('/')
def index():
    """Render the index page with ON/OFF links."""
    return render_template_string(
        '<h1>LED Control</h1><a href="/light_on">Turn ON</a> | <a href="/light_off">Turn OFF</a>')


@app.route('/light_on')
def light_on():
    """Turn the LED on and return a status message."""
    if led is None:
        return render_template_string(
            '<h1>LED Control</h1><p>LED not initialized.</p><a href="/">Back</a>'), 500
    try:
        led.on()
        return render_template_string(
            '<h1>LED Control</h1><p>LED is ON.</p><a href="/">Back</a>'), 303
    except GPIOZeroError as e:
        print(f"GPIO error turning LED on: {e}", file=sys.stderr)
        return render_template_string(
            '<h1>LED Control</h1><p>Error turning LED on.</p><a href="/">Back</a>'), 500


@app.route('/light_off')
def light_off():
    """Turn the LED off and return a status message."""
    if led is None:
        return render_template_string(
            '<h1>LED Control</h1><p>LED not initialized.</p><a href="/">Back</a>'), 500
    try:
        led.off()
        return render_template_string(
            '<h1>LED Control</h1><p>LED is OFF.</p><a href="/">Back</a>'), 303
    except GPIOZeroError as e:
        print(f"GPIO error turning LED off: {e}", file=sys.stderr)
        return render_template_string(
            '<h1>LED Control</h1><p>Error turning LED off.</p><a href="/">Back</a>'), 500


if __name__ == '__main__':
    # Register signal handlers for clean shutdown
    signal.signal(signal.SIGINT, cleanup)
    signal.signal(signal.SIGTERM, cleanup)

    led = init_led()
    if led is None:
        print("Failed to initialize LED. Exiting.", file=sys.stderr)
        sys.exit(1)

    try:
        app.run(host='0.0.0.0', port=8080, debug=False)
    except Exception as e:
        print(f"Server error: {e}", file=sys.stderr)
    finally:
        cleanup()

