#!/usr/bin/env python3
"""OutputPin: robust GPIO output control via pigpio on Raspberry Pi."""

import pigpio
import time
import logging
import sys

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)


class OutputPin:
    """Controls a GPIO pin as an output using pigpio."""

    def __init__(self, pin_number: int, initial_value: int = 0) -> None:
        if not isinstance(pin_number, int) or not (0 <= pin_number <= 31):
            raise ValueError(f"Invalid pin number: {pin_number!r}. Must be an integer between 0 and 31.")
        if initial_value not in (0, 1):
            raise ValueError(f"Invalid initial value: {initial_value!r}. Must be 0 or 1.")

        self.pin_number = pin_number
        self.initial_value = initial_value
        self._pi: pigpio.pi | None = None
        self._closed = False

        try:
            self._pi = pigpio.pi()
            if not self._pi.connected:
                raise RuntimeError("Failed to connect to pigpio daemon. Is pigpiod running?")
            self._pi.set_mode(self.pin_number, pigpio.OUTPUT)
            self.set_value(self.initial_value)
            logger.info(f"OutputPin initialized on BCM GPIO {self.pin_number} with value {self.initial_value}")
        except Exception as e:
            logger.error(f"Error initializing OutputPin: {e}")
            self.shutdown()
            raise

    def set_value(self, value: int) -> None:
        if self._closed:
            raise RuntimeError("OutputPin has been closed; cannot set value.")
        if value not in (0, 1):
            raise ValueError(f"Invalid value: {value!r}. Must be 0 or 1.")
        try:
            self._pi.write(self.pin_number, value)
            logger.debug(f"Set BCM GPIO {self.pin_number} to {value}")
        except Exception as e:
            logger.error(f"Error setting value on BCM GPIO {self.pin_number}: {e}")
            raise

    def shutdown(self) -> None:
        if self._closed:
            return
        self._closed = True
        try:
            if self._pi is not None and self._pi.connected:
                self._pi.set_mode(self.pin_number, pigpio.INPUT)
                logger.info(f"BCM GPIO {self.pin_number} set to INPUT mode during shutdown.")
        except Exception as e:
            logger.error(f"Error during shutdown of BCM GPIO {self.pin_number}: {e}")
        finally:
            if self._pi is not None:
                self._pi.stop()
                self._pi = None

    def close(self) -> None:
        self.shutdown()


if __name__ == '__main__':
    try:
        output_pin = OutputPin(17, initial_value=0)
        logger.info("Starting toggle demo...")
        for _ in range(5):
            output_pin.set_value(1)
            time.sleep(0.5)
            output_pin.set_value(0)
            time.sleep(0.5)
        logger.info("Demo complete.")
    except Exception as e:
        logger.error(f"Fatal error: {e}")
        sys.exit(1)
    finally:
        if 'output_pin' in locals():
            output_pin.close()

