import atexit
import signal
import sys
import time

try:
    import spidev
except ImportError:
    spidev = None

try:
    from gpiozero import OutputDevice
except ImportError:
    OutputDevice = None

# ---------------------------------------------------------------------------
# Constants
# ---------------------------------------------------------------------------
WIDTH = 128
HEIGHT = 128

# ST7735 commands
ST7735_SWRESET = 0x01
ST7735_SLPOUT = 0x11
ST7735_DISPON = 0x29
ST7735_CASET = 0x2A
ST7735_RASET = 0x2B
ST7735_RAMWR = 0x2C
ST7735_MADCTL = 0x36
ST7735_COLMOD = 0x3A

# Colors (RGB565)
BLACK = 0x0000
WHITE = 0xFFFF
BLUE = 0x001F
RED = 0xF800
GREEN = 0x07E0

# ---------------------------------------------------------------------------
# ST7735 driver (hardware SPI0, CE0 -> GPIO8)
# ---------------------------------------------------------------------------
class ST7735:
    def __init__(self, spi, dc, rst, led, orientation=90):
        self.spi = spi
        self.dc = dc
        self.rst = rst
        self.led = led
        self.orientation = orientation
        self.width = WIDTH
        self.height = HEIGHT

        # Hardware reset
        self.rst.on()
        time.sleep(0.1)
        self.rst.off()
        time.sleep(0.1)
        self.rst.on()
        time.sleep(0.2)

        # Software reset
        self._write_cmd(ST7735_SWRESET)
        time.sleep(0.15)

        # Out of sleep mode
        self._write_cmd(ST7735_SLPOUT)
        time.sleep(0.5)

        # Set color format to 16-bit RGB565
        self._write_cmd(ST7735_COLMOD)
        self._write_data(16)

        # Memory access control: row/col order and mirror
        self._write_cmd(ST7735_MADCTL)
        if self.orientation == 90:
            self._write_data(0x80)  # MY=1, MX=1 (90 deg)
        elif self.orientation == 180:
            self._write_data(0xC0)  # MY=0, MX=0 (180 deg)
        elif self.orientation == 270:
            self._write_data(0x00)  # MY=0, MX=0 (270 deg)
        else:
            self._write_data(0x00)

        # Turn on display
        self._write_cmd(ST7735_DISPON)

        # Turn on backlight
        self.led.on()

    def _write_cmd(self, cmd):
        self.dc.off()
        self.spi.writebytes([cmd])

    def _write_data(self, data):
        self.dc.on()
        if isinstance(data, int):
            data = [data]
        self.spi.writebytes(list(data))

    def clear(self, color=BLACK):
        x0 = 0
        x1 = self.width - 1
        y0 = 0
        y1 = self.height - 1
        self._fill_rect(x0, y0, x1, y1, color)

    def _fill_rect(self, x0, y0, x1, y1, color):
        if x0 > x1:
            x0, x1 = x1, x0
        if y0 > y1:
            y0, y1 = y1, y0
        for y in range(y0, y1 + 1):
            self._fill_row(x0, y, x1, y1, color)

    def _fill_row(self, x0, y, x1, y1, color):
        for x in range(x0, x1 + 1):
            self._write_data(color)

    def put_char(self, char, x, y, fg=WHITE, bg=BLACK, font=1):
        # Simple 5x8 font (font 1-8) - placeholder
        pass

    def put_string(self, text, x, y, fg=WHITE, bg=BLACK, font=1):
        for i, ch in enumerate(text):
            self.put_char(ch, x + i * 6, y, fg, bg, font)

    def cleanup(self):
        try:
            self.clear(BLACK)
        except Exception:
            pass


# ---------------------------------------------------------------------------
# Stub implementations for environments without spidev or gpiozero
# ---------------------------------------------------------------------------
class StubSpi:
    def __init__(self):
        self._closed = False

    def close(self):
        self._closed = True

    def writebytes(self, data):
        pass


class StubOutputDevice:
    def __init__(self, pin):
        self.pin = pin
        self._closed = False

    def close(self):
        self._closed = True

    def on(self):
        pass

    def off(self):
        pass


# ---------------------------------------------------------------------------
# Main
# ---------------------------------------------------------------------------
class TFTDisplay:
    def __init__(self, spi, dc, rst, led, orientation=90):
        self.tft = ST7735(spi, dc, rst, led, orientation)
        atexit.register(self.tft.cleanup)

    def display_color_cycle(self):
        colors = [RED, GREEN, BLUE, WHITE]
        for color in colors:
            self.tft.clear(color)
            time.sleep(1)

    def display_printable(self):
        for font_num in range(1, 9):
            self.tft.clear(BLACK)
            pos_x = 0
            pos_y = 0
            for code in range(33, 127):
                try:
                    self.tft.put_char(chr(code), pos_x, pos_y, WHITE, BLACK, font=font_num)
                except Exception:
                    pass
                pos_x += self.tft.fontW[font_num]
                if pos_x + self.tft.fontW[font_num] >= self.tft.width:
                    pos_x = 0
                    pos_y += self.tft.fontH[font_num]
                if pos_y + self.tft.fontH[font_num] >= self.tft.height:
                    break
            time.sleep(1)

    def display_extended(self):
        for font_num in (3, 4):
            self.tft.clear(BLACK)
            pos_x = 0
            pos_y = 0
            for code in range(1, 256):
                try:
                    self.tft.put_char(chr(code), pos_x, pos_y, WHITE, BLACK, font=font_num)
                except Exception:
                    pass
                pos_x += self.tft.fontW[font_num]
                if pos_x + self.tft.fontW[font_num] >= self.tft.width:
                    pos_x = 0
                    pos_y += self.tft.fontH[font_num]
                if pos_y + self.tft.fontH[font_num] >= self.tft.height:
                    break
            time.sleep(1)

    def display_message(self):
        self.tft.clear(BLUE)
        self.tft.put_string("Quick Brown fox jumped over", 0, 0, WHITE, BLUE, 8)
        self.tft.clear(BLUE)
        self.tft.put_string("Fin.", 0, 60, WHITE, BLUE, 8)
        time.sleep(2)


def main():
    spi = None
    dc = None
    rst = None
    led = None

    if spidev is not None:
        try:
            spi = spidev.SpiDev()
            spi.open(0, 0)
            spi.max_speed_hz = 32000000
            spi.mode = 0
        except Exception as e:
            print(f"spidev init failed: {e}")
            spi = None
    else:
        print("spidev not available; using stub SPI.")
        spi = StubSpi()

    if OutputDevice is not None:
        try:
            dc = OutputDevice(8)
            rst = OutputDevice(18)
            led = OutputDevice(23)
        except Exception as e:
            print(f"gpiozero init failed: {e}")
            dc = None
            rst = None
            led = None
    else:
        print("gpiozero not available; using stub GPIO.")
        dc = StubOutputDevice(8)
        rst = StubOutputDevice(18)
        led = StubOutputDevice(23)

    display = None
    try:
        display = TFTDisplay(spi, dc, rst, led, orientation=90)

        display.display_color_cycle()
        display.display_printable()
        display.display_extended()
        display.display_message()

    except KeyboardInterrupt:
        print("\nInterrupted by user.")
    except Exception as e:
        print(f"Error: {e}")
    finally:
        if spi is not None:
            try:
                spi.close()
            except Exception:
                pass
        if dc is not None:
            dc.close()
        if rst is not None:
            rst.close()
        if led is not None:
            led.close()
        print("Resources released.")


def _signal_handler(signum, frame):
    print(f"\nReceived signal {signum}; exiting.")
    sys.exit(0)


if __name__ == "__main__":
    signal.signal(signal.SIGTERM, _signal_handler)
    main()

