import signal
import sys
import time

from gpiozero import Button, LED
from gpiozero.exc import DeviceClosed, BadPinFactory

DOOR_PIN = 19
SIREN_PIN = 26
SAMPLE_COUNT = 8
SAMPLE_INTERVAL = 0.4
BOUNCE_TIME = 0.05

_running = True

def _handle_sigint(signum, frame):
    global _running
    _running = False

def main():
    global _running
    signal.signal(signal.SIGINT, _handle_sigint)

    try:
        door = Button(DOOR_PIN, pull_up=False, bounce_time=BOUNCE_TIME)
        siren = LED(SIREN_PIN)
    except (DeviceClosed, BadPinFactory) as exc:
        print(f"Error: GPIO initialization failed: {exc}", file=sys.stderr)
        sys.exit(1)

    try:
