import http.server
import socketserver
import signal
import sys
from gpiozero import LED
from gpiozero.exc import GPIOZeroError

PORT = 8080
HOST = '0.0.0.0'
LED_PIN = 18

led = None
httpd = None

def cleanup(signum=None, frame=None):
    global led, httpd
    if httpd is not None:
        try:
            httpd.shutdown()
        except Exception:
            pass
        try:
            httpd.server_close()
        except Exception:
            pass
        httpd = None
    if led is not None:
        try:
            led.close()
        except Exception:
            pass
        led = None
    if signum is not None:
        sys.exit(0)

def handle_request(req, handle):
    try:
        if req.path == '/led/on':
            led.on()
            body = 'LED is ON'
        elif req.path == '/led/off':
            led.off()
            body = 'LED is OFF'
        else:
            body = 'Not Found'
        resp = b'HTTP/1.1 200 OK\r\nContent-Type: text/plain\r\n\r\n' + body.encode('utf-8')
        handle.sendall(resp)
    except Exception as e:
        print(f"Error handling request: {e}", file=sys.stderr)
        try:
            handle.sendall(b'HTTP/1.1 500 Internal Server Error\r\n\r\n')
        except Exception:
            pass

