        led = LED(LED_PIN)
    except GPIOZeroError as e:
        print(f"Failed to initialize LED on GPIO{LED_PIN}: {e}", file=sys.stderr)
        sys.exit(1)
    try:
        httpd = ThreadedHTTPServer((HOST, PORT), http.server.SimpleHTTPRequestHandler)
        httpd.allow_reuse_address = True
        httpd.server_bind = lambda *a: None
        httpd.server_loop = lambda *a: ThreadedHTTPServer.server_loop(*a, handle_request)
        print(f"Serving LED control on {HOST}:{PORT} (Ctrl+C to stop)")
        httpd.serve_forever()
    except OSError as e:
        print(f"Socket error on {HOST}:{PORT}: {e}", file=sys.stderr)
    except Exception as e:
        print(f"Unexpected error: {e}", file=sys.stderr)
    finally:
        cleanup()

if __name__ == '__main__':
    main()

