#!/usr/bin/env python3
"""Rainbow HAT 3-bit binary counter.

Touchpad A (GPIO5)  -> MSB (value 4)
Touchpad B (GPIO6)  -> MSB/LSB (value 2)
Touchpad C (GPIO12) -> LSB (value 1)

Displays decimal value (0-7) on HT16K33 (I2C 0x70), lights APA102 strip,
plays buzzer at MIDI note 60 + value.
"""

import signal
import sys
import time

import board
import busio
from adafruit_ht16k33.segments import Seg16x8
from adafruit_dotstar import APA102

try:
    from gpiozero import Button, LED, Buzzer
except Exception as exc:  # pragma: no cover - hardware-dependent
    print(f"gpiozero unavailable: {exc}", file=sys.stderr)
    Button = None
    LED = None
    Buzzer = None

# ---------------------------------------------------------------------------
# Configuration
# ---------------------------------------------------------------------------
TOUCH_PADS = {
    "A": board.D5,
    "B": board.D6,
    "C": board.D12,
}
LED_PINS = {"red": board.D7, "green": board.D7, "blue": board.D8}
BUZZER_PIN = board.D13

I2C_ADDR = 0x70
NUM_BITS = 3
NUM_PIXELS = 7
TONE_BASE = 60

# ---------------------------------------------------------------------------
# Globals (initialised in setup)
# ---------------------------------------------------------------------------
bit_states = [False] * NUM_BITS
leds = {}
buzzer = None
display = None
strip = None
running = True


def setup():
    """Initialise all hardware peripherals.  Returns True on success."""
    global leds, buzzer, display, strip

    # --- Touchpads (gpiozero Button with pull_up=True) ---
    for name, pin in TOUCH_PADS.items():
        try:
            btn = Button(pin, pull_up=True, bounce_time=0.05)
            btn.when_pressed = lambda b=btn, n=name: _on_touch(b, n)
        except Exception as exc:
            print(f"Touchpad {name} on GPIO{pin}: {exc}", file=sys.stderr)
            btn = None

    # --- LEDs (gpiozero LED) ---
    for name, pin in LED_PINS.items():
        try:
            leds[name] = LED(pin)
        except Exception as exc:
            print(f"LED {name} on GPIO{pin}: {exc}", file=sys.stderr)
            leds[name] = None

    # --- Buzzer (gpiozero Buzzer) ---
    try:
        buzzer = Buzzer(BUZZER_PIN)
    except Exception as exc:
        print(f"Buzzer on GPIO{BUZZER_PIN}: {exc}", file=sys.stderr)
        buzzer = None

    # --- HT16K33 display (I2C) ---
    try:
        i2c = busio.I2C(board.SCL, board.SDA)
        display = Seg16x8(i2c, address=I2C_ADDR)
        display.brightness = 0.5
        display.fill(0)
    except Exception as exc:
        print(f"HT16K33 display at 0x{I2C_ADDR:02X}: {exc}", file=sys.stderr)
        display = None

    # --- APA102 LED strip ---
    try:
        strip = APA102(NUM_PIXELS, APA102.CLOCK_PIN, APA102.DAT_PIN)
        strip.begin()
        strip.fill((0, 0, 0))
    except Exception as exc:
        print(f"APA102 strip on GPIO10/GPIO11: {exc}", file=sys.stderr)
        strip = None

    return True


def cleanup():
    """Turn off all hardware resources."""
    global running
    running = False

    # --- LEDs ---
    for name, led in leds.items():
        if led is not None:
            try:
                led.off()
            except Exception:
                pass

    # --- Buzzer ---
    if buzzer is not None:
        try:
            buzzer.off()
        except Exception:
            pass

    # --- APA102 strip ---
    if strip is not None:
        try:
            strip.fill((0, 0, 0))
            strip.show()
        except Exception:
            pass

    # --- HT16K33 display ---
    if display is not None:
        try:
            display.fill(0)
            display.show()
        except Exception:
            pass

    # --- Touchpads (gpiozero Button) ---
    for name, btn in TOUCH_PADS.items():
        if btn is not None:
            try:
                btn.close()
            except Exception:
                pass


def _on_touch(btn, name):
    """Toggle the bit for *name* and update display/strip/buzzer."""
    idx = list(TOUCH_PADS).index(name)
    bit_states[idx] = not bit_states[idx]

    # --- Update LEDs ---
    for name, led in leds.items():
        if led is not None:
            led.value = 1 if bit_states[0] else 0
            led.value = 1 if bit_states[1] else 0
            led.value = 1 if bit_states[2] else 0

    # --- Compute decimal value ---
    value = 0
    for i, bit in enumerate(bit_states):
        value += 2 ** (NUM_BITS - 1 - i) if bit else 0

    # --- Display on HT16K33 ---
    if display is not None:
        try:
            display.fill(0)
            display.print(f"{value:02X}", 0, 0)
            display.show()
        except Exception as exc:
            print(f"Display update error: {exc}", file=sys.stderr)

    # --- APA102 strip ---
    if strip is not None:
        try:
            if value == 0:
                for i in range(NUM_PIXELS):
                    strip[i] = (255, 255, 255)
            elif value == 7:
                for i in range(NUM_PIXELS):
                    strip[i] = (255, 255, 255)
            else:
                red = 255 if bit_states[0] else 0
                green = 255 if bit_states[1] else 0
                blue = 255 if bit_states[2] else 0
                for i in range(NUM_PIXELS):
                    if i == value:
                        strip[i] = (red, green, blue)
                    else:
                        strip[i] = (0, 0, 0)
            strip.show()
        except Exception as exc:
            print(f"APA102 update error: {exc}", file=sys.stderr)

    # --- Buzzer ---
    if buzzer is not None:
        try:
            buzzer.play(TONE_BASE + value)
        except Exception as exc:
            print(f"Buzzer error: {exc}", file=sys.stderr)


def _signal_handler(signum, frame):
    """Handle SIGINT / SIGTERM for clean shutdown."""
    global running
    running = False


def main():
    global running

    if not setup():
        print("Hardware initialisation failed. Exiting.", file=sys.stderr)
        sys.exit(1)

    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    print("Rainbow HAT binary counter ready. Press touchpads to toggle bits.")

    try:
        while running:
            signal.pause()
    except Exception as exc:
        print(f"Unexpected error in main loop: {exc}", file=sys.stderr)
    finally:
        cleanup()
        print("Program terminated.")


if __name__ == "__main__":
    main()

