import smbus2
import time
import threading
import math
import signal
import sys

# QMC5883L magnetometer constants
QMC5883L_ADDRESS = 0x0D
QMC5883L_STATUS_REG = 0x06
QMC5883L_DATA_X_MSB = 0x00
QMC5883L_CONTROL_REG = 0x09
QMC5883L_DATA_RATE_REG = 0x0A
QMC5883L_MODE_REG = 0x0B

# Control register values
QMC5883L_CONTINUOUS_MODE = 0x01
QMC5883L_RANGE_2_GAUSS = 0x40
QMC5883L_DATA_RATE_10_HZ = 0x10

# Hard-iron offsets
X_OFFSET = 20
Y_OFFSET = -15

shutdown_event = threading.Event()
bus = None
thread = None

def signal_handler(sig, frame):
    print("\nShutting down...")
    shutdown_event.set()

def read_register(bus, register):
    try:
        return bus.read_byte_data(QMC5883L_ADDRESS, register)
    except Exception as e:
        print(f"Error reading register 0x{register:02X}: {e}")
        return None

def write_register(bus, register, value):
    try:
        bus.write_byte_data(QMC5883L_ADDRESS, register, value)
        return True
    except Exception as e:
        print(f"Error writing to register 0x{register:02X}: {e}")
        return False

def initialize_magnetometer(bus):
    for attempt in range(3):
        if read_register(bus, QMC5883L_STATUS_REG) is not None:
            print("Magnetometer detected.")
            return True
        else:
            print(f"Attempt {attempt + 1}/3: Magnetometer not detected. Retrying in 1 second...")
            shutdown_event.wait(1)
    return False

def read_magnetometer_data(bus):
    data = []
    for i in range(6):
        msb = read_register(bus, QMC5883L_DATA_X_MSB + i * 2)
        lsb = read_register(bus, QMC5883L_DATA_X_MSB + i * 2 + 1)
        if msb is not None and lsb is not None:
            data.append((msb << 8) | lsb)
        else:
            data.append(None)
    return data

def calculate_heading(x, y):
    x_offset = X_OFFSET if x is not None else 0
    y_offset = Y_OFFSET if y is not None else 0
    x = x - x_offset
    y = y - y_offset
    if x == 0 and y == 0:
        return 0.0
    heading_rad = math.atan2(y, x)
    return math.degrees(heading_rad)

def main():
    global bus, thread
    signal.signal(signal.SIGINT, signal_handler)

    try:
        bus = smbus2.SMBus(1)
    except Exception as e:
        print(f"Failed to open I2C bus: {e}")
        sys.exit(1)

    if not initialize_magnetometer(bus):
        print("Failed to initialize magnetometer after 3 attempts.")
        bus.close()
        sys.exit(1)

    if not write_register(bus, QMC5883L_CONTROL_REG, QMC5883L_RANGE_2_GAUSS):
        print("Failed to set range.")
        bus.close()
        sys.exit(1)
    if not write_register(bus, QMC5883L_DATA_RATE_REG, QMC5883L_DATA_RATE_10_HZ):
        print("Failed to set data rate.")
        bus.close()
        sys.exit(1)
    if not write_register(bus, QMC5883L_MODE_REG, QMC5883L_CONTINUOUS_MODE):
        print("Failed to set continuous mode.")
        bus.close()
        sys.exit(1)

    print("Magnetometer initialized. Reading data...")

    def data_acquisition_loop():
        while not shutdown_event.is_set():
            data = read_magnetometer_data(bus)
            if data:
                x, y, z = data
                heading = calculate_heading(x, y)
                print(f"Heading: {heading:.1f} degrees")
            else:
                print("Failed to read magnetometer data.")
            shutdown_event.wait(0.1)

    thread = threading.Thread(target=data_acquisition_loop, daemon=True)
    thread.start()

    try:
        while not shutdown_event.is_set():
            shutdown_event.wait(1)
    except Exception as e:
        print(f"Unexpected error: {e}")
    finally:
        shutdown_event.set()
        if thread is not None and thread.is_alive():
            thread.join(timeout=2)
        if bus is not None:
            bus.close()
        print("Program finished.")

if __name__ == "__main__":
    main()

