#!/usr/bin/env python3
"""
Predictive maintenance for urban monitoring using a digital vibration sensor.
Reads an active-low digital output on GPIO17 (BCM), simulates amplitude, and
recommends maintenance when the average exceeds a threshold.
"""

import time
import random
import sys
from gpiozero import DigitalInputDevice
from gpiozero.exc import BadPinFactory, DeviceClosed

def read_vibration_sensor(sensor):
    """Read the digital vibration sensor state (True = HIGH, False = LOW)."""
    return sensor.is_active  # True when pin is HIGH (idle), False when LOW (vibration)

def simulate_amplitude():
    """Simulate a vibration amplitude value based on sensor state."""
    if read_vibration_sensor(sensor):
        return random.uniform(6.0, 9.0)
    else:
        return random.uniform(3.0, 5.0)

def main():
    """Main routine: sample sensor, compute average, recommend maintenance."""
    sensor = None
    try:
        # Initialize digital input device on GPIO17 with internal pull-up
        sensor = DigitalInputDevice(17, pull_up=True)
        print("Vibration sensor initialized on GPIO17 (BCM).")

        # Sample the sensor 6 times
        readings = []
        for i in range(6):
            amplitude = simulate_amplitude()
            readings.append(amplitude)
            print(f"Sample {i+1}: amplitude = {amplitude:.2f}")
            time.sleep(0.3)

        # Compute the average amplitude
        average_amplitude = sum(readings) / len(readings)
        print(f"\nAverage amplitude: {average_amplitude:.2f}")

        # Recommend maintenance if average exceeds threshold
        if average_amplitude > 7.5:
            print("Maintenance recommended: wear trend is high")
        else:
            print("Component healthy: no action needed")

    except BadPinFactory as e:
        print(f"GPIO initialization error: {e}", file=sys.stderr)
        sys.exit(1)
    except DeviceClosed as e:
        print(f"Device closed unexpectedly: {e}", file=sys.stderr)
        sys.exit(1)
    except Exception as e:
        print(f"Unexpected error: {e}", file=sys.stderr)
        sys.exit(1)
    finally:
        # Clean up GPIO resources
        if sensor is not None:
            try:
                sensor.close()
                print("GPIO resources released.")
            except Exception as e:
                print(f"Error during cleanup: {e}", file=sys.stderr)

if __name__ == "__main__":
    main()

