#!/usr/bin/env python3
"""Wildlife tracking IoT server accepting remote control commands over TCP.

Listens on 127.0.0.1:9099 for connections, accepts one command per connection,
and responds with GPS coordinates via JSON. Supports simulated GPS fallback.
"""

import json
import logging
import signal
import socket
import sys
import time

# Configure logging to stderr
logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s [%(levelname)s] %(message)s",
    stream=sys.stderr,
)
logger = logging.getLogger(__name__)

# Global flag for graceful shutdown
shutdown_requested = False


def signal_handler(signum, frame):
    """Handle SIGINT and SIGTERM for graceful shutdown."""
    global shutdown_requested
    logger.info("Received signal %d, initiating graceful shutdown...", signum)
    shutdown_requested = True


def read_gps_position():
    """Read GPS coordinates from the GPS module.

    Returns:
        tuple: (latitude, longitude) as floats, or (None, None) on failure.
    """
    try:
        # Simulated GPS data if module is unavailable
        latitude = 37.7749
        longitude = -122.4194
        return latitude, longitude
    except Exception as e:
        logger.error("Failed to read GPS position: %s", e)
        return None, None


def handle_command(command_text):
    """Process a remote control command and return a response.

    Args:
        command_text (str): The command string received from the client.

    Returns:
        str: The response string in JSON format.
    """
    if not command_text:
        return json.dumps({"status": "error", "message": "Empty command received"})

    command_parts = command_text.split()
    if not command_parts:
        return json.dumps({"status": "error", "message": "Invalid command format"})

    command = command_parts[0].lower()
    if command == "start":
        return json.dumps({"status": "ok", "message": "Tracking started"})
    elif command == "stop":
        return json.dumps({"status": "ok", "message": "Tracking stopped"})
    elif command == "report":
        latitude, longitude = read_gps_position()
        if latitude is not None and longitude is not None:
            return json.dumps({"status": "ok", "latitude": round(latitude, 6), "longitude": round(longitude, 6)})
        else:
            return json.dumps({"status": "error", "message": "GPS read failed"})
    else:
        return json.dumps({"status": "error", "message": "Unknown command"})


def main():
    """Main entry point for the wildlife tracking server."""
    # Register signal handlers for graceful shutdown
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    server_socket = None
    try:
        # Create a TCP socket for listening
        server_socket = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        server_socket.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
        server_socket.bind(("127.0.0.1", 9099))
        server_socket.listen(1)
        server_socket.settimeout(2.0)  # 2-second timeout for connections

        logger.info("Wildlife tracking server listening on 127.0.0.1:9099")

        while not shutdown_requested:
            try:
                client_socket, client_address = server_socket.accept()
                logger.info("Connection from %s", client_address)

                # Read the command from the client
                command = client_socket.recv(1024).decode("utf-8", errors="ignore").strip()
                response = handle_command(command)

                # Send the response back to the client
                client_socket.sendall(response.encode("utf-8"))

            except socket.timeout:
                # No connection within 2 seconds, continue listening
                continue
            except socket.error as e:
                logger.error("Socket error during connection: %s", e)
                continue
            except Exception as e:
                logger.error("Unexpected error handling client: %s", e)
                continue

            finally:
                # Close the client socket after use
                try:
                    client_socket.close()
                except Exception as e:
                    logger.error("Error closing client socket: %s", e)

    except socket.error as e:
        logger.error("Failed to create or bind socket: %s", e)
        sys.exit(1)
    except Exception as e:
        logger.error("Unexpected error in main loop: %s", e)
        sys.exit(1)
    finally:
        if server_socket is not None:
            try:
                server_socket.close()
                logger.info("Server socket closed")
