import random
import time
import signal
import sys

try:
    from gpiozero import OutputDevice
    from gpiozero.exc import GPIOZeroError, GPIODeviceError
except ImportError:
    print("Error: gpiozero is not installed. Install with: sudo apt install python3-gpiozero")
    sys.exit(1)

# Configuration
PUMP_PIN = 17
MOISTURE_THRESHOLD = 30
ITERATIONS = 5
DELAY_SECONDS = 2

# Global pump handle for cleanup
pump = None


def cleanup():
    """Turn off the pump and release GPIO resources."""
    global pump
    if pump is not None:
        try:
            pump.off()
            pump.close()
        except Exception:
            pass
        pump = None


def signal_handler(signum, frame):
    """Handle SIGTERM/SIGINT for graceful shutdown."""
    print(f"\nReceived signal {signum}, shutting down...")
    cleanup()
    sys.exit(0)


def read_moisture():
    """Simulate a soil-moisture sensor reading (0-100 inclusive)."""
    return random.randint(0, 100)


def main():
    global pump

    # Register signal handlers for graceful termination
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    # Initialize the pump GPIO pin as a digital output
    try:
        pump = OutputDevice(PUMP_PIN, active_high=True, initial_value=False)
    except (GPIOZeroError, GPIODeviceError) as e:
        print(f"Error: Failed to initialize GPIO {PUMP_PIN}: {e}")
        sys.exit(1)
    except Exception as e:
        print(f"Error: Unexpected GPIO initialization failure: {e}")
        sys.exit(1)

    try:
        for i in range(1, ITERATIONS + 1):
            moisture = read_moisture()
            print(f"Reading {i}/{ITERATIONS}: Soil Moisture = {moisture}%")

            if moisture < MOISTURE_THRESHOLD:
                pump.on()
                print(f"  -> Pump ON: Soil too dry")
            else:
                pump.off()
                print(f"  -> Pump OFF: Soil moisture sufficient")

            if i < ITERATIONS:
                time.sleep(DELAY_SECONDS)

    except KeyboardInterrupt:
        print("\nProgram interrupted by user.")
    except Exception as e:
        print(f"Error: {e}")
    finally:
        cleanup()
        print("GPIO cleanup completed.")


if __name__ == "__main__":
    main()

