import time
import math
import logging
import signal
import sys
import smbus2
import numpy as np

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

MPU6050_ADDR = 0x68
PWR_MGMT_1 = 0x6B
ACCEL_XOUT_H = 0x3B

running = True

def signal_handler(sig, frame):
    global running
    logging.info("Signal received, shutting down...")
    running = False

class TinyMLQualityControl:
    def __init__(self, magnitude_limit=2.5, variance_limit=0.4):
        self.magnitude_limit = magnitude_limit
        self.variance_limit = variance_limit
        self.model = None

    def load_model(self):
        try:
            with open("tinyml_model.h5", "rb") as f:
                self.model = np.load(f)
            logging.info("TinyML model loaded successfully.")
        except FileNotFoundError:
            logging.error("TinyML model file not found.")
            self.model = None
        except Exception as e:
            logging.error(f"Error loading TinyML model: {e}")
            self.model = None

    def read_accelerometer(self, bus):
        try:
            data = bus.read_i2c_block_data(MPU6050_ADDR, ACCEL_XOUT_H, 6)
            x = (data[0] << 8) | data[1]
            y = (data[2] << 8) | data[3]
            z = (data[4] << 8) | data[5]
            x = x - 65536 if x > 32767 else x
            y = y - 65536 if y > 32767 else y
            z = z - 65536 if z > 32767 else z
            return x, y, z
        except Exception as e:
            logging.error(f"Error reading accelerometer data: {e}")
            return None, None, None

    def extract_features(self, x, y, z):
        try:
            samples = np.array([x, y, z])
            magnitude = np.sqrt(np.sum(samples**2))
            variance = np.var(samples)
            return magnitude, variance
        except Exception as e:
            logging.error(f"Error extracting features: {e}")
            return None, None

    def predict(self, magnitude, variance):
        if self.model is None:
            return None
        try:
            prediction = self.model.predict(np.array([magnitude, variance]))
            return float(prediction[0])
        except Exception as e:
            logging.error(f"Error during prediction: {e}")
            return None

    def check_part(self, magnitude, variance):
        if magnitude is None or variance is None:
            return "ERROR"
        if magnitude > self.magnitude_limit or variance > self.variance_limit:
            return "DEFECTIVE"
        return "PASS"

def main():
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    bus = None
    try:
        bus = smbus2.SMBus(1)
        bus.write_byte_data(MPU6050_ADDR, PWR_MGMT_1, 0)
        logging.info("MPU6050 initialized successfully.")
    except Exception as e:
        logging.error(f"Failed to initialize I2C bus or MPU6050: {e}")
        return

    quality_control = TinyMLQualityControl()
    quality_control.load_model()

    try:
        for i in range(8):
            if not running:
                break
            x, y, z = quality_control.read_accelerometer(bus)
            if x is None:
                logging.warning(f"Skipping sample {i+1} due to read error.")
                continue
            magnitude, variance = quality_control.extract_features(x, y, z)
            if magnitude is None:
                logging.warning(f"Skipping sample {i+1} due to feature extraction error.")
                continue
            prediction = quality_control.predict(magnitude, variance)
            verdict = quality_control.check_part(magnitude, variance)
            logging.info(f"Sample {i+1}: Magnitude={magnitude:.2f}, Variance={variance:.2f}, Prediction={prediction}, Verdict={verdict}")
    except Exception as e:
        logging.error(f"Unexpected error during quality control loop: {e}")
    finally:
        if bus is not None:
            try:
                bus.close()
                logging.info("I2C bus closed.")
            except Exception as e:
                logging.error(f"Error closing I2C bus: {e}")

if __name__ == "__main__":
    main()

