#!/usr/bin/env python3
"""
Parking Sensor Simulation for Raspberry Pi 5

Simulates a parking sensor using a passive buzzer (KY-006) on GPIO 17.
Randomly selects distance and plays a tone corresponding to the distance.
Uses gpiozero for hardware control and time for delays.
"""

import time
import random
import sys

try:
    from gpiozero import TonalBuzzer
    from gpiozero.exc import GPIOZeroError, GPIODeviceError
except ImportError:
    print("Error: gpiozero library not found. Install with: sudo apt install python3-gpiozero")
    sys.exit(1)

# Constants
BUZZER_PIN = 17
TONE_FREQUENCY = 440  # Hz
DISTANCES = ["Far", "Medium", "Close"]

# Global buzzer object
buzzer = None


def initialize_buzzer(pin):
    """Initialize the buzzer on the given GPIO pin."""
    global buzzer
    try:
        buzzer = TonalBuzzer(pin)
        print(f"Buzzer initialized on GPIO {pin}")
    except (GPIOZeroError, GPIODeviceError) as e:
        print(f"Error initializing buzzer: {e}")
        sys.exit(1)
    except Exception as e:
        print(f"Unexpected error initializing buzzer: {e}")
        sys.exit(1)


def play_tone(buzzer_obj, frequency, duration):
    """Play a tone on the buzzer for the given duration (seconds)."""
    try:
        buzzer_obj.play(frequency)
        time.sleep(duration)
        buzzer_obj.stop()
        time.sleep(0.01)  # Delay after stop to ensure full silence
    except Exception as e:
        print(f"Error playing tone: {e}")
        raise


def get_distance():
    """Randomly select a distance from the list."""
    return random.choice(DISTANCES)


def main():
    """Main loop: simulate parking sensor readings and play tones."""
    global buzzer
    try:
        initialize_buzzer(BUZZER_PIN)

        while True:
            distance = get_distance()
            print(f"Distance: {distance}")

            if distance == "Far":
                play_tone(buzzer, TONE_FREQUENCY, 0.1)
                time.sleep(2)
            elif distance == "Medium":
                play_tone(buzzer, TONE_FREQUENCY, 0.1)
                time.sleep(0.1)
                play_tone(buzzer, TONE_FREQUENCY, 0.1)
                time.sleep(1)
            elif distance == "Close":
                play_tone(buzzer, TONE_FREQUENCY, 0.4)
                time.sleep(0.1)

    except KeyboardInterrupt:
        print("\nProgram stopped by user.")
    except Exception as e:
        print(f"An unexpected error occurred: {e}")
    finally:
        if buzzer is not None:
            try:
                buzzer.stop()
                print("Buzzer stopped.")
            except Exception as e:
                print(f"Error stopping buzzer: {e}")
        print("Exiting program.")


if __name__ == "__main__":
    main()

