#!/usr/bin/env python3
"""
Soil Moisture Monitor with Water Pump Control for Raspberry Pi Zero W

Reads soil moisture from an Adafruit Seesaw sensor (I2C address 0x36) and
controls a 12V water pump via a relay on GPIO17 (BCM).
"""

import signal
import sys
import time
import board
import busio
import adafruit_seesaw.seesaw
from gpiozero import OutputDevice

# Constants
PUMP_PIN = 17
MOISTURE_THRESHOLD = 500
READ_INTERVAL = 10  # seconds
SENSOR_ADDRESS = 0x36

# Global resources for cleanup
pump = None
i2c = None
sensor = None
running = True


def cleanup():
    """Release all resources and ensure pump is off."""
    global pump, i2c, sensor
    if pump is not None:
        try:
            pump.off()
            pump.close()
        except Exception:
            pass
    if i2c is not None:
        try:
            i2c.deinit()
        except Exception:
            pass
    if sensor is not None:
        try:
            sensor = None
        except Exception:
            pass


def signal_handler(signum, frame):
    """Handle SIGINT/SIGTERM for graceful shutdown."""
    global running
    running = False


def init_hardware():
    """Initialize I2C bus, sensor, and pump GPIO."""
    global i2c, sensor, pump
    try:
        i2c = busio.I2C(board.SCL, board.SDA)
    except Exception as e:
        print(f"Fatal: I2C bus initialization failed: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        sensor = adafruit_seesaw.seesaw.Seesaw(i2c, addr=SENSOR_ADDRESS)
    except Exception as e:
        print(f"Fatal: Could not communicate with Seesaw sensor at 0x{SENSOR_ADDRESS:02X}: {e}", file=sys.stderr)
        cleanup()
        sys.exit(1)

    try:
        pump = OutputDevice(PUMP_PIN, active_high=True, initial_value=False)
    except Exception as e:
        print(f"Fatal: Could not initialize GPIO{PUMP_PIN}: {e}", file=sys.stderr)
        cleanup()
        sys.exit(1)


def read_moisture():
    """Read soil moisture from the Seesaw sensor. Returns int or None on error."""
    try:
        return sensor.moisture_read()
    except Exception as e:
        print(f"Warning: Sensor read error: {e}", file=sys.stderr)
        return None


def control_pump(moisture_level):
    """Control the pump based on moisture level. Returns 'on' or 'off'."""
    if moisture_level is None:
        return "off"
    if moisture_level < MOISTURE_THRESHOLD:
        pump.on()
        return "on"
    pump.off()
    return "off"


def main():
    """Main loop: read sensor and control pump every 10 seconds."""
    global running
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    init_hardware()

    print("Soil Moisture Monitor started. Press Ctrl+C to exit.")
    print(f"Threshold: {MOISTURE_THRESHOLD}, Pin: {PUMP_PIN}, Interval: {READ_INTERVAL}s")

    try:
        while running:
            moisture = read_moisture()
            pump_status = control_pump(moisture)
            print(f"Moisture: {moisture}, Pump: {pump_status}")
            time.sleep(READ_INTERVAL)
    except Exception as e:
        print(f"Unexpected error in main loop: {e}", file=sys.stderr)
    finally:
        cleanup()
        print("Resources released. Exiting.")


if __name__ == "__main__":
    main()

