import signal
import sys
import time
import logging
from typing import Optional, Union

import serial
from minimalmodbus import ModbusSerialInstrument

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)


class ServoMotor:
    """
    Controls a servo motor via Modbus RTU over a Raspberry Pi serial bus.
    """

    SERVO_SERIAL_PORT = "/dev/serial0"
    SERVO_BAUD_RATE = 115200
    SERVO_SLAVE_ADDRESS = 1
    SERVO_REGISTERS = {
        "operation_mode": 0x3500,
        "position_command": 0x4000,
        "velocity_command": 0x6F00,
        "position_feedback": 0x3700,
        "velocity_feedback": 0x3B00,
        "status": 0x3000,
        "start_command": 0x3100,
        "stop_command": 0x0006,
    }

    def __init__(self, serial_port: str = SERVO_SERIAL_PORT, baud_rate: int = SERVO_BAUD_RATE,
                 slave_address: int = SERVO_SLAVE_ADDRESS):
        self.serial_port = serial_port
        self.baud_rate = baud_rate
        self.slave_address = slave_address
        self.instrument: Optional[ModbusSerialInstrument] = None
        self._running = True

    def _connect(self) -> bool:
        try:
            self.instrument = ModbusSerialInstrument(
                port=self.serial_port,
                baudrate=self.baud_rate,
                bytesize=8,
                parity='N',
                stopbits=1,
                timeout=1.0
            )
            if not self.instrument.connect():
                logger.error("Failed to open serial port %s", self.serial_port)
                self.instrument = None
                return False
            logger.info("Connected to servo on %s at %d baud (slave %d)", self.serial_port, self.baud_rate, self.slave_address)
            return True
        except serial.SerialException as e:
            logger.error("Serial error connecting to %s: %s", self.serial_port, e)
            self.instrument = None
            return False
        except Exception as e:
            logger.error("Unexpected error connecting to %s: %s", self.serial_port, e)
            self.instrument = None
            return False

    def _close(self) -> None:
        if self.instrument is not None:
            try:
                self.instrument.close()
                logger.info("Serial port %s closed", self.serial_port)
            except Exception as e:
                logger.error("Error closing serial port %s: %s", self.serial_port, e)
            finally:
                self.instrument = None

    def _signal_handler(self, signum, frame):
        logger.info("Signal %d received, shutting down...", signum)
        self._running = False

    def _read_register(self, register_address: int, count: int = 2) -> Optional[Union[int, list]]:
        if self.instrument is None:
            logger.error("Serial port not initialized; cannot read register 0x%04X", register_address)
            return None
        try:
            return self.instrument.read_register(register_address, count, signed=True)
        except Exception as e:
            logger.error("Error reading register 0x%04X: %s", register_address, e)
            return None

    def _write_register(self, register_address: int, value: Union[int, list]) -> bool:
        if self.instrument is None:
            logger.error("Serial port not initialized; cannot write to register 0x%04X", register_address)
            return False
        try:
            if isinstance(value, int):
                self.instrument.write_register(register_address, value, signed=True)
            else:
                self.instrument.write_register(register_address, value, signed=True)
            return True
        except Exception as e:
            logger.error("Error writing to register 0x%04X: %s", register_address, e)
            return False

    def set_operation_mode(self, mode: int) -> bool:
        if not isinstance(mode, int):
            logger.error("Mode must be an integer, got %s", type(mode).__name__)
            return False
        if not self._write_register(self.SERVO_REGISTERS["operation_mode"], mode):
            return False
        return True

    def write_position_command(self, value: int) -> bool:
        if not isinstance(value, int):
            logger.error("Position value must be an integer, got %s", type(value).__name__)
            return False
        if not self._write_register(self.SERVO_REGISTERS["position_command"], value):
            return False
        return True

    def write_velocity_command(self, value: int) -> bool:
        if not isinstance(value, int):
            logger.error("Velocity value must be an integer, got %s", type(value).__name__)
            return False
        if not self._write_register(self.SERVO_REGISTERS["velocity_command"], value):
            return False
        return True

    def read_position_feedback(self) -> Optional[int]:
        result = self._read_register(self.SERVO_REGISTERS["position_feedback"])
        if result is None:
            return None
        if len(result) != 2:
            logger.error("Unexpected feedback length: %s", result)
            return None
        return result[0]

    def read_velocity_feedback(self) -> Optional[int]:
        result = self._read_register(self.SERVO_REGISTERS["velocity_feedback"])
        if result is None:
            return None
        if len(result) != 2:
            logger.error("Unexpected feedback length: %s", result)
            return None
        return result[0]

    def start(self) -> bool:
        if not self._write_register(self.SERVO_REGISTERS["start_command"], 0x000F):
            return False
        return True

    def stop(self) -> bool:
        if not self._write_register(self.SERVO_REGISTERS["stop_command"], 0x0006):
            return False
        return True

    def read_status(self) -> Optional[int]:
        result = self._read_register(self.SERVO_REGISTERS["status"])
        if result is None:
            return None
        return result

    def run(self) -> None:
        if not self._connect():
            logger.error("Failed to initialize servo motor. Exiting.")
            return
        signal.signal(signal.SIGINT, self._signal_handler)
        signal.signal(signal.SIGTERM, self._signal_handler)
        try:
            if not self.start():
                logger.error("Failed to start servo motor.")
            time.sleep(0.5)
            if not self.write_position_command(0):
                logger.error("Failed to set position command.")
            time.sleep(0.5)
            if not self.stop():
                logger.error("Failed to stop servo motor.")
            time.sleep(0.5)
            position = self.read_position_feedback()
            velocity = self.read_velocity_feedback()
            status = self.read_status()
            logger.info("Position: %s, Velocity: %s, Status: %s", position, velocity, status)
        except Exception as e:
            logger.error("Error during servo operation: %s", e)
        finally:
            self._close()


if __name__ == '__main__':
    servo = ServoMotor()
    try:
        servo.run()
    except Exception as e:
        logger.error("Fatal error: %s", e)
        sys.exit(0)
    sys.exit(0)

