import time
import signal
import sys
from gpiozero import OutputDevice, Servo


class Laser:
    """Controls a laser module via gpiozero OutputDevice."""

    def __init__(self, pin=17):
        self.pin = pin
        self.device = None
        try:
            self.device = OutputDevice(pin)
        except Exception as e:
            raise RuntimeError(f"Failed to initialize laser on GPIO{pin}: {e}")

    def on(self):
        if self.device is None:
            raise RuntimeError("Laser device not initialized")
        self.device.on()

    def off(self):
        if self.device is not None:
            self.device.off()

    def close(self):
        if self.device is not None:
            self.device.close()
            self.device = None


class Aim:
    """Controls two servos for aiming and a laser for on-time targeting."""

    def __init__(self, ld=0.5, sd=0.5):
        self.ld = ld
        self.sd = sd
        self.hp = [0.0] * 10
        self.vp = [0.0] * 10
        self.laser = Laser()
        self.servo_h = None
        self.servo_v = None
        try:
            self.servo_h = Servo(18)
            self.servo_v = Servo(19)
        except Exception as e:
            raise RuntimeError(f"Failed to initialize servos: {e}")
        self.laser.on()

    def aim(self, b):
        """Aim at the target position b (1-based index)."""
        if not 1 <= b <= len(self.hp):
            raise ValueError(f"Target index {b} out of range (1-{len(self.hp)})")
        self.laser.on()
        time.sleep(self.ld)
        self.laser.off()
        for i in range(1, b):
            self.servo_h.value = self.hp[i - 1]
            self.servo_v.value = self.vp[i - 1]
            time.sleep(self.sd / 2)
        self.servo_h.value = self.hp[b - 1]
        self.servo_v.value = self.vp[b - 1]
        time.sleep(self.sd / 2)
        self.servo_h.value = self.hp[10]
        self.servo_v.value = self.vp[10]

    def close(self):
        if self.servo_h is not None:
            self.servo_h.close()
            self.servo_h = None
        if self.servo_v is not None:
            self.servo_v.close()
            self.servo_v = None
        if self.laser is not None:
            self.laser.close()
            self.laser = None


def main():
    aim = None
    try:
        aim = Aim(ld=0.5, sd=0.5)
        nums = [1, 5, 3]
        for i in nums:
            aim.aim(i)
    except KeyboardInterrupt:
        print("\nInterrupted by user")
    except Exception as e:
        print(f"Error: {e}", file=sys.stderr)
    finally:
        if aim is not None:
            aim.close()


if __name__ == "__main__":
    main()

