import time
import signal
import sys
import board
import busio
from adafruit_servokit import ServoKit

# Constants for servo channels
BASE = 0
DROP = 1
SEEK = 2
GRAB = 4

# Constants for object positions
METAL = 135
PLASTIC = 180
PAPER = 90

# Default angles for servos
DEFAULT_ANGLE = 90

# Global flag for graceful shutdown
_running = True


def _signal_handler(signum, frame):
    """Handle SIGINT/SIGTERM for clean shutdown."""
    global _running
    _running = False


def initialize_servokit():
    """Initializes the ServoKit with robust error handling."""
    try:
        i2c = busio.I2C(board.SCL, board.SDA)
        kit = ServoKit(channels=16, i2c=i2c, address=0x40)
        return kit
    except Exception as e:
        print(f"Error initializing ServoKit: {e}", file=sys.stderr)
        return None


def move_servo(kit, channel, target_angle, step_size=5, delay=0.04):
    """Moves a servo smoothly to a target angle."""
    if not 0 <= channel <= 15:
        raise ValueError(f"Invalid servo channel: {channel}")
    if not 0 <= target_angle <= 180:
        raise ValueError(f"Invalid target angle: {target_angle}")

    current_angle = kit.servo[channel].angle
    if current_angle is None:
        current_angle = DEFAULT_ANGLE

    step = step_size if target_angle > current_angle else -step_size
    angle = current_angle
    while abs(angle - target_angle) > 1 and _running:
        angle += step
        if _running:
            kit.servo[channel].angle = angle
        time.sleep(delay)

    if _running:
        kit.servo[channel].angle = target_angle


def seek(kit, angle):
    """Moves the seek servo to the specified angle."""
    move_servo(kit, SEEK, angle)


def deseek(kit, angle):
    """Moves the seek servo away from the specified angle."""
    move_servo(kit, SEEK, angle)


def drop(kit, angle):
    """Moves the drop servo to the specified angle."""
    move_servo(kit, DROP, angle)


def pick(kit, angle):
    """Moves the pick servo to the specified angle."""
    move_servo(kit, GRAB, angle)


def grab(kit, angle):
    """Closes the gripper."""
    move_servo(kit, GRAB, angle)


def release(kit, angle):
    """Opens the gripper."""
    move_servo(kit, GRAB, angle)


def collect_object_steps(kit, seek_angle):
    """Collects an object: seeks, lowers, raises, and returns to default."""
    seek(kit, seek_angle)
    grab(kit, 90)
    move_servo(kit, SEEK, 160)
    pick(kit, 100)
    move_servo(kit, SEEK, 90)


def drop_object_steps(kit, drop_angle):
    """Drops an object: moves drop servo, releases gripper, returns drop servo to default."""
    drop(kit, drop_angle)
    release(kit, 120)
    move_servo(kit, DROP, 100)


def get_pos_x(x_center):
    """Maps a 0-320 pixel range to a 0-180 degree range."""
    return min(max(x_center / 320 * 180, 0), 180)


def get_pos_y(y_center):
    """Maps a 0-320 pixel range to a 0-180 degree range."""
    return min(max(y_center / 320 * 180, 0), 180)


def collect_object(x_center, y_center, kit, drop_angle):
    """Collects an object at the specified coordinates."""
    seek_angle = get_pos_x(x_center)
    pos_x = get_pos_x(x_center)
    pos_y = get_pos_y(y_center)

    move_servo(kit, BASE, pos_x)
    collect_object_steps(kit, seek_angle)
    drop_object_steps(kit, drop_angle)
    move_servo(kit, BASE, 90)


def cleanup(kit):
    """Stops all servos and releases the I2C bus."""
    if kit is not None:
        for ch in range(16):
            try:
                kit.servo[ch].angle = None
            except Exception:
                pass
    if hasattr(kit, 'i2c'):
        try:
            kit.i2c.deinit()
        except Exception:
            pass


if __name__ == "__main__":
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    kit = initialize_servokit()
    if kit is None:
        sys.exit(1)

    try:
        collect_object(160, 240, kit, 135)
    except KeyboardInterrupt:
        pass
    finally:
        cleanup(kit)

