import RPi.GPIO as GPIO
import time
import datetime
import sys

RELAY_PIN = 17

def setup_gpio():
    GPIO.setmode(GPIO.BCM)
    GPIO.setup(RELAY_PIN, GPIO.OUT, initial=GPIO.LOW)

def cleanup_gpio():
    GPIO.cleanup()

def main():
    try:
        setup_gpio()
        print("Relay control started. Press Ctrl+C to exit.")
        while True:
            now = datetime.datetime.now().time()
            if now >= datetime.time(19, 0):
                print(f"{datetime.datetime.now().strftime('%H:%M:%S')} - Closing door (sunset)")
                GPIO.output(RELAY_PIN, GPIO.HIGH)
                time.sleep(1)
            elif now < datetime.time(7, 0):
                print(f"{datetime.datetime.now().strftime('%H:%M:%S')} - Opening door (sunrise)")
                GPIO.output(RELAY_PIN, GPIO.LOW)
                time.sleep(1)
