# Configure logging
logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s - %(levelname)s - %(message)s"
)

# Define GPIO pins for actuators (BCM numbering)
PUMP_PIN = 20
LIGHT_PIN = 21

# Global list to hold OutputDevice objects for cleanup
actuators = []

def setup_actuators():
    """Initialize OutputDevice objects for pump and light."""
    global actuators
    try:
        pump = OutputDevice(PUMP_PIN)
        light = OutputDevice(LIGHT_PIN)
        actuators = [pump, light]
        logging.info("Actuators initialized on pins %d and %d", PUMP_PIN, LIGHT_PIN)
    except GPIOZeroError as e:
        logging.error("Failed to initialize actuators: %s", e)
        raise

def cleanup_actuators(signum=None, frame=None):
    """Turn off all actuators and close devices."""
    logging.info("Cleaning up actuators...")
    for dev in actuators:
        try:
            dev.off()
            dev.close()
        except Exception as e:
            logging.error("Error closing actuator: %s", e)
    actuators.clear()
    if signum is not None:
        sys.exit(0)

def parse_intent(phrase):
    """Parse a phrase and return the recognized intent."""
    # Simple keyword matching for hydroponics control phrases
    intent_map = {
        "turn the pump on": "pump_on",
        "switch the light": "light_toggle",
        "turn pump off": "pump_off",
    }
    phrase_lower = phrase.lower()
    for keyword, intent in intent_map.items():
        if keyword in phrase_lower:
            logging.info("Parsed phrase: %s, Intent: %s", phrase, intent)
            return intent
    logging.warning("No intent recognized for phrase: %s", phrase)
    return None

def control_actuator(intent, device):
    """Apply an intent to the corresponding actuator."""
    if intent == "pump_on":
        device.on()
        logging.info("Pump turned ON")
    elif intent == "pump_off":
        device.off()
        logging.info("Pump turned OFF")
    elif intent == "light_toggle":
        device.toggle()
        logging.info("Light toggled ON/OFF")

def main():
    """Main function to process phrases and control actuators."""
    # Register signal handlers for graceful shutdown
    signal.signal(signal.SIGINT, cleanup_actuators)
    signal.signal(signal.SIGTERM, cleanup_actuators)

    try:
        setup_actuators()
    except GPIOZeroError:
        sys.exit(1)

    try:
        phrases = [
            "turn the pump on",
            "switch the light",
            "turn pump off",
            "unknown command",
        ]
        for phrase in phrases:
            intent = parse_intent(phrase)
            if intent:
                control_actuator(intent, actuators[0] if intent in ("pump_on", "pump_off") else actuators[1])
    except Exception as e:
        logging.error("Unexpected error: %s", e)
    finally:
        cleanup_actuators()

if __name__ == "__main__":
