import signal
import sys
import time
from datetime import datetime
from smbus2 import SMBus, i2c_msg

DS1338_ADDR = 0x68
I2C_BUS = 1

_running = True


def _signal_handler(signum, frame):
    global _running
    _running = False


class DS1338:
    def __init__(self, bus_num=I2C_BUS, addr=DS1338_ADDR):
        self.addr = addr
        self.bus = None
        try:
            self.bus = SMBus(bus_num)
        except OSError as e:
            raise RuntimeError(f"Failed to open I2C bus {bus_num}: {e}") from e

        try:
            self.bus.read_byte_data(self.addr, 0x00)
        except OSError as e:
            self.bus.close()
            self.bus = None
            raise RuntimeError(
                f"No ACK from DS1338 at 0x{addr:02X} on bus {bus_num}: {e}"
            ) from e

    def close(self):
        if self.bus is not None:
            try:
                self.bus.close()
            except OSError:
                pass
            finally:
                self.bus = None

    def _write_reg(self, reg, value):
        if self.bus is None:
            raise RuntimeError("I2C bus is not initialized")
        try:
            self.bus.write_byte_data(self.addr, reg, value & 0xFF)
        except OSError as e:
            raise RuntimeError(
                f"I2C write 0x{reg:02X} failed: {e}"
            ) from e

    def _read_reg(self, reg):
        if self.bus is None:
            raise RuntimeError("I2C bus is not initialized")
        try:
            return self.bus.read_byte_data(self.addr, reg)
        except OSError as e:
            raise RuntimeError(
                f"I2C read 0x{reg:02X} failed: {e}"
            ) from e

    @staticmethod
    def _bcd_to_int(bcd):
        return (bcd >> 4) * 10 + (bcd & 0x0F)

    @staticmethod
    def _int_to_bcd(n):
        return ((n // 10) << 4) | (n % 10)

    def read_seconds(self):
        return self._bcd_to_int(self._read_reg(0x00))

