import serial
import time
import signal
import sys
import re

class ESP8266:
    def __init__(self, port='/dev/serial0', baud_rate=115200, timeout=1.0):
        self.port = port
        self.baud_rate = baud_rate
        self.timeout = timeout
        self.serial = None
        try:
            self.serial = serial.Serial(
                port=port,
                baudrate=baud_rate,
                timeout=timeout,
                write_timeout=timeout
            )
            if not self.serial.is_open:
                raise IOError(f"Failed to open serial port {port}")
        except serial.SerialException as e:
            print(f"Error opening serial port {port}: {e}", file=sys.stderr)
            self.serial = None
            raise

    def _send_command(self, command, timeout=1.0, wait_for=b'OK'):
        if not self.serial or not self.serial.is_open:
            print("Serial port not open", file=sys.stderr)
            return None
        try:
            self.serial.reset_input_buffer()
            self.serial.write(command)
            self.serial.flush()
            response = b''
            start_time = time.time()
            while time.time() - start_time < timeout:
                if self.serial.in_waiting > 0:
                    response += self.serial.read(self.serial.in_waiting)
                    if wait_for in response:
                        break
                time.sleep(0.01)
            return response
        except serial.SerialException as e:
            print(f"Serial communication error: {e}", file=sys.stderr)
            return None

    def test_connection(self):
        response = self._send_command(b'AT')
        return response is not None and b'OK' in response

    def restart(self):
        response = self._send_command(b'AT+RST')
        if b'OK' in response:
            time.sleep(2)
            return self.test_connection()
        return False

    def connect_wifi(self, ssid, password):
        response = self._send_command(b'AT+CWJAP', timeout=10.0, wait_for=b'OK')
        if b'OK' in response:
            return True
        return False

    def disconnect_wifi(self):
        response = self._send_command(b'AT+CWQAP')
        if b'OK' in response:
            return True
        return False

    def get_ip(self):
        response = self._send_command(b'AT+CIFSR')
        if b'+CIFSR:OK' in response:
            match = re.search(r'STAIP:(\S+)', response)
            if match:
                return match.group(1)
        return None

    def send_http_request(self, method, url, host, port=80, headers=None, data=None):
        if not self.serial or not self.serial.is_open:
            print("Serial port not open", file=sys.stderr)
            return None
        try:
            self.serial.reset_input_buffer()
            command = f'AT+CIPSTART="TCP","{host}",{port}\r\n'.encode()
            self.serial.write(command)
            self.serial.flush()
            if b'+CIPSTART:OK' not in self.serial.in_waiting:
                print("Failed to start TCP connection", file=sys.stderr)
                return None
            time.sleep(0.5)
            if not self.serial.in_waiting:
                print("No response from server", file=sys.stderr)
                return None
            request = f'{method} {url} HTTP/1.1\r\nHost: {host}\r\n{headers if headers else ""}\r\n\r\n{data if data else ""}'.encode()
            self.serial.write(request)
            self.serial.flush()
            time.sleep(0.5)
            response = b''
            start_time = time.time()
            while time.time() - start_time < 10.0:
                if self.serial.in_waiting > 0:
                    response += self.serial.read(self.serial.in_waiting)
                    if b'CLOSED' in response:
                        print("Server closed connection", file=sys.stderr)
                        return None
                    if b'ERROR' in response:
                        print("Server error", file=sys.stderr)
                        return None
                    if b'+IPD,' in response:
                        break
                time.sleep(0.01)
            return response
        except serial.SerialException as e:
            print(f"Serial communication error: {e}", file=sys.stderr)
            return None

    def receive_http_response(self, timeout=5.0):
        if not self.serial or not self.serial.is_open:
            print("Serial port not open", file=sys.stderr)
            return None
        try:
            response = b''
            start_time = time.time()
            while time.time() - start_time < timeout:
                if self.serial.in_waiting > 0:
                    response += self.serial.read(self.serial.in_waiting)
                    if b'+IPD,' in response:
                        match = re.search(r'+IPD:(\d+):(.*)', response)
                        if match:
                            return match.group(2)
                        else:
                            print("Invalid +IPD:format", file=sys.stderr)
                            return None
                    if b'CLOSED' in response:
                        print("Connection closed", file=sys.stderr)
                        return None
                    if b'ERROR' in response:
                        print("Error receiving response", file=sys.stderr)
                        return None
                time.sleep(0.01)
            return response
        except serial.SerialException as e:
            print(f"Serial communication error: {e}", file=sys.stderr)
            return None

    def close(self):
        if self.serial and self.serial.is_open:
            try:
                self.serial.close()
            except serial.SerialException as e:
                print(f"Error closing serial port: {e}", file=sys.stderr)

def main():
    esp = None
    def signal_handler(sig, frame):
        if esp:
            esp.close()
        sys.exit(0)
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)
    try:
        esp = ESP8266()
        if esp.test_connection():
            print("ESP8266 connected")
            ip = esp.get_ip()
            if ip:
                print(f"IP address: {ip}")
            else:
                print("Could not get IP address")
        else:
            print("ESP8266 not responding")
    except Exception as e:
        print(f"Initialization error: {e}", file=sys.stderr)
    finally:
        if esp:
            esp.close()

if __name__ == '__main__':
    main()

