import serial
import time
import signal
import sys
from gpiozero import OutputDevice

SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
READ_TIMEOUT = 1.0
ALARM_PIN = 18
RADIATION_THRESHOLD = 50.0
READ_INTERVAL = 1.0

running = True
serial_connection = None
alarm = None

def signal_handler(signum, frame):
    global running
    running = False

def cleanup():
    global serial_connection, alarm
    if serial_connection is not None and serial_connection.is_open:
        try:
            serial_connection.close()
        except Exception:
            pass
    if alarm is not None:
        try:
            alarm.close()
        except Exception:
            pass

def main():
    global serial_connection, alarm

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        serial_connection = serial.Serial(
            SERIAL_PORT,
            BAUD_RATE,
            bytesize=serial.EIGHTBITS,
            parity=serial.PARITY_NONE,
            stopbits=serial.STOPBITS_ONE,
            timeout=READ_TIMEOUT
        )
    except serial.SerialException as e:
        print(f"Error opening serial port {SERIAL_PORT}: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        alarm = OutputDevice(ALARM_PIN, active_high=True, initial_value=False)
    except Exception as e:
        print(f"Error initializing GPIO pin {ALARM_PIN}: {e}", file=sys.stderr)
        cleanup()
        sys.exit(1)

    try:
        while running:
            try:
                raw = serial_connection.readline()
            except serial.SerialException as e:
                print(f"Serial read error: {e}", file=sys.stderr)
                break

            if not raw:
                continue

            line = raw.decode('ascii', errors='replace').strip()
            if not line:
                continue

            try:
                radiation = float(line)
            except ValueError:
                print(f"Warning: non-numeric data received: {line!r}", file=sys.stderr)
                continue

            if radiation > RADIATION_THRESHOLD:
                alarm.on()
            else:
                alarm.off()

            time.sleep(READ_INTERVAL)
    finally:
        cleanup()

if __name__ == '__main__':
    main()

