import serial
import signal
import sys
import logging
from dataclasses import dataclass
from typing import Optional, Tuple

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s - %(levelname)s - %(message)s",
)
logger = logging.getLogger(__name__)


@dataclass
class GPS_readings:
    latitude: Optional[float] = None
    longitude: Optional[float] = None
    altitude: Optional[float] = None
    satellites: Optional[int] = None


class GPSReader:
    def __init__(self, port: str = "/dev/serial0", baudrate: int = 9600, timeout: float = 1.0):
        self.port = port
        self.baudrate = baudrate
        self.timeout = timeout
        self.serial_port: Optional[serial.Serial] = None
        self._running = True

    def connect(self) -> bool:
        try:
            self.serial_port = serial.Serial(
                port=self.port,
                baudrate=self.baudrate,
                bytesize=serial.EIGHTBITS,
                parity=serial.PARITY_NONE,
                stopbits=serial.STOPBITS_ONE,
                timeout=self.timeout,
            )
            logger.info("Connected to GPS on %s at %d baud", self.port, self.baudrate)
            return True
        except serial.SerialException as e:
            logger.error("Failed to open serial port %s: %s", self.port, e)
            self.serial_port = None
            return False

    def disconnect(self) -> None:
        if self.serial_port is not None and self.serial_port.is_open:
            try:
                self.serial_port.close()
                logger.info("Serial port %s closed", self.port)
            except serial.SerialException as e:
                logger.warning("Error closing serial port: %s", e)
        self.serial_port = None

    def _signal_handler(self, signum, frame):
        logger.info("Signal %d received, shutting down", signum)
        self._running = False

    def read_gps_data(self) -> Optional[Tuple[str, GPS_readings]]:
        if self.serial_port is None or not self.serial_port.is_open:
            logger.warning("Serial port not open, cannot read")
            return None

        try:
            raw = self.serial_port.readline()
        except serial.SerialException as e:
            logger.error("Serial read error: %s", e)
            return None

        if not raw:
            logger.warning("Read timeout: no data received")
            return None

        try:
            line = raw.decode("ascii", errors="replace").strip()
        except Exception as e:
            logger.error("Decode error: %s", e)
            return None

        if not line:
            return None

        if not line.startswith("$GPGGA"):
            return None

        parts = line.split(",")
        if len(parts) < 15:
            logger.warning("GPGGA sentence too short: %s", line)
            return None

        try:
            talker = parts[2]
            if talker != "A":
                logger.warning("Invalid GPS talker ID: %s", talker)
                return None

            latitude = self._parse_coordinate(parts[4], parts[5])
            longitude = self._parse_coordinate(parts[6], parts[7])
            altitude = self._parse_coordinate(parts[9], parts[10])
            satellites = int(parts[7])

            return line, GPS_readings(
                latitude=latitude,
                longitude=longitude,
                altitude=altitude,
                satellites=satellites,
            )
        except ValueError as e:
            logger.error("Parse error on GPGGA: %s", e)
            return None
        except IndexError as e:
            logger.error("Index error parsing GPGGA: %s", e)
            return None

    @staticmethod
    def _parse_coordinate(coord_str: str, direction: str) -> Optional[float]:
        if not coord_str or not direction:
            return None
        try:
            deg = float(coord_str[:2])
            minut = float(coord_str[2:])
            decimal = deg + minut / 60.0
            if direction in ("S", "W"):
                decimal = -decimal
            return decimal
        except (ValueError, IndexError):
            return None

    def run(self) -> None:
        signal.signal(signal.SIGINT, self._signal_handler)
        signal.signal(signal.SIGTERM, self._signal_handler)

        if not self.connect():
            logger.error("Cannot start without serial port")
            return

        try:
            while self._running:
                result = self.read_gps_data()
                if result is not None:
                    line, readings = result
                    logger.info("GPS: %s  |  Readings: lat=%.6f, lon=%.6f, alt=%.1f m, sat=%d",
                                line, readings.latitude, readings.longitude, readings.altitude, readings.satellites)
        except Exception as e:
            logger.error("Unexpected error in main loop: %s", e)
        finally:
            self.disconnect()


if __name__ == "__main__":
    reader = GPSReader()
    reader.run()

