class SimpleGPS:
    """
    A class to read and parse GPS data from a serial port on a Raspberry Pi.
    Supports both $GPGGA and $GNGGA sentences from a GPS module.
    """

    def __init__(self, port='/dev/serial0', baudrate=9600, timeout=1.0):
        self.port = port
        self.baudrate = baudrate
        self.timeout = timeout
        self.serial_connection = None
        self._running = True

    def connect(self):
        """Establishes a serial connection to the GPS module."""
        try:
            self.serial_connection = serial.Serial(
                port=self.port,
                baudrate=self.baudrate,
                bytesize=serial.EIGHTBITS,
                parity=serial.PARITY_NONE,
                stopbits=serial.STOPBITS_ONE,
                timeout=self.timeout
            )
            logging.info(f"Connected to GPS on port {self.port} at {self.baudrate} baud.")
            return True
        except serial.SerialException as e:
            logging.error(f"Failed to connect to GPS on {self.port}: {e}")
            self.serial_connection = None
