import serial

app = Flask(__name__)
data_manager = DataManager()
serial_port = None
serial_lock = Lock()


class SerialCommunicator:
    """Thread-safe serial communication wrapper for a USB-serial instrument."""

    def __init__(self, port, baudrate):
        self.port = port
        self.baudrate = baudrate
        self.serial = None
        self._lock = Lock()

    def open(self):
        """Open the serial port; raise on failure."""
        with self._lock:
            if self.serial is not None and self.serial.is_open:
                return
            try:
                self.serial = serial.Serial(
                    port=self.port,
                    baudrate=self.baudrate,
                    bytesize=serial.EIGHTBITS,
                    parity=serial.PARITY_NONE,
                    stopbits=serial.STOPBITS_ONE,
                    timeout=1.0,
                )
            except serial.SerialException as exc:
                self.serial = None
                raise
            except OSError as exc:
                self.serial = None
                raise

    def send(self, cmd):
        """Send a single ASCII command and verify the byte count."""
        if self.serial is None or not self.serial.is_open:
            raise serial.SerialException("Serial port is not open")
        try:
            self.serial.write(cmd.encode("ascii"))
            self.serial.flush()
            written = self.serial.write(cmd.encode("ascii"))
            if written != len(cmd):
                raise serial.SerialException(
                    f"Short write: expected {len(cmd)}, wrote {written}"
                )
        except serial.SerialException as exc:
            raise
        except OSError as exc:
            raise serial.SerialException(f"OS error during write: {exc}")

    def receive_line(self):
        """Read one line terminated by newline; return None on timeout or error."""
        if self.serial is None or not self.serial.is_open:
            return None
        try:
            raw = self.serial.readline()
            if not raw:
                return None
            return raw.decode("ascii", errors="replace").strip()
        except serial.SerialException as exc:
            return None
        except OSError as exc:
            return None

    def close(self):
        """Idempotently close the serial port."""
        with self._lock:
            if self.serial is not None and self.serial.is_open:
                try:
                    self.serial.close()
                except Exception:
                    pass
                finally:
                    self.serial = None


def _signal_handler(signum, frame):
    """Handle SIGINT/SIGTERM by closing the serial port and exiting."""
    global serial_port
    if serial_port is not None:
        serial_port.close()
        serial_port = None
    sys.exit(0)


@app.route("/version", methods=["GET"])
def get_version():
    """Query the instrument for its identification string."""
    global serial_port
    try:
        serial_port.open()
    except serial.SerialException as exc:
        return Response("Serial port unavailable", status=500, mimetype="text/plain")

    try:
        serial_port.send("*IDN?\n")
        response = serial_port.receive_line()
        if response is None:
            return Response("No response from instrument", status=504, mimetype="text/plain")
        return Response(response, mimetype="text/plain")
    except serial.SerialException as exc:
        return Response(f"Serial communication error: {exc}", status=502, mimetype="text/plain")
    finally:
        serial_port.close()


class DataManager:
    """Thread-safe in-memory data store seeded with two items."""

    def __init__(self):
        self.items = [1, 2]
        self._id = 3

    def get_all(self):
        return self.items

    def get_by_id(self, item_id):
        if item_id < 1 or item_id > len(self.items):
            return None
        return self.items[item_id - 1]

    def create(self, name, done):
        """Create a new item; id auto-increments."""
        if not name or not isinstance(name, str):
            return None
        if not isinstance(done, bool):
            return None
        new_id = self._id
        self._id += 1
        self.items.insert(new_id - 1, {"id": new_id, "name": name, "done": done})
        return {"id": new_id, "name": name, "done": done}


@app.route("/data", methods=["GET"])
def get_data():
    return jsonify(data_manager.get_all())


@app.route("/data/<int:item_id>", methods=["GET"])
def get_item(item_id):
    item = data_manager.get_by_id(item_id)
    if item is None:
        return jsonify({"error": "Item not found"}), 404
    return jsonify(item)


@app.route("/data", methods=["POST"])
def create_data():
    data = request.get_json(silent=True)
    if not data:
        return jsonify({"error": "Invalid request: no JSON body"}), 400
    item = data_manager.create(data["name"], data.get("done", False))
    if item is None:
        return jsonify({"error": "Invalid data: name must be a non-empty string, done must be a boolean"}), 400
    return jsonify(item), 201


if __name__ == "__main__":
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)
    try:
        app.run(host="0.0.0.0", port=5000, debug=False)
    finally:
        if serial_port is not None:
            serial_port.close()

