import serial
import time
import sys

SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
READ_TIMEOUT = 1.0
LOOP_DELAY = 1.0


def parse_line(line: str) -> None:
    """Parse a comma-separated line into heart rate and SpO2, print results."""
    parts = line.split(',')
    if len(parts) != 2:
        print(f"Warning: expected 2 fields, got {len(parts)}: '{line}'")
        return
    try:
        heart_rate = int(parts[0].strip())
        spo2 = float(parts[1].strip())
    except ValueError:
        print(f"Warning: non-numeric data: '{line}'")
        return
    print(f"Heart Rate: {heart_rate} bpm, SpO2: {spo2} %")


def main() -> None:
    try:
        ser = serial.Serial(
            port=SERIAL_PORT,
            baudrate=BAUD_RATE,
            bytesize=serial.EIGHTBITS,
            parity=serial.PARITY_NONE,
            stopbits=serial.STOPBITS_ONE,
            timeout=READ_TIMEOUT,
        )
    except serial.SerialException as e:
        print(f"Error opening serial port {SERIAL_PORT}: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        while True:
            try:
                raw = ser.readline()
            except serial.SerialException as e:
                print(f"Serial read error: {e}", file=sys.stderr)
                break

            if not raw:
                # Timeout with no data
                time.sleep(LOOP_DELAY)
                continue

            line = raw.decode('ascii', errors='replace').strip()
            if line:
                parse_line(line)

            time.sleep(LOOP_DELAY)

    except KeyboardInterrupt:
        print("\nExiting program.")
    finally:
        if ser.is_open:
            ser.close()
            print("Serial port closed.")


if __name__ == '__main__':
    main()

