import serial
import time
import sys
from datetime import datetime

SERIAL_PORT = '/dev/serial0'
BAUD_RATE = 9600
TIMEOUT = 1
LOG_FILE = 'power_consumption.log'


def log_power_consumption(power_value: float) -> None:
    """Append a timestamped power reading to the log file."""
    timestamp = datetime.now().strftime('%Y-%m-%d %H:%M:%S')
    entry = f'{timestamp} - Power: {power_value} W\n'
    try:
        with open(LOG_FILE, 'a', encoding='utf-8') as f:
            f.write(entry)
    except OSError as e:
        print(f'Error writing to log file: {e}', file=sys.stderr)


def process_meter_data(data: str) -> None:
    """Parse a serial line and log the power consumption."""
    try:
        power_value = float(data)
        log_power_consumption(power_value)
    except ValueError:
        print(f'Invalid data received (not a float): {data!r}', file=sys.stderr)


def main() -> None:
    """Open the serial port once and read lines until interrupted."""
    try:
        with serial.Serial(
            port=SERIAL_PORT,
