from flask import Flask, Response, request, jsonify
import serial
import time
import threading
import signal
import sys

app = Flask(__name__)

store = [
    {"id": 1, "name": "Sensor 1", "done": False},
    {"id": 2, "name": "Sensor 2", "done": True},
]

ser = None
running = True


def init_serial():
    global ser
    try:
        ser = serial.Serial(
            port="/dev/ttyUSB0",
            baudrate=9600,
            bytesize=serial.EIGHTBITS,
            parity=serial.PARITY_NONE,
            stopbits=serial.STOPBITS_ONE,
            timeout=1,
        )
        if not ser.is_open:
            ser.open()
        print("Serial port /dev/ttyUSB0 opened at 9600 baud.")
    except serial.SerialException as e:
        print(f"Error opening serial port: {e}")
        ser = None


def close_serial():
    global ser
    if ser is not None and ser.is_open:
        try:
            ser.close()
            print("Serial port closed.")
        except serial.SerialException as e:
            print(f"Error closing serial port: {e}")
        finally:
            ser = None


def signal_handler(signum, frame):
    global running
    running = False
    print(f"Signal {signum} received, shutting down...")
    close_serial()
    sys.exit(0)


@app.route("/version")
def version():
    if ser is None or not ser.is_open:
        return Response(
            "Serial port not initialized or unavailable.\n",
            status=503,
            mimetype="text/plain",
        )
    try:
        ser.reset_input_buffer()
        ser.write(b"*IDN?\n")
        time.sleep(0.1)
        response = ser.read(ser.in_waiting or 1024)
        if not response:
            return Response(
                "No response from instrument.\n",
                status=503,
                mimetype="text/plain",
            )
        return Response(response.decode("utf-8", errors="replace").replace("\n", "<br>"), mimetype="text/html")
    except serial.SerialException as e:
        print(f"Serial communication error: {e}")
        return Response(f"Serial error: {e}\n", status=503, mimetype="text/plain")
    except Exception as e:
        print(f"Unexpected error: {e}")
        return Response(f"Internal error: {e}\n", status=500, mimetype="text/plain")


@app.route("/getdata")
def get_data():
    return jsonify(store)


@app.route("/getset/<int:item_id>")
def get_item(item_id):
    item = next((item for item in store if item["id"] == item_id), None)
    if item is None:
        return jsonify({"error": f"Item ID {item_id} not found"}), 404
    return jsonify(item)


@app.route("/getpost/<int:item_id>/<name>")
def post_item(item_id, name):
    item = next((item for item in store if item["id"] == item_id), None)
    if item is None:
        return jsonify({"error": f"Item ID {item_id} not found"}), 404
    new_item = {
        "id": item["id"] + 1,
        "name": name or "",
        "done": item.get("done", False) or (item.get("done", False) == False),
    }
    store.append(new_item)
    return jsonify(store)


@app.route("/postjson", methods=["POST", "GET"])
def post_json():
    if request.method == "POST":
        try:
            data = request.get_json(silent=True) or request.form
            if not isinstance(data, dict):
                return jsonify({"error": "Invalid JSON input"}), 400
            new_item = {
                "id": len(store) + 1,
                "name": data.get("name", ""),
                "done": data.get("done", False) or (data.get("done", False) == False),
            }
            store.append(new_item)
            return jsonify(store)
        except Exception as e:
            print(f"Error processing JSON: {e}")
            return jsonify({"error": str(e)}), 500
    return jsonify(store)


if __name__ == "__main__":
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)
    init_serial()
    try:
        app.run(host="0.0.0.0", port=5000, debug=False)
    finally:
        close_serial()

