import serial
import time
import sys

BLUETOOTH_DEVICE = '/dev/rfcomm4'
BLUETOOTH_BAUDRATE = 38400


def send_command(bluetooth_serial, command_string):
    """Sends a command string to the Bluetooth device with error handling."""
    try:
        command_string = 'X' + command_string + '\n'
        bluetooth_serial.write(command_string.encode('utf-8'))
        bluetooth_serial.flush()
        time.sleep(0.1)  # Add a small delay to avoid flooding the device
        return True
    except serial.SerialException as e:
        print(f"Serial communication error: {e}", file=sys.stderr)
        return False
    except Exception as e:
        print(f"An unexpected error occurred: {e}", file=sys.stderr)
        return False


def main():
    """Main function to handle user input and send commands."""
    bluetooth_serial = None
    try:
        bluetooth_serial = serial.Serial(
            port=BLUETOOTH_DEVICE,
            baudrate=BLUETOOTH_BAUDRATE,
            timeout=1
        )
        print(f"Connected to {BLUETOOTH_DEVICE} at {BLUETOOTH_BAUDRATE} baud.")

        while True:
            try:
                user_command = input('Enter command (or type "exit" to quit): ')
            except EOFError:
                print("\nEOF received, exiting.")
                break

            if user_command.lower() == 'exit':
                break

            if not user_command:
                continue

            if not send_command(bluetooth_serial, user_command):
                print("Failed to send command. Retrying...")

    except serial.SerialException as e:
        print(f"Failed to open serial port: {e}", file=sys.stderr)
        sys.exit(1)
    except KeyboardInterrupt:
        print("\nProgram terminated by user.")
    finally:
        if bluetooth_serial and bluetooth_serial.is_open:
            bluetooth_serial.close()
            print("Serial connection closed.")


if __name__ == "__main__":
    main()

